export const staticFrameworks = [
  { id: "11111111-1111-1111-1111-111111111111", slug: "strategic-decision-making", title: "Strategic Decision-Making", description: "Core frameworks for making high-stakes decisions under uncertainty", category: "decision-making", difficulty: 2, estimated_time_minutes: 45, key_concepts: ["First Principles Thinking", "Inversion", "Second-Order Thinking", "OODA Loop", "Probabilistic Thinking", "Pre-Mortem Analysis"], use_cases: ["Major strategic bets", "M&A decisions", "Market entry", "Crisis response"], content: "", concepts: [{"name": "First Principles Thinking", "definition": "Decompose problems to fundamental truths, rebuild from ground up", "example": "SpaceX: Rockets cost $65M not because that's what they cost, but because of legacy cost structures. First principles: raw materials = 2% of cost. | Elon Musk: Instead of buying rockets for $65M, calculated raw materials cost at 2% of that \u2014 built SpaceX for fraction of cost. | Airbnb founders asked: 'What do travelers really need?' Answer: a place to sleep + local experience. Not another hotel chain.", "tags": ["decision-making", "innovation"], "order_index": 1}, {"name": "Inversion", "definition": "Solve problems by thinking backward from failure", "example": "To avoid project failure: identify all ways it could fail, then design against each. | Charlie Munger: 'Tell me where I'm going to die, so I'll never go there.' Identify failure points first, then avoid them. | Investment: Instead of 'what will make this stock go up?', ask 'what could make it go to zero?' Screen out the disasters.", "tags": ["decision-making", "risk"], "order_index": 2}, {"name": "OODA Loop", "definition": "Observe \u2192 Orient \u2192 Decide \u2192 Act cycle for rapid decision-making", "example": "Startup iterating weekly beats enterprise planning quarterly. | Air Force pilots: Observe enemy position \u2192 Orient to their moves \u2192 Decide counter-maneuver \u2192 Act faster than they can respond. | Startup vs incumbent: Startup ships weekly (fast OODA), incumbent ships quarterly (slow OODA). Startup wins through speed.", "tags": ["decision-making", "speed"], "order_index": 3}, {"name": "Second-Order Thinking", "definition": "Consider cascading effects and unintended consequences. Always ask 'And then what?'", "tags": ["decision-making", "long-term"], "order_index": 4, "example": "Raising prices 20% \u2192 First order: 20% more revenue per customer. Second order: 10% churn, net revenue down. | Hiring 50 engineers fast \u2192 First order: more capacity. Second order: onboarding load slows existing team, net velocity drops. | Cutting R&D to hit quarterly EPS \u2192 First order: profit up. Second order: competitors launch better products in 18 months."}, {"name": "Probabilistic Thinking", "definition": "Think in probabilities and expected value, not absolutes. Update beliefs with new evidence.", "tags": ["decision-making", "uncertainty"], "order_index": 5, "example": "Poker: Don't bet on 'good hands.' Bet when win probability \u00d7 pot size > bet cost. Expected value thinking. | Venture capital: 90% of startups fail. But 1% return 100x. The math: 0.9\u00d70 + 0.09\u00d71x + 0.01\u00d7100x = 1.09x expected return. | Hiring decision: Candidate has 70% chance of success at $200k cost. Expected value: 0.7\u00d7$400k value - $200k = $80k positive."}, {"name": "Pre-Mortem Analysis", "definition": "Imagine the project failed, then work backward to prevent those failures.", "tags": ["decision-making", "risk"], "order_index": 6, "example": "Project Galileo at Apple: 'Assume Newton failed. Why?' Found: no clear target market, supply chain issues. Pivoted before launch. | M&A integration: 'It's 18 months post-acquisition. The deal destroyed $50M in value. What went wrong?' \u2014 then design against those risks. | New market entry: 'We spent $10M and got 0 customers in Germany. Why?' Found: no German-speaking support, GDPR compliance gaps."}] },
  { id: "22222222-2222-2222-2222-222222222222", slug: "financial-mastery", title: "Financial Mastery", description: "Read financial statements, value companies, allocate capital like a CEO", category: "financial", difficulty: 3, estimated_time_minutes: 60, key_concepts: ["EBITDA", "Free Cash Flow", "ROIC", "DuPont Analysis", "DCF Valuation", "LBO Modeling", "Unit Economics", "Cap Table"], use_cases: ["Board presentations", "Fundraising", "M&A evaluation", "Capital allocation", "Pricing strategy"], content: "", concepts: [{"name": "EBITDA", "definition": "Earnings Before Interest, Taxes, Depreciation, Amortization", "formula": "Revenue - COGS - Operating Expenses + D&A", "example": "$100M revenue, $40M COGS, $30M OpEx, $10M D&A = $40M EBITDA (40% margin) | SaaS company: $20M revenue, $8M COGS, $6M OpEx, $2M D&A = $6M EBITDA (30% margin). Excludes $500k interest on debt. | Manufacturing: $50M revenue, $30M materials, $8M labor, $3M D&A = $9M EBITDA. Excludes $4M tax and $1M interest.", "tags": ["financial", "metrics"], "order_index": 1}, {"name": "Free Cash Flow", "definition": "Cash generated after maintaining/growing asset base", "formula": "Operating Cash Flow - Capital Expenditures", "example": "$30M OCF - $8M CapEx = $22M FCF | Apple 2023: $110B operating cash flow - $11B capex = $99B FCF. This funds buybacks, dividends, and R&D. | SaaS startup: $5M OCF - $1M server purchases = $4M FCF. This is cash available for growth or returning to investors.", "tags": ["financial", "metrics", "valuation"], "order_index": 2}, {"name": "ROIC", "definition": "Return on Invested Capital - measures capital efficiency", "formula": "NOPAT / (Total Assets - Excess Cash - Non-Interest Current Liabilities)", "example": "$15M NOPAT / $100M Invested Capital = 15% ROIC. If WACC=10%, creating value. | Company A: $10M NOPAT / $50M invested capital = 20% ROIC. WACC = 10%. Creating value \u2014 every $1 invested generates $2 return. | Company B: $10M NOPAT / $200M invested capital = 5% ROIC. WACC = 10%. Destroying value \u2014 better to return capital to shareholders.", "tags": ["financial", "metrics", "capital-allocation"], "order_index": 3}, {"name": "DuPont Analysis", "definition": "ROE = Net Margin \u00d7 Asset Turnover \u00d7 Financial Leverage. Decomposes what drives returns.", "tags": ["financial", "analysis"], "order_index": 4, "example": "Nike: high margins (brand power) \u00d7 moderate turnover \u00d7 moderate leverage. ROE driven by pricing power, not debt. | Walmart: low margins (discount model) \u00d7 very high turnover (inventory velocity) \u00d7 some leverage. ROE from efficiency, not margin. | Bank: low margins \u00d7 moderate turnover \u00d7 HIGH leverage (10x+). ROE from financial engineering. Very different risk profile."}, {"name": "DCF Valuation", "definition": "Intrinsic value = sum of discounted future free cash flows + terminal value.", "tags": ["financial", "valuation"], "order_index": 5, "example": "Startup: Project 5 years of FCF: -$2M, -$1M, $0, $3M, $10M. Terminal value at 15x = $150M. Discounted at 25% = ~$60M valuation. | Mature company: Stable $100M FCF, 3% growth, 10% discount rate = $100M/(0.10-0.03) = $1.43B terminal value. | Real estate: $50k annual rent, 5% growth, 8% discount, 10 year hold + sale at 6% cap rate = DCF value ~$800k."}, {"name": "LBO Modeling", "definition": "Leveraged Buyout: Sources & Uses, debt schedule, IRR/MOIC at exit.", "tags": ["financial", "m&a"], "order_index": 6, "example": "PE firm buys company for $100M: $40M equity + $60M debt. Grows EBITDA from $12M to $20M in 5 years. Sells at 10x = $200M. Pay off $40M debt. Equity returns: $160M / $40M = 4x MOIC. | Dell/Silver Lake 2013: $24.4B LBO. Used Dell's steady cash flow to pay down debt. Went public again in 2018 at 3x original equity. | Failed LBO: Too much debt (8x EBITDA), recession hits, EBITDA drops 30%, can't service debt. Equity wiped out. Lesson: leverage cuts both ways."}, {"name": "Unit Economics", "definition": "Per-unit revenue minus per-unit cost. LTV/CAC > 3x, payback < 12 months for healthy SaaS.", "tags": ["financial", "saas"], "order_index": 7, "example": "SaaS: CAC = $10k (sales + marketing per customer). LTV = $150/month \u00d7 36 months \u00d7 70% GM = $3,780. LTV/CAC = 0.38 < 1x. Dying business. | Healthy SaaS: CAC = $5k, LTV = $20k. LTV/CAC = 4x. Payback in 12 months. Unit economics work \u2014 invest in growth. | E-commerce: $100 AOV, $30 COGS, $20 shipping, $15 marketing = $35 contribution per order. 2.3 repeat purchases/year means $80 LTV per customer."}, {"name": "Cap Table", "definition": "Ownership through funding rounds. Liquidation preferences, participation rights, dilution.", "tags": ["financial", "fundraising"], "order_index": 8, "example": "Seed: Founders 80%, Seed investors 20% ($2M at $10M post). Series A: $10M at $40M pre = dilution to 60%/15%/25% new. Founders go from 80% to 60%. | Liquidation preference: Series A has 1x non-participating. If company sells for $30M, Series A gets $10M back first. Founders split $20M. | ESOP pool: Create 10% option pool pre-Series A. Dilution hits founders (from 80% to 72%) not investors. Timing matters."}] },
  { id: "33333333-3333-3333-3333-333333333333", slug: "competitive-market-analysis", title: "Competitive & Market Analysis", description: "Frameworks for understanding markets, competition, and positioning", category: "strategy", difficulty: 2, estimated_time_minutes: 45, key_concepts: ["Porter's Five Forces", "SWOT", "VRIO", "BCG Matrix", "Ansoff Matrix", "Blue Ocean", "Jobs-to-be-Done", "Network Effects"], use_cases: ["Market entry", "Competitive response", "Product strategy", "Pricing", "Growth strategy"], content: "", concepts: [{"name": "Porter's Five Forces", "definition": "Analyzes industry competitiveness through five forces", "tags": ["strategy", "competitive-analysis"], "order_index": 1, "example": "Airlines: High rivalry (many competitors), high buyer power (price comparison), high supplier power (Boeing/Airbus duopoly), medium substitutes (trains, video calls), low barriers (anyone can lease planes). Result: terrible industry returns. | Soft drinks (Coke/Pepsi): Low rivalry (duopoly), low buyer power (brand loyalty), low supplier power (commodity ingredients), low substitutes, HIGH barriers (distribution network, brand). Result: 30%+ ROIC. | Streaming (Netflix): Rivalry rising (Disney+, HBO, Apple). Supplier power rising (content costs). Substitutes: YouTube, gaming. Barriers dropping."}, {"name": "VRIO", "definition": "Tests resources for sustainable competitive advantage", "tags": ["strategy", "competitive-advantage"], "order_index": 2, "example": "Coca-Cola brand: Valuable (drives purchase), Rare (one of top 5 global brands), Inimitable (130+ years of marketing can't be copied), Organized (global distribution system). Sustainable competitive advantage. | Google search algorithm: Valuable (80%+ of search ad revenue), Rare (only one at this scale), Inimitable (20+ years of data + engineering), Organized (massive infrastructure). | Generic retailer's 'great customer service': Valuable, not rare (everyone claims it), not inimitable (competitors can copy policies). Temporary parity, not advantage."}, {"name": "Jobs-to-be-Done", "definition": "Customers hire products to do jobs. Understand the job, not the product.", "example": "People don't want a 1/4\" drill bit. They want a 1/4\" hole. | McDonald's milkshake: Morning commuters 'hire' milkshakes to make a boring drive interesting. Not competing with Burger King \u2014 competing with bananas and bagels. | Airbnb: Travelers don't want a hotel room. They want to 'live like a local' and save money. Airbnb competes with hotels AND staying with friends.", "tags": ["strategy", "customer", "product"], "order_index": 3}, {"name": "SWOT", "definition": "Strengths, Weaknesses, Opportunities, Threats. Quick situational assessment matrix.", "tags": ["strategy", "analysis"], "order_index": 4, "example": "Tesla (2020): Strengths: brand, tech lead. Weaknesses: production scaling, cash burn. Opportunities: EV mandates, battery cost decline. Threats: legacy OEMs catching up. | Netflix (2023): Strengths: 230M subs, content library. Weaknesses: rising content costs, password sharing crackdown backlash. Opportunities: ads tier, gaming. Threats: Disney+ bundling. | Local restaurant: Strengths: chef reputation, loyal regulars. Weaknesses: no delivery, small marketing budget. Opportunities: UberEats partnership, catering. Threats: chain restaurant opening nearby."}, {"name": "BCG Matrix", "definition": "Stars, Cash Cows, Question Marks, Dogs. Market Growth \u00d7 Market Share portfolio allocation.", "tags": ["strategy", "portfolio"], "order_index": 5, "example": "Apple: iPhone = Star (high growth, high share). Mac = Cash Cow (low growth, high share). Apple Vision Pro = Question Mark (high growth, low share). iPod = Dog (killed in 2022). | Google: Search ads = Cash Cow (funds everything else). YouTube = Star (still growing). Waymo = Question Mark (huge investment, no profit yet). Google+ = Dog (killed). | Portfolio rebalancing: Use Cash Cow profits to fund Question Marks. If Question Mark can't become Star in 2-3 years, kill it. Don't let Stars starve."}, {"name": "Ansoff Matrix", "definition": "Market Penetration, Development, Product Development, Diversification growth vectors.", "tags": ["strategy", "growth"], "order_index": 6, "example": "Market Penetration: Coca-Cola increasing ad spend in existing US market to gain share from Pepsi. Lowest risk. | Market Development: Netflix expanding from US to 190 countries. Same product (streaming), new geography. Medium risk. | Product Development: Apple adding Apple Watch to existing iPhone customer base. New product, same customers. Medium risk."}, {"name": "Blue Ocean", "definition": "Create uncontested market space: Eliminate, Reduce, Raise, Create.", "tags": ["strategy", "innovation"], "order_index": 7, "example": "Cirque du Soleil: Eliminated animals and star performers (reduced cost). Raised artistic quality and unique venue. Created entirely new market between circus and theater. | Nintendo Wii: Eliminated cutting-edge graphics. Reduced console cost. Raised motion controls and family gaming. Created casual gaming market (non-gamers). | Yellow Tail wine: Eliminated wine jargon and aging claims. Reduced complexity. Raised fun branding and easy-drinking taste. Created market of beer drinkers switching to wine."}, {"name": "Network Effects", "definition": "Product becomes more valuable as more users join. Direct, indirect, data, and platform effects.", "tags": ["strategy", "moat"], "order_index": 9, "example": "Direct: WhatsApp \u2014 each new user makes it more valuable for existing users (more people to message). | Two-sided: Uber \u2014 more riders attract more drivers; more drivers reduce wait times attracting more riders. Self-reinforcing loop. | Data: Google Search \u2014 more searches = more data = better results = more users. Competitors can't replicate 20 years of click data."}] },
  { id: "44444444-4444-4444-4444-444444444444", slug: "organizational-people", title: "Organizational & People", description: "Structure teams, develop talent, build culture, and lead through change", category: "org", difficulty: 3, estimated_time_minutes: 60, key_concepts: ["Org Design (span/layer)", "Nine-Box Grid", "OKRs", "ADKAR Change Management", "Psychological Safety", "Talent Density", "Kotter's 8-Step Change Model"], use_cases: ["Re-org", "Scaling 50 to 500", "Hiring/firing decisions", "Culture transformation"], content: "", concepts: [{"name": "Span of Control", "definition": "Optimal number of direct reports: 7+/3 for complex work, 15+ for simple. Minimize layers.", "tags": ["org", "design"], "order_index": 1, "example": "Engineering VP with 4 Tech Leads (each managing 5-7 engineers) = good span. VP with 15 direct reports = too wide, becomes bottleneck. | Call center: Team leads can manage 15-20 agents (simple, repetitive work). Optimal span depends on task complexity. | Fast-growing startup: CEO with 8 direct reports (product, eng, sales, marketing, finance, people, legal, ops) = too wide. Need COO layer."}, {"name": "Nine-Box Grid", "definition": "Talent review: Performance (Low/Med/High) x Potential (Low/Med/High). Develop, promote, or exit.", "tags": ["talent", "review"], "order_index": 2, "example": "High performer / High potential (box 9): Promote now. Give stretch assignments. Invest in development. Your future VPs. | High performer / Low potential (box 6): Reward and retain. Don't promote out of expertise. They're valuable where they are. | Low performer / Low potential (box 1): Exit with dignity. Draining management attention. Better for them and the company."}, {"name": "Psychological Safety", "definition": "Team members feel safe to take risks and be vulnerable. Google Project Aristotle's top predictor of team success.", "tags": ["culture", "teams"], "order_index": 3, "example": "Google Project Aristotle: Studied 180 teams. Top predictor of success wasn't IQ, experience, or personality \u2014 it was psychological safety. Teams that admit mistakes outperform. | Pixar 'Braintrust': Directors present rough cuts. Everyone gives brutally honest feedback. No rank, no authority \u2014 just making the movie better. Safety to be wrong. | Failed culture: Bridgewater (before fixes). 'Radical transparency' without safety = fear, silence, politics. Safety must come before candor."}, {"name": "OKRs", "definition": "Objectives (inspiring goals) + Key Results (measurable outcomes). 3-5 per quarter.", "tags": ["org", "alignment"], "order_index": 4, "example": "Google: Objective: 'Make the web faster.' KR1: Page load time < 200ms. KR2: 99th percentile < 500ms. KR3: Reduce data usage 25%. Measurable, specific, ambitious. | Startup: O: 'Achieve product-market fit in enterprise segment.' KR1: 10 enterprise pilots. KR2: 3 convert to paid. KR3: NPS > 40 in segment. | Anti-pattern: O: 'Do better at sales.' KR1: 'Try harder.' Not measurable. Not time-bound. Not OKRs. Just wishes."}, {"name": "ADKAR Change Management", "definition": "The Prosci ADKAR model for individual change: Awareness (why change is needed), Desire (personal motivation to change), Knowledge (how to change), Ability (skills to implement change), Reinforcement (sustain the change). Change fails when any element is missing. Diagnose which element is weakest, fix it, then move to the next.", "tags": ["org", "change"], "order_index": 5, "example": "Diagnosing ADKAR: Company rolling out new CRM. Survey employees: Awareness? 80% understand WHY. Desire? 35% want to change (they like the old system). That's the bottleneck \u2014 don't train yet (Knowledge), solve Desire first. Show how new CRM reduces manual data entry by 50% (personal benefit). | Awareness: Not 'management decided to restructure.' But 'our market share dropped 8% and competitors are consolidating. We need to respond.' Context creates awareness. | Reinforcement: Not just celebrating wins. Auditing \u2014 6 months post-change, are people actually using the new process or reverted to old habits? If 30% reverted, reinforcement failed. Diagnose and fix."}, {"name": "Org Design (span/layer)", "definition": "Optimal spans: 7\u00b13 for complex work, 15+ for simple. Minimize layers.", "tags": ["org", "design"], "order_index": 6, "example": "Startup at 50 people: 2 layers (CEO > team leads). Span of 5-7. Flat works at this size. | Scale-up at 200: 3 layers (CEO > VPs > Directors > teams). Spans of 5-8. Need middle management layer. | Enterprise at 2000: 5-6 layers. Spans of 6-10. Too many layers = slow decisions. Too wide spans = overwhelmed managers."}, {"name": "Talent Density", "definition": "Hire and retain only A-players. Adequate performance gets a generous severance.", "tags": ["org", "talent"], "order_index": 7, "example": "Netflix: 'Adequate performance gets a generous severance package.' Keep only A-players. Average performers drag everyone down. | Median team vs elite team: 10 average engineers = 1x output. 5 elite engineers = 5x output. Pay 2x salary for 5x output = rational. | Hiring mistake cost: Bad VP Sales costs $500k salary + $5M missed pipeline + 12 months of team churn. 'Hire slow, fire fast' is a $5M lesson."}, {"name": "Kotter's 8-Step Change Model", "definition": "Kotter's 8-Step framework for leading organizational transformation: 1) Create Urgency 2) Build Guiding Coalition 3) Form Strategic Vision 4) Enlist Volunteer Army 5) Enable Action by Removing Barriers 6) Generate Short-Term Wins 7) Sustain Acceleration 8) Institute Change. The first 4 steps unfreeze the status quo; steps 5-7 introduce new practices; step 8 anchors them in culture.", "example": "Urgency: Nokia CEO Stephen Elop's 'burning platform' memo. 'We are standing on a burning platform.' Created urgency that enabled massive change (partnership with Microsoft). Too little, too late \u2014 but the urgency creation was powerful. | Short-Term Wins: large ERP implementation (24 months). Month 3: automate one department's reporting (saves 5 hours/week). Celebrate. People see progress. Momentum builds. Don't wait 12 months for a win \u2014 create wins every 30-60 days. | Institute Change: after successful transformation, don't declare victory. Kotter: 70% of transformations fail in the last phase \u2014 leaders move on too quickly. Embed new behaviors in performance reviews, hiring criteria, and promotion decisions. Culture = 'the way we do things here.'", "tags": ["org", "change"], "order_index": 8}] },
  { id: "55555555-5555-5555-5555-555555555555", slug: "engineering-product-leadership", title: "Engineering & Product Leadership", description: "Build the right things right with DORA metrics, agile delivery, and technical strategy", category: "engineering", difficulty: 4, estimated_time_minutes: 75, key_concepts: ["DORA Metrics", "SPACE Framework", "RICE/ICE/WSJF Prioritization", "Build vs Buy", "Kano Model", "Tech Debt Management"], use_cases: ["Product roadmap", "Engineering org design", "Platform vs feature investment", "Tech debt vs new features"], content: "", concepts: [{"name": "DORA Metrics", "definition": "Four key metrics: Deployment Frequency, Lead Time, Change Failure Rate, MTTR. Elite performers deploy on-demand with <1hr lead time.", "tags": ["engineering", "metrics"], "order_index": 1, "example": "Elite: Amazon deploys every 11.7 seconds. Lead time < 1 hour. CFR < 15%. MTTR < 1 hour. 1000s of microservices, each team owns deployment. | Low performer: Enterprise deploys quarterly. Lead time 3-6 months. CFR 40%. MTTR 1 week. Monolithic architecture, manual testing. | Improvement journey: From quarterly to weekly deploys = 12x improvement. Required: automated testing, CI/CD pipeline, feature flags."}, {"name": "RICE Prioritization", "definition": "Reach x Impact x Confidence / Effort. Quantify product decisions instead of gut feel.", "example": "Feature A: 1000 users x 3 impact x 80% confidence / 2 weeks effort = 1200 RICE score | Feature A: Reach 5000 users \u00d7 Impact 3 (massive) \u00d7 Confidence 80% / Effort 2 person-weeks = 6000 RICE score. | Feature B: Reach 500 users \u00d7 Impact 1 (low) \u00d7 Confidence 50% / Effort 8 person-weeks = 31 RICE score. Don't build this.", "tags": ["product", "prioritization"], "order_index": 2}, {"name": "Tech Debt Quadrant", "definition": "Categorize debt: Deliberate/Inadvertent x Prudent/Reckless. Pay down reckless debt first, manage prudent debt.", "tags": ["engineering", "tech-debt"], "order_index": 3, "example": "Prudent-Deliberate: 'We know this doesn't scale past 1000 users, but we have 100. Ship now, fix later.' Correct decision. | Reckless-Inadvertent: 'We didn't know that framework was deprecated.' Fair \u2014 learn and fix. Not blameworthy. | Reckless-Deliberate: 'We skipped tests to hit a deadline. We'll never fix them.' Career-limiting. This is negligence."}, {"name": "Build vs Buy", "definition": "Core (strategic differentiator) = build. Context (commodity) = buy or partner.", "tags": ["engineering", "strategy"], "order_index": 4, "example": "Build: Core payment processing (Stripe competitor). Differentiates your product. Risk of buying: vendor lock-in. | Buy: CRM system (Salesforce). Everyone uses it. No differentiation. Focus engineers on your product, not commodity tools. | Partner: AI chatbot for support. Use Intercom + GPT integration. Faster than building, more control than pure buy."}, {"name": "Kano Model", "definition": "Classify features: Basic (must-have), Performance (linear value), Delight (unexpected wow).", "tags": ["product", "prioritization"], "order_index": 5, "example": "Basic (must-have): Hotel room has a bed. If missing, outrage. If present, no delight \u2014 it's expected. | Performance (more is better): Hotel WiFi speed. Faster = happier. Slower = disappointed. Linear relationship. | Delight (unexpected): Hotel leaves handwritten welcome note with local chocolate. Costs $2, creates loyalty. Not expected, so zero downside."}, {"name": "RICE/ICE/WSJF Prioritization", "definition": "RICE = Reach \u00d7 Impact \u00d7 Confidence / Effort. Quantify roadmap decisions.", "tags": ["product", "prioritization"], "order_index": 6, "example": "RICE (Asana/Intercom): Reach \u00d7 Impact \u00d7 Confidence / Effort. Best for mid-stage products with usage data. | ICE (Growth hacking): Impact \u00d7 Confidence \u00d7 Ease. Faster, more intuitive. Best for early-stage when data is limited. | WSJF (SAFe): Weighted Shortest Job First = Cost of Delay / Job Duration. Best for large enterprise with economic framing."}, {"name": "SPACE Framework", "definition": "Satisfaction, Performance, Activity, Communication, Efficiency. Multi-dimensional dev productivity.", "tags": ["engineering", "metrics"], "order_index": 7, "example": "Satisfaction: Developer surveys (eNPS). Performance: DORA metrics. Activity: PR count, code review volume. | Communication: Documentation quality, meeting load. Efficiency: Time to first PR, build times. | Multi-dimensional: Team with high activity but low satisfaction = burnout risk. High performance but low communication = silo risk."}, {"name": "Tech Debt Management", "definition": "Categorize debt: Deliberate/Inadvertent \u00d7 Prudent/Reckless. Fix reckless first.", "tags": ["engineering", "tech-debt"], "order_index": 8, "example": "Allocate 20% of sprint capacity to tech debt (Stripe model). Consistent small investments compound. | Track a 'tech debt ratio': (time spent on maintenance / total eng time). If >30%, halt new features and pay down debt. | Ward Cunningham (creator of term): 'Shipping first-time code is like going into debt. A little debt speeds development \u2014 too much debt crushes it.'"}] },
  { id: "66666666-6666-6666-6666-666666666666", slug: "risk-governance-crisis", title: "Risk, Governance & Crisis", description: "Manage enterprise risk, govern as a board member, and lead through crisis", category: "risk", difficulty: 4, estimated_time_minutes: 60, key_concepts: ["COSO ERM", "ISO 31000", "FMEA", "Crisis Communication", "Board Governance", "Fiduciary Duties", "Turnaround Playbook"], use_cases: ["Risk assessment", "Board preparation", "Crisis response", "M&A integration risk", "Turnaround"], content: "", concepts: [{"name": "FMEA", "definition": "Failure Mode Effects Analysis. Score: Severity x Occurrence x Detection = RPN. Prioritize highest RPN.", "tags": ["risk", "analysis"], "order_index": 1, "example": "Aircraft engine: Failure mode = turbine blade crack. Severity 10 (catastrophic), Occurrence 2 (rare), Detection 4 (inspections catch half). RPN = 80. Prioritize. | Medical device: Failure mode = incorrect dosage display. Severity 9, Occurrence 3, Detection 8 (display test catches most). RPN = 216. Top priority fix. | Not severe: App crashes on obscure edge case affecting 0.01% of users. Severity 2, Occurrence 1, Detection 5. RPN = 10. Fix eventually."}, {"name": "Crisis First Hour", "definition": "Activate team, confirm containment, preserve evidence, draft holding statement, notify board. Speed + accuracy + empathy.", "tags": ["crisis", "response"], "order_index": 2, "example": "Tylenol 1982: 7 deaths from cyanide-laced capsules. Johnson & Johnson recalled 31M bottles within days. Became gold standard for crisis response. | Equifax 2017: 147M records breached. Took 6 weeks to notify. CEO and CIO resigned. $700M settlement. Speed matters. | Buffer 2013: Hacked, spammed users. CEO posted real-time updates on blog every 30 min. No customers left. Transparency saved them."}, {"name": "Business Judgment Rule", "definition": "Presumption that directors acted in good faith if decision was informed, disinterested, and rational.", "tags": ["governance", "legal"], "order_index": 3, "example": "Board approves $50M acquisition after 3 months of diligence, external valuation, and legal review. Deal fails. Directors protected \u2014 they made an informed decision. | Board approves $50M acquisition in a 10-minute call with no documents. Deal fails. No protection \u2014 not an informed decision. | Directors can rely on expert advice (lawyers, bankers, auditors) as long as they reasonably believe the expert is competent."}, {"name": "COSO ERM", "definition": "Governance \u2192 Strategy \u2192 Performance \u2192 Review \u2192 Information. Enterprise risk framework.", "tags": ["risk", "framework"], "order_index": 4, "example": "Governance: Board sets risk appetite (e.g., 'no single customer > 10% of revenue'). Strategy: risk-aware strategic planning. | Performance: Identify risks, assess severity/likelihood, prioritize responses. Review: monitor key risk indicators monthly. | Information: Risk reporting flows from operations \u2192 management \u2192 board. Escalation thresholds defined (red/amber/green KRIs)."}, {"name": "ISO 31000", "definition": "Principles, Framework, Process for risk management. International standard.", "tags": ["risk", "standard"], "order_index": 5, "example": "Principles: Risk management creates value, is part of decision-making, explicitly addresses uncertainty. | Framework: Leadership commitment \u2192 design \u2192 implement \u2192 evaluate \u2192 improve. Continuous cycle. | Process: Scope \u2192 Risk assessment (identify, analyze, evaluate) \u2192 Treatment \u2192 Monitor \u2192 Record. Repeat quarterly."}, {"name": "Crisis Communication", "definition": "Speed (1hr), Accuracy (no speculation), Empathy (people first), Consistency (single source).", "tags": ["crisis", "comms"], "order_index": 6, "example": "Speed: First statement within 1 hour even if just 'We are investigating and will update in 2 hours.' Silence = guilt in public perception. | Accuracy: Never say 'no customer data was affected' until forensics confirms it. If wrong, you lied. Say 'our investigation has not found evidence of...' | Empathy: 'We deeply regret this happened and the concern it causes our customers.' Before explaining what happened, acknowledge the impact on people."}, {"name": "Fiduciary Duties", "definition": "Duty of Care (informed), Loyalty (no self-dealing), Good Faith. Business Judgment Rule.", "tags": ["governance", "legal"], "order_index": 7, "example": "Duty of Care: Director reads board materials before meeting, asks questions, understands the business. Not just showing up. | Duty of Loyalty: Director discloses that their spouse works at a vendor the company is considering. Recuses from vote. No self-dealing. | Duty of Good Faith: Director can't consciously ignore red flags. 'I didn't know about the fraud' doesn't work if you deliberately avoided knowing."}, {"name": "Board Governance", "definition": "Committee charters, board packs, executive sessions, annual evaluation. Skills matrix.", "tags": ["governance", "board"], "order_index": 8, "example": "Audit Committee: Oversees financial reporting, internal controls, external auditor relationship. Must have financial expert member. | Compensation Committee: Sets CEO pay, equity plans, performance metrics. Independent directors only. No management involvement. | Board pack design: 1-page KPI dashboard, 1-page strategic decisions needed, consent agenda (routine approvals), 1 deep-dive topic per meeting."}, {"name": "Turnaround Playbook", "definition": "Stabilize (cash) \u2192 Fix (operations) \u2192 Grow (strategy). 13-week cash flow, restructuring waterfall.", "tags": ["crisis", "turnaround"], "order_index": 9, "example": "Stabilize (0-90 days): 13-week cash forecast, stop non-essential spend, negotiate with creditors, communicate with all stakeholders. | Fix (3-18 months): Restructure operations, exit unprofitable products/lines, right-size workforce, rebuild management team. | Grow (18+ months): Strategic repositioning, enter adjacent markets, rebuild brand, M&A for growth. Only after stabilize and fix are done."}] },
  { id: "77777777-7777-7777-7777-777777777777", slug: "cause-analysis-methods", title: "Cause Analysis Methods", description: "Diagnose root causes with 11 methods from 5 Whys to Causal Inference", category: "analysis", difficulty: 3, estimated_time_minutes: 45, key_concepts: ["5 Whys", "Fishbone / Ishikawa", "Root Cause Analysis", "Fault Tree Analysis", "Causal Loop Diagrams", "Just Culture", "Causal Inference"], use_cases: ["Incident investigation", "Quality problems", "System failures", "Org dysfunction", "Strategic surprises"], content: "", concepts: [{"name": "5 Whys", "definition": "Ask 'Why?' repeatedly until root cause is found (typically 3-5 iterations). Simple, linear causal chains only.", "tags": ["analysis", "simple"], "order_index": 1, "example": "Server crashed. Why? Database overloaded. Why? Spike in queries from reporting feature. Why? Users running large reports simultaneously. Why? No queue system for heavy queries. Why? Report feature built without considering scale. Root cause: no architecture review for new features. | Customer churn. Why? Product too hard to use. Why? Onboarding takes 30 days. Why? Manual setup required. Why? No self-service wizard built. Why? Product team prioritized new features over onboarding. Root cause: misaligned priorities. | Not always 5: 'Why did the project miss deadline?' 'Because we were understaffed.' 'Why?' 'Because hiring is frozen.' Done in 2. The number varies \u2014 stop when you reach a systemic cause, not a person."}, {"name": "Fishbone / Ishikawa", "definition": "Categorize causes: People, Process, Technology, Measurement, Environment, Materials. Teams vote on most likely category.", "tags": ["analysis", "multi-factor"], "order_index": 2, "example": "Manufacturing defect: People (untrained operators), Process (no QA checkpoint), Technology (old machine), Measurement (defect not caught until final), Environment (humidity affecting materials). | Sales miss: People (2 reps on leave), Process (no standardized pitch), Technology (CRM data stale), Measurement (pipeline inflated), Environment (competitor launched free tier). | Never start with 'People' as the cause. Default to Process first. Most problems are process problems, not people problems."}, {"name": "Causal Loop Diagrams", "definition": "Systems thinking tool: map reinforcing (R) and balancing (B) feedback loops with delays. Reveals unintended consequences.", "tags": ["analysis", "systems"], "order_index": 3, "example": "Limits to Growth: Growth \u2192 more customers \u2192 more support tickets \u2192 slower response \u2192 lower satisfaction \u2192 slower growth. Balancing loop eventually dominates. | Success to the Successful: Product A gets more investment (it's successful) \u2192 gets better \u2192 gets more customers \u2192 gets more investment. Product B starves. Self-fulfilling. | Shifting the Burden: Symptom: customer complaints. Quick fix: add more support agents. Symptom returns. Real fix: improve product quality. Quick fix delays real solution."}, {"name": "Root Cause Analysis", "definition": "Define \u2192 Timeline \u2192 Data \u2192 Analyze \u2192 Root Cause \u2192 Solutions \u2192 Verify at 30/90 days.", "tags": ["analysis", "formal"], "order_index": 5, "example": "Formal RCA at NASA: Challenger disaster \u2192 timeline of events \u2192 O-ring failure as proximate cause \u2192 flawed decision-making process as root cause \u2192 redesign launch approval process. | Healthcare RCA: Patient receives wrong medication \u2192 timeline: nurse misread label \u2192 proximate: similar packaging \u2192 root: pharmacy stocked look-alike drugs next to each other \u2192 solution: separate storage. | Enterprise RCA output: 1-page summary with timeline, causal factor chart, root causes (plural), corrective actions (immediate + preventive), verification checkpoint at 90 days."}, {"name": "Fault Tree Analysis", "definition": "Top event \u2192 AND/OR gates \u2192 basic events with probabilities. Quantitative risk assessment.", "tags": ["analysis", "quantitative"], "order_index": 6, "example": "Reactor meltdown FTA: Top event = meltdown. AND gate: loss of cooling AND failure of emergency shutdown. Loss of cooling: pump failure OR power loss OR operator error. Assign probabilities to each basic event. | E-commerce outage: Top event = checkout fails. OR gate: payment processor down OR database timeout OR CDN failure. Each with probability and monitoring. | Probability math: If payment processor fails 0.1% of time and database times out 0.05%, combined probability at OR gate \u2248 0.15%. Not 0.1 + 0.05 = 0.15% (roughly) due to potential overlap."}, {"name": "Just Culture", "definition": "Human error (console) vs at-risk behavior (coach) vs reckless (discipline). Fair judgment.", "tags": ["analysis", "human-factors"], "order_index": 7, "example": "Human error (slip): Nurse accidentally grabs wrong vial (looks identical). Console the person, fix the system (change vial design). | At-risk behavior (drift): Developer skips code review because 'we always skip it when in a rush.' Coach \u2014 this is normalized deviance. Fix the culture that rewards speed over quality. | Reckless behavior: Employee deliberately disables safety system to work faster. Disciplinary action. They knew the risk and chose to ignore it."}, {"name": "Causal Inference", "definition": "Diff-in-diff, IV, regression discontinuity, synthetic control. Prove causation from data.", "tags": ["analysis", "data-driven"], "order_index": 8, "example": "Difference-in-Differences: New return policy in California stores, no change in Nevada. Compare pre/post difference between CA and NV. Removes time trend bias. | Regression Discontinuity: Score above 700 gets credit card approval; below 700 gets rejected. Compare default rates just above and just below 700. Random-like assignment at cutoff. | Instrumental Variable: Want to measure effect of education on income, but ability is a confounder. Use draft lottery number (random, affects education) as instrument."}] },
  { id: "88888888-8888-8888-8888-888888888888", slug: "negotiation-deal-making", title: "Negotiation & Deal-Making", description: "Master the art of getting to yes: from BATNA to integrative bargaining", category: "negotiation", difficulty: 3, estimated_time_minutes: 60, key_concepts: ["BATNA", "ZOPA", "Anchoring", "Integrative Negotiation", "Distributive Negotiation", "Principled Negotiation (Getting to Yes)", "Game Theory / Prisoner's Dilemma", "M&A Deal Structure"], use_cases: ["Fundraising", "M&A negotiation", "Key hires", "Vendor contracts", "Partner deals", "Board-level negotiations"], content: "", concepts: [{"name": "BATNA", "definition": "Best Alternative to a Negotiated Agreement \u2014 your best option if the deal fails. A strong BATNA gives you leverage and confidence.", "example": "Fundraising: Your BATNA is another term sheet at better valuation. Without it, you take whatever first offer comes. | Hiring: Your BATNA is the next-best candidate. The candidate's BATNA is another offer. | Vendor: Your BATNA is a competing supplier quote. Don't negotiate without knowing your BATNA.", "tags": ["negotiation", "strategy"], "order_index": 1}, {"name": "ZOPA", "definition": "Zone of Possible Agreement \u2014 the range between the seller's minimum and buyer's maximum. If no overlap exists, no deal is possible.", "example": "Founder minimum: $8M valuation. Investor maximum: $12M. ZOPA = $8-12M. | Key hire: Min salary $150k, max budget $200k. ZOPA = $50k negotiation range. | M&A: Seller min $100M, buyer max $130M = $30M ZOPA. Both sides should try to capture more of it.", "tags": ["negotiation", "valuation"], "order_index": 2}, {"name": "Anchoring", "definition": "The first number put on the table becomes the reference point \u2014 even if arbitrary. Skilled negotiators use this to shift the range in their favor.", "example": "Salary: Candidate asks $180k first. Employer thinks 'maybe $140-160k'. Even if settled at $155k, candidate got more than if employer opened at $130k. | M&A: Sell-side opens at 12x EBITDA (high anchor). Buyer counters at 6x. Settle at 8-9x. Without anchor, settle at 7x. | Venture: Founder asks for $10M at $40M pre. VC counters $6M at $25M pre. Anchor set the reference.", "tags": ["negotiation", "psychology"], "order_index": 3}, {"name": "Integrative Negotiation", "definition": "Expand the total value available, not just divide a fixed pie. Focus on interests (why they want something), not positions (what they say they want). Creates win-win outcomes.", "example": "Two sisters fighting over one orange. Position: each wants the whole thing. Interest: one wants the peel for baking, other wants juice for drinking. Both can get 100% of what they need. | Employee wants remote work (interest: flexibility). Company wants office presence (interest: collaboration). Solution: 3 days office, 2 remote + quarterly in-person weeks. | Supplier wants longer contract (interest: stability). Buyer wants lower price (interest: cost). Solution: 5-year contract at 10% annual discount.", "tags": ["negotiation", "win-win"], "order_index": 4}, {"name": "Distributive Negotiation", "definition": "Dividing fixed value \u2014 one side's gain is the other's loss. Used when interests are directly opposed or relationship is transactional.", "example": "Car purchase: dealer wants highest price, buyer wants lowest. Every dollar is zero-sum. | Licensing deal: fixed royalty rate negotiation. 5% vs 7% = $2M difference in a $100M deal. | Severance negotiation: employee wants 6 months pay + benefits. Company wants 3 months. Fixed pie, claim value.", "tags": ["negotiation", "zero-sum"], "order_index": 5}, {"name": "Principled Negotiation (Getting to Yes)", "definition": "Fisher & Ury's 4-point framework: 1) Separate people from problem 2) Focus on interests, not positions 3) Generate options for mutual gain 4) Insist on objective criteria.", "example": "People vs problem: 'I'm frustrated by the delay' not 'You're incompetent.' | Interests: 'We need payment certainty' not 'Pay within 30 days.' The interest can be met in multiple ways. | Options: Brainstorm before evaluating. 'What if we tried X? What about Y?' | Objective criteria: 'Industry standard royalty is 5-8%' not 'I think 5% is fair.' External benchmarks reduce emotion.", "tags": ["negotiation", "framework"], "order_index": 6}, {"name": "Game Theory / Prisoner's Dilemma", "definition": "Mathematical framework for strategic decision-making where outcomes depend on others' choices. Prisoner's Dilemma shows why cooperation can fail even when it benefits both parties.", "example": "Two suspects, no communication. Both stay silent = 1 year each. Both confess = 5 years each. One confesses while other stays silent = confesse goes free, silent gets 10 years. Rational self-interest leads to 5 years each, worse than cooperation. | In business: PRICE WAR. Both keep prices high = both profitable. One cuts prices = gains share (temporarily). Both cut = both lose margin. | OPEC: Each country benefits from cheating on quotas, but if all cheat, oil price collapses. Tit-for-tat strategy: cooperate first, then mirror opponent's last move.", "tags": ["strategy", "game-theory"], "order_index": 7}, {"name": "M&A Deal Structure", "definition": "The architecture of an acquisition: cash vs stock, earnouts, holdbacks, representations & warranties, indemnification, closing conditions. Structure often matters more than price.", "example": "Cash deal: $100M at close. Clean, simple. Seller bears no future risk. | Earnout: $60M at close + $40M if targets hit over 3 years. Aligns incentives, protects buyer. | Stock deal: Buyer issues shares instead of cash. Seller's risk tied to buyer's future performance. | Indemnification cap: Seller's liability capped at 15% of deal value. Anything above = buyer's risk. Anything below = seller's reps & warranties insurance.", "tags": ["m-a", "deal-structure"], "order_index": 8}] },
  { id: "99999999-9999-9999-9999-999999999999", slug: "innovation-rd-management", title: "Innovation & R&D Management", description: "Turn ideas into growth: from disruptive innovation to lean experimentation", category: "innovation", difficulty: 3, estimated_time_minutes: 45, key_concepts: ["Disruptive Innovation", "Crossing the Chasm", "Lean Startup / Build-Measure-Learn", "Design Thinking", "Stage-Gate Process", "Ambidextrous Organization", "Technology S-Curve", "Innovator's Dilemma"], use_cases: ["R&D investment decisions", "Entering new markets", "Corporate innovation", "Startup incubation", "Product roadmap"], content: "", concepts: [{"name": "Disruptive Innovation", "definition": "Clayton Christensen's theory: incumbents focus on best customers and ignore simpler, cheaper alternatives. Disruptors start at the low end and move upmarket until they overtake incumbents.", "example": "Netflix: Started mailing DVDs (low end). Blockbuster ignored it (their customers wanted same-day rentals). Netflix moved to streaming. Blockbuster went bankrupt. | Tesla: Started with Roadster (niche sports car). Incumbents ignored. Model S (luxury sedan). Still ignored. Model 3 (mass market). Now threatening all automakers. | Cloud computing: AWS started with simple storage (low end, cheap). Enterprise ignored ('not secure enough'). Now AWS powers Netflix, Airbnb, and the Pentagon.", "tags": ["innovation", "strategy"], "order_index": 1}, {"name": "Crossing the Chasm", "definition": "Geoffrey Moore's model: innovations succeed with early adopters but fail to reach the mainstream 'early majority' \u2014 the gap between them is 'the chasm.' Crossing requires a focused 'beachhead' strategy.", "example": "Technology adoption lifecycle: Innovators (2.5%) \u2192 Early Adopters (13.5%) \u2192 [THE CHASM] \u2192 Early Majority (34%) \u2192 Late Majority (34%) \u2192 Laggards (16%). | Crossing the chasm: Don't try to sell to everyone. Pick ONE niche, dominate it 100%, use it as reference to expand. | Salesforce in 1999: Didn't sell to 'all enterprises.' Targeted SMB sales teams in tech companies. Became reference. Expanded to all teams, all industries.", "tags": ["innovation", "go-to-market"], "order_index": 2}, {"name": "Lean Startup / Build-Measure-Learn", "definition": "Eric Ries' methodology: Ship a minimum viable product (MVP), measure real customer behavior (not surveys), learn from data, and iterate rapidly. Speed of learning > perfection.", "example": "Zappos MVP: Founder didn't build a warehouse or buy inventory. Took photos of shoes at local stores, posted online. If someone bought, he'd go buy the shoes and ship them. Validated demand before investing. | Dropbox MVP: A 3-minute video demo (not actual product). Got 75,000 sign-ups overnight from the waiting list. Proved demand without writing code. | Build-Measure-Learn cycle: Build minimum test \u2192 Measure real customer data \u2192 Learn (pivot or persevere) \u2192 Repeat. Time per cycle: days, not months.", "tags": ["innovation", "lean"], "order_index": 3}, {"name": "Design Thinking", "definition": "Human-centered innovation process: Empathize (understand users) \u2192 Define (frame the problem) \u2192 Ideate (brainstorm solutions) \u2192 Prototype (build rough versions) \u2192 Test (get feedback). Iterate.", "example": "IDEO redesigning shopping carts: Empathized by watching shoppers, interviewing employees. Defined the problem: safety, maneuverability, checkout speed. Ideated hundreds of concepts. Prototyped rapidly. Tested in real stores. Result: modular cart with child seat, scanner, and nesting design. | Airbnb turnaround: Founders 'lived' as Airbnb guests. Realized poor photos were killing bookings. Flew to NYC, took professional photos for hosts. Bookings doubled. Problem was photography, not the platform.", "tags": ["innovation", "design"], "order_index": 4}, {"name": "Stage-Gate Process", "definition": "Structured innovation funnel: Ideas enter, pass through gates (go/kill decisions) at each stage. Reduces risk by killing bad ideas early before heavy investment.", "example": "Stages: Discovery (idea generation) \u2192 Gate 1: Is it aligned with strategy? \u2192 Scoping (quick assessment) \u2192 Gate 2: Does market exist? \u2192 Business Case (detailed analysis) \u2192 Gate 3: Is ROI sufficient? \u2192 Development \u2192 Gate 4: Is product ready? \u2192 Testing/Validation \u2192 Gate 5: Launch ready? \u2192 Launch. | Pharmaceutical: ~10,000 compounds \u2192 250 pre-clinical \u2192 5 clinical trials \u2192 1 approved drug. Stage-Gate kills 99.99% before heavy costs. | Gates are decisions: Go (fund next stage), Kill (stop), Hold (wait for more data), Recycle (revise and resubmit).", "tags": ["innovation", "process"], "order_index": 5}, {"name": "Ambidextrous Organization", "definition": "Simultaneously exploit (optimize current business for efficiency) AND explore (experiment with new opportunities). Requires separate structures, processes, and cultures for each.", "example": "Exploit: Quarterly targets, efficiency metrics, Six Sigma, cost reduction. Run by operational managers. | Explore: Long time horizons, tolerate failure, small autonomous teams, venture-style funding. Run by entrepreneurial leaders. | Amazon: Exploit = retail operations (fulfillment optimization, pricing algorithms). Explore = AWS (started as internal tool, now $90B). Bezos kept AWS separate from retail \u2014 different culture, different metrics. | Failure mode: Using exploit metrics on explore teams kills innovation ('this R&D project has no ROI after 6 months').", "tags": ["innovation", "org-design"], "order_index": 6}, {"name": "Technology S-Curve", "definition": "Technologies follow an S-curve: slow initial progress, rapid improvement, then diminishing returns as limits are reached. Timing the jump to the next S-curve is the CEO's job.", "example": "Hard disk drives: 14-inch \u2192 8-inch \u2192 5.25-inch \u2192 3.5-inch. Each new format started worse than the optimized old format, then surpassed it. Incumbents missed each transition. | Electric vehicles: ICE engines at top of S-curve (diminishing returns on efficiency). Battery tech climbing steep part of S-curve (rapid improvement). | CEO's task: Monitor when current technology approaches its limits. Invest in next S-curve BEFORE the current one peaks. Too early = wasted investment. Too late = extinction.", "tags": ["innovation", "technology"], "order_index": 7}, {"name": "Innovator's Dilemma", "definition": "Successful companies fail NOT because of bad management, but BECAUSE of good management. Listening to current customers, investing in highest-margin products, and optimizing for current market all prevent investing in disruptive technologies.", "example": "Kodak invented digital photography in 1975. Didn't pursue it \u2014 would cannibalize film business (80% gross margin). Customers didn't want digital (yet). By 2012, Kodak bankrupt. | Why good management fails: 1) Disruptive tech starts in small, unprofitable markets 2) Current customers don't want it 3) Margins look worse than existing products 4) All 'rational' analysis says 'don't invest.' Solution: Create a separate unit to pursue disruption, protected from core business metrics.", "tags": ["innovation", "strategy"], "order_index": 8}] },
  { id: "aaaaaaaa-aaaa-aaaa-aaaa-aaaa00000001", slug: "business-model-strategy", title: "Business Model & Strategy Design", description: "Design, analyze, and evolve your business model with proven strategic frameworks", category: "strategy", difficulty: 2, estimated_time_minutes: 45, key_concepts: ["Business Model Canvas", "Porter's Generic Strategies", "Core Competency", "Strategy Map", "Balanced Scorecard", "Gap Analysis", "OGSM Framework", "MECE Principle"], use_cases: ["Strategy retreats", "Business model innovation", "Investor pitch preparation", "Annual planning", "Organizational alignment", "Performance measurement"], content: "", concepts: [{"name": "Business Model Canvas", "definition": "Alexander Osterwalder's one-page framework mapping 9 building blocks of any business model. Used to design, analyze, and pivot business models rapidly.", "example": "Uber canvas: Value prop = Tap button, get ride. Customers = Urban riders + drivers. Revenue = 25% commission. Key resources = Platform, driver network. Key partners = Drivers (not employees). Cost structure = Engineering, marketing, insurance. | Airbnb canvas: Value prop = Live like a local, earn from extra space. Customers = Travelers + hosts. Revenue = 3% host fee + 6-12% guest fee. Key resources = Trust system (reviews, verification). Key partners = Hosts (not hotel owners). | Pivot example: YouTube started as video dating site ('Tune In, Hook Up'). Pivot to 'Broadcast Yourself' after zero traction. Canvas reveals pivot opportunities.", "tags": ["strategy", "business-model"], "order_index": 1}, {"name": "Porter's Generic Strategies", "definition": "Three fundamental competitive positions: Cost Leadership (lowest cost in industry), Differentiation (unique value customers pay premium for), and Focus (serve a narrow segment extremely well). Being 'stuck in the middle' is the worst position.", "example": "Cost Leadership: Walmart. Massive scale, efficient supply chain, lean operations. Every decision optimizes for lower cost. | Differentiation: Apple. Design, ecosystem, brand, user experience. Premium pricing (40%+ gross margin). Not the cheapest, but customers pay more willingly. | Focus: Ferrari (focused differentiation \u2014 luxury sports cars). Southwest Airlines (focused cost leadership \u2014 point-to-point, single aircraft type, no frills domestic). | Stuck in the middle: Sears. Not as cheap as Walmart, not as nice as Target. Failed both ways.", "tags": ["strategy", "competitive-positioning"], "order_index": 2}, {"name": "Core Competency", "definition": "Prahalad & Hamel: A unique capability that provides access to wide markets, contributes significantly to customer perceived value, and is difficult for competitors to imitate. Strategy should be built around competencies, not products.", "example": "Honda's core competency: small engine design and manufacturing. Products: motorcycles, cars, lawn mowers, generators, marine engines, jets. All built on the same competency. | Canon's core competency: precision optics, imaging, and microelectronics. Products: cameras, copiers, printers, medical imaging. | 3M: Competency in adhesives and materials science. Products: Post-it notes, Scotch tape, medical tapes, abrasives, reflective materials. Thousands of products, one core skill.", "tags": ["strategy", "capabilities"], "order_index": 3}, {"name": "Balanced Scorecard", "definition": "Kaplan & Norton: Translates strategy into measurable objectives across 4 perspectives \u2014 Financial, Customer, Internal Process, Learning & Growth. Prevents over-focusing on financial metrics alone.", "example": "Financial: 'How do we look to shareholders?' Revenue growth, ROIC, cash flow, margins. | Customer: 'How do customers see us?' NPS, retention, market share, customer acquisition cost. | Internal Process: 'What must we excel at?' Quality, cycle time, innovation rate, operational efficiency. | Learning & Growth: 'How do we sustain innovation?' Employee skills, satisfaction, IT systems, culture. | Strategy map: If we invest in people (L&G) \u2192 they improve processes (Internal) \u2192 customers are happier (Customer) \u2192 financials improve (Financial). Causal chain.", "tags": ["strategy", "measurement"], "order_index": 4}, {"name": "Strategy Map", "definition": "Visual representation of an organization's strategy showing cause-and-effect relationships between objectives across the Balanced Scorecard perspectives. One-page strategy communication tool.", "example": "FedEx Strategy Map: L&G: Hire right people, improve IT \u2192 Internal: On-time delivery 99.9%, handle exceptions fast \u2192 Customer: 'Absolutely, positively overnight' reputation \u2192 Financial: Premium pricing (FedEx charges 30%+ more than competitors). | Start with financial target (what result), work backward through customer value proposition, critical internal processes, and required capabilities. | Every objective on the map should connect to at least one other in a causal chain. If an objective doesn't connect, it's not strategic.", "tags": ["strategy", "visualization"], "order_index": 5}, {"name": "Gap Analysis", "definition": "Identify the gap between current state and desired future state, then develop strategies to close it. Systematic performance improvement planning.", "example": "Revenue gap: Current $10M ARR, target $50M in 3 years. Gap = $40M. Break into: organic growth ($20M), new products ($10M), market expansion ($10M). Each gets its own strategy. | Capability gap: Need AI/ML but have no data scientists. Gap closure options: hire (6 months, $500k/year), acquire small AI startup (3 months, $5M), partner with AI platform (1 month, revenue share). | Process: Define current state \u2192 Define desired state \u2192 Identify root causes of gap \u2192 Generate options \u2192 Select and implement.", "tags": ["strategy", "planning"], "order_index": 6}, {"name": "OGSM Framework", "definition": "Objective, Goals, Strategies, Measures. A one-page strategic planning framework used by P&G, Coca-Cola, and Mars. Bridges vision (Objective) to execution (Measures) with clear accountability.", "example": "Objective (qualitative, inspiring): 'Be the #1 healthy snack brand in US schools.' | Goals (quantitative, time-bound): 20% market share by 2027, $500M revenue, available in 10,000 schools. | Strategies (how to achieve goals): Partner with school districts (#1), launch kid-friendly packaging (#2), influencer marketing campaign (#3). | Measures (KPIs per strategy): # school district contracts signed, product placement in vending machines, social media impressions. | Entire OGSM fits on one page. Every employee can see how their work connects to company objectives.", "tags": ["strategy", "planning"], "order_index": 7}, {"name": "MECE Principle", "definition": "Mutually Exclusive, Collectively Exhaustive. A problem-structuring principle from McKinsey: categories must not overlap (no double counting) and must cover everything (no gaps).", "example": "Revenue analysis: Break down by product line (ME: each product is separate, CE: all products covered). Not by product AND region (overlap). | Customer segmentation: Enterprise (1000+ employees), Mid-market (100-999), SMB (1-99). Is this MECE? Yes \u2014 no employee count falls in two segments, all possible counts are covered. | Common MECE structures: Profit = Revenue - Cost (mathematical). Revenue = Price \u00d7 Quantity (algebraic). Market = Segment A + Segment B + Segment C (process).", "tags": ["strategy", "problem-solving"], "order_index": 8}] },
  { id: "bbbbbbbb-bbbb-bbbb-bbbb-bbbb00000001", slug: "operations-quality-management", title: "Operations & Quality Management", description: "Drive operational excellence through lean, quality, and constraint management", category: "operations", difficulty: 3, estimated_time_minutes: 45, key_concepts: ["Six Sigma / DMAIC", "Theory of Constraints", "Lean Manufacturing / TPS", "Just-in-Time (JIT)", "Hoshin Kanri / Policy Deployment", "Pareto Principle (80/20)", "Statistical Process Control", "Total Quality Management (TQM)"], use_cases: ["Process improvement", "Cost reduction", "Quality programs", "Manufacturing optimization", "Service operations", "Supply chain management"], content: "", concepts: [{"name": "Six Sigma / DMAIC", "definition": "Data-driven methodology to eliminate defects and reduce variation. DMAIC: Define (problem), Measure (current performance), Analyze (root causes), Improve (implement solutions), Control (sustain gains). Goal: 3.4 defects per million.", "example": "Define: What is the problem? (ER wait times too long). Measure: How bad is it? (Average 287 min). Analyze: Why? Root cause = lab turnaround is 42% of wait. Improve: What fixes it? Dedicated ER lab tech, 15-min SLA. Control: How do we sustain? Daily dashboard, alert at 20 min. Result: wait time 287\u2192126 min.", "tags": ["operations", "quality"], "order_index": 1}, {"name": "Theory of Constraints", "definition": "Eliyahu Goldratt: Every system has ONE bottleneck that limits throughput. Improve the bottleneck, improve the whole system. Improve anything else = wasted effort.", "example": "Factory: Machine #3 is the bottleneck (15 units/hour, while others do 25). Adding capacity to Machine #1 does nothing \u2014 parts just pile up at Machine #3. Fix the bottleneck first. | 5 focusing steps: 1) IDENTIFY constraint (Machine #3) 2) EXPLOIT it (no idle time, preventive maintenance) 3) SUBORDINATE everything else (don't feed Machine #3 faster than 15/hr) 4) ELEVATE the constraint (add second Machine #3) 5) REPEAT \u2014 now find the new bottleneck. | Software team: If QA is the bottleneck, having developers code faster just increases the testing backlog. Fix QA capacity first.", "tags": ["operations", "constraints"], "order_index": 2}, {"name": "Lean Manufacturing / TPS", "definition": "Toyota Production System: Eliminate all waste (muda) \u2014 overproduction, waiting, transport, over-processing, inventory, motion, defects. Produce exactly what's needed, when needed, in the amount needed.", "example": "Toyota: Just-in-Time production \u2014 parts arrive exactly when needed, not before (reduces inventory waste). Jidoka \u2014 machines stop automatically when a defect is detected (prevents defect propagation). Kaizen \u2014 every worker can stop the line and suggest improvements (600,000 improvement suggestions/year). | 7 wastes (TIMWOOD): Transport, Inventory, Motion, Waiting, Overproduction, Over-processing, Defects. | Lean in software: Continuous deployment (reduce WIP), automated testing (reduce defect waste), pair programming (reduce waiting).", "tags": ["operations", "lean"], "order_index": 3}, {"name": "Pareto Principle (80/20)", "definition": "80% of effects come from 20% of causes. Applied to operations: 80% of quality issues from 20% of defect types, 80% of revenue from 20% of customers, 80% of delays from 20% of process steps. Focus on the vital 20%.", "example": "Quality: 80% of customer complaints caused by 3 out of 50 product defects. Fix those 3 first. | Revenue: 80% of revenue from 20% of customers. Give those 20% white-glove treatment. | Inventory: 80% of inventory value in 20% of SKUs. Optimize those first. | Time management: 80% of results from 20% of activities. Identify and protect that 20%. Delegate or eliminate the rest. | Pareto chart: Bar chart sorted by frequency + cumulative % line. Visually identifies the vital few vs trivial many.", "tags": ["operations", "prioritization"], "order_index": 4}, {"name": "Just-in-Time (JIT)", "definition": "Inventory strategy: materials arrive exactly when needed in production, not before. Reduces carrying costs, reveals process problems (no buffer inventory hides issues), and forces quality improvements.", "example": "Toyota: Parts arrive 4 hours before assembly. No warehouse. If a part is defective, production stops \u2014 the problem is visible immediately and gets fixed. | Dell in 1990s: Build-to-order model. No finished goods inventory. Customer orders, Dell builds. Components arrive JIT. Cash conversion cycle was NEGATIVE (got paid before paying suppliers). | Risk: JIT breaks when supply chains break. COVID showed this \u2014 2-week inventory buffer vs 2-hour. Balance JIT with strategic buffers for critical components.", "tags": ["operations", "inventory"], "order_index": 5}, {"name": "Hoshin Kanri / Policy Deployment", "definition": "Japanese strategic planning process that aligns company-wide objectives (what) with daily management (how). Cascading goals from CEO to front line with catchball (two-way negotiation) at each level.", "example": "CEO: 'Improve quality 50% this year' (hoshin). VP Engineering interprets: 'Reduce defect rate from 2% to 1%.' Director: 'Implement automated testing for top 10 defect types.' Team lead: 'Write test suite for Module X, target 0.5% defect rate.' | Catchball: The team lead pushes back: 'Need 2 more weeks for Module X, but can deliver Module Y earlier.' The negotiation goes back up the chain. | Hoshin Review: Monthly reviews using A3 reports (one-page problem-solving documents). Green (on track), Yellow (at risk), Red (off track \u2014 needs escalation).", "tags": ["operations", "strategy"], "order_index": 6}, {"name": "Statistical Process Control", "definition": "Monitor process performance with control charts. Upper and lower control limits (typically \u00b13 sigma). Points outside limits = special cause (investigate). Points within limits = common cause (process is stable).", "example": "Manufacturing: part diameter measured hourly. UCL = 10.2mm, LCL = 9.8mm. Reading at 11am: 10.5mm \u2014 outside UCL. Investigate: machine calibration drifted. Fix before producing defects. | Call center: average handle time chart. Sudden spike at 2pm \u2014 special cause (system outage). Don't retrain agents \u2014 fix the outage. | Rule of 7: seven consecutive points on one side of the mean (even within limits) also signals a process shift. Statistical, not random.", "tags": ["operations", "quality"], "order_index": 7, "formula": null}, {"name": "Total Quality Management (TQM)", "definition": "Organization-wide commitment to quality: customer focus, continuous improvement, employee involvement, process-centered, data-driven. Everyone owns quality, not just QA department.", "example": "Toyota: any worker can stop the assembly line if they spot a defect. Quality is everyone's job. | Ritz-Carlton: every employee can spend up to $2000 to solve a guest problem without manager approval. Empowers quality at the front line. | TQM principles: 1) Customer defines quality 2) Prevention over inspection 3) Continuous improvement (Kaizen) 4) Fact-based decision making 5) Everyone participates. | Deming's 14 Points: core TQM philosophy \u2014 'cease dependence on inspection to achieve quality.'", "tags": ["operations", "quality"], "order_index": 7, "formula": null}] },
  { id: "cc000001-0000-4000-8000-000000000001", slug: "decision-tree-analysis", title: "Decision Tree Analysis", description: "Map decisions as branching paths with probabilities and payoffs — calculate expected value at each node to identify the optimal choice", category: "analysis", difficulty: 2, estimated_time_minutes: 30, key_concepts: ["Decision Nodes vs Chance Nodes", "Expected Value Calculation", "Bayesian Updating in Trees", "Sensitivity at Decision Nodes", "Value of Information", "Real Options in Decision Trees"], use_cases: ["Make vs buy decisions", "Market entry (go/no-go)", "R&D portfolio allocation", "Litigation settle vs fight", "Investment under uncertainty"], content: "", concepts: [{"name": "Expected Value Calculation", "definition": "Multiply each possible outcome by its probability and sum them. The weighted average result \u2014 use this to compare choices objectively.", "example": "Build product: 40% chance of $10M success + 60% chance of -$3M failure = EV of $2.2M. | Acquire competitor: 70% chance of $6M + 30% chance of -$5M = EV of $2.7M. Acquire has higher EV. | Add 'value of waiting' option: gather 3 months of intel at $500k cost, then decide with better info. EV with intel: $3.5M. Wait.", "tags": ["analysis", "decision-making"], "order_index": 1}, {"name": "Decision Nodes vs Chance Nodes", "definition": "Decision nodes (squares) = you choose the path. Chance nodes (circles) = the universe chooses, with probabilities you estimate. Separate what you control from what you don't.", "example": "Square: 'Launch product A or product B?' You decide. | Circle: 'Market reaction: strong (30%), moderate (50%), weak (20%).' The market decides. | Mistake: treating competitor response as a chance node (it's actually a decision node for THEM \u2014 game theory applies, not probability).", "tags": ["analysis", "decision-making"], "order_index": 2}, {"name": "Value of Information", "definition": "How much should you pay to reduce uncertainty before deciding? Calculate: EV with perfect information minus EV without it. If cost < value, buy the information.", "example": "EV of decision today (with uncertainty) = $5M. EV if you knew the outcome in advance (and could always choose optimally) = $8M. Value of perfect information = $3M. | Market research costs $200k \u2014 will it improve your EV by more than that? Calculate the uplift and compare. | Don't confuse value of information with cost of analysis. The value is the DECISION IMPROVEMENT, not the report cost.", "tags": ["analysis", "decision-making"], "order_index": 3}, {"name": "Real Options in Decision Trees", "definition": "Some decisions create future flexibility (options). An option to expand, abandon, or defer has value \u2014 include it in the tree.", "example": "Pilot project costs $2M. If successful (60%), expand for $10M to capture $30M. If fail (40%), abandon at $0 loss beyond pilot. EV = 0.6\u00d7($30M-$10M) + 0.4\u00d7(-$2M) = $12M - $0.8M = $11.2M. | The option to abandon limits downside. The option to expand captures upside. | Amazon's 'two-way door' decisions: easily reversible decisions don't need deep analysis. Use trees for one-way doors.", "tags": ["analysis", "strategy"], "order_index": 4}, {"name": "Bayesian Updating in Trees", "definition": "As new information arrives, update the probabilities at chance nodes. Bayes' Theorem: posterior probability = prior \u00d7 likelihood / evidence. Trees are living models, not static artifacts.", "example": "Initial: 30% chance market is large. Run pilot, get positive signal. Bayes update: now 55% chance. Recalculate EV \u2014 does the decision change? | Drug trial: prior probability of efficacy = 20%. Phase 1 results positive (likelihood ratio = 3). Posterior = 43%. Worth proceeding to Phase 2. | Board: 'What if the pilot results are disappointing?' Update the tree with that data. The decision may flip from Go to No-Go. That's the VALUE of the pilot.", "tags": ["analysis", "probability"], "order_index": 5, "formula": null}, {"name": "Sensitivity at Decision Nodes", "definition": "At each decision node, test: if the probability at the next chance node changes by 10%, does the optimal decision change? Nodes where a small change flips the decision are your key uncertainties.", "example": "Decision A has EV = $5M. Decision B has EV = $4.8M. If success probability for A drops 5%, EV falls to $4.2M. Decision flips to B. That probability is your sensitivity point. Investigate it. | Tornado + Decision Tree combo: run tornado on key probabilities in the tree. Which probabilities dominate the decision? | CEO presentation: 'This decision hinges on one assumption: market adoption > 25%. Below that, we should not launch. Our research suggests 30-35%, so we proceed \u2014 but we monitor adoption weekly.'", "tags": ["analysis", "decision-making"], "order_index": 6, "formula": null}] },
  { id: "cc000001-0000-4000-8000-000000000002", slug: "sensitivity-analysis", title: "Sensitivity Analysis", description: "Stress-test your assumptions: find which variables most affect outcomes and where your model is fragile", category: "analysis", difficulty: 2, estimated_time_minutes: 30, key_concepts: ["Tornado Charts", "Spider Charts", "Break-Even Analysis", "Scenario Testing", "One-Way vs Two-Way Sensitivity", "Assumption Auditing"], use_cases: ["Financial model validation", "M&A due diligence", "Budget assumptions", "Revenue forecast review", "Any model presented to the board"], content: "", concepts: [{"name": "Tornado Charts", "definition": "Rank every input variable by how much it swings the final output when varied across its plausible range. The variable with the widest bar is your deal-killer \u2014 verify it first.", "example": "DCF value = $100M. Tornado shows: churn rate swings value \u00b1$40M, CAC swings value \u00b1$15M, interest rate swings \u00b1$5M. Focus 80% of your analysis on churn \u2014 it dominates everything else. | Board question: 'What keeps you up at night on this model?' Show the tornado chart. 'If churn is off by 2 percentage points, we lose $30M.' Credible, data-driven answer. | Every board presentation should include a tornado chart. One image replaces 20 'what if' questions.", "tags": ["analysis", "financial"], "order_index": 1}, {"name": "Break-Even Analysis", "definition": "For each critical assumption, calculate what value would make NPV = 0. How far are we from disaster? Small margin = high risk.", "example": "Investment breaks even if churn stays below 4.2%. Current assumption is 3%. Margin of safety = 1.2 percentage points. Thin margin = high-risk bet. | M&A: accretion/dilution break-even at $8M in synergies. You've modeled $12M. Margin = $4M (33% buffer). Good. | Pricing: new price breaks even at 15% customer adoption. Expected: 25%. 10 points of safety. If expected were 16%, would you really bet the company on 1 point?", "tags": ["analysis", "financial"], "order_index": 2}, {"name": "Scenario Testing", "definition": "Don't just show one number. Show Best Case, Worst Case, and Most Likely Case. The spread between best and worst IS the risk. Narrow spreads = confident predictions; wide spreads = speculative.", "example": "Base case: $50M value. Best case: $120M (if competitor exits market). Worst case: -$15M (if regulation changes). Board sees $50M-$120M. But the risk is the -$15M tail. | Present scenarios, not point estimates. 'Under these conditions, we see $X. Under these adverse conditions, $Y.' | McKinsey-style: always show 3-4 scenarios with explicit trigger conditions for each. Makes the discussion about which scenario is most likely, not whether the model is 'right.'", "tags": ["analysis", "planning"], "order_index": 3}, {"name": "Assumption Auditing", "definition": "List every assumption in your model. Rate each on: 1) How much does it impact the output? 2) How certain are we about it? Focus verification on high-impact, high-uncertainty assumptions.", "example": "Assumption matrix: Top-right quadrant = high impact + low certainty. These need external validation (market research, expert interviews, historical data). | Bottom-left = low impact + high certainty. Accept these and move on. Don't waste time debating assumptions that don't move the needle. | Before any major decision, audit assumptions. The act of listing them forces intellectual honesty. 'We're assuming churn stays at 3%. Is that based on data or hope?'", "tags": ["analysis", "decision-making"], "order_index": 4}, {"name": "Spider Charts", "definition": "A radar-style chart showing how multiple input variables affect the output when each is varied across its range. The variable with the steepest line has the most impact \u2014 visually obvious in seconds.", "example": "Five variables plotted: lines from center to edge. Churn rate line is nearly vertical (huge impact). CAC line is gentle slope (moderate). Office rent line is flat (negligible). Board sees instantly: churn dominates. | Better than tornado charts for showing RELATIVE sensitivity of many variables simultaneously. Use both: tornado for ranking, spider for pattern recognition. | Spider chart reveals interactions: if two lines cross, those variables interact. Investigate the crossing point.", "tags": ["analysis", "visualization"], "order_index": 5, "formula": null}, {"name": "One-Way vs Two-Way Sensitivity", "definition": "One-way: vary one input, hold all others constant. Two-way: vary two inputs simultaneously and observe the interaction. Two-way reveals synergies and offsetting effects one-way misses.", "example": "One-way: varying price only. Two-way: varying price AND volume simultaneously. Price up 10% + volume down 5% = net revenue +4.5%. Price up 10% + volume down 15% = net revenue -6.5%. The relationship between price elasticity and revenue is the key. | One-way shows each lever in isolation; two-way shows reality where they move together. | Two-way sensitivity table: rows = price change (-20% to +20%), columns = volume change (-20% to +20%). Each cell = resulting revenue. The table tells the full story.", "tags": ["analysis", "modeling"], "order_index": 6, "formula": null}] },
  { id: "cc000001-0000-4000-8000-000000000003", slug: "stakeholder-analysis", title: "Stakeholder Analysis & Mapping", description: "Identify who has power over your outcome, what they care about, and how to engage them — before they block you", category: "analysis", difficulty: 2, estimated_time_minutes: 25, key_concepts: ["Power/Interest Grid", "Stakeholder Salience", "RACI Mapping", "Influence Networks", "Communication Planning", "Coalition Building"], use_cases: ["Reorganization", "Major policy change", "Product launch", "M&A integration", "Crisis response", "Board alignment"], content: "", concepts: [{"name": "Power/Interest Grid", "definition": "Plot every stakeholder on a 2x2: Power (ability to affect outcome) vs Interest (how much they care). Each quadrant gets a different engagement strategy.", "example": "High Power + High Interest (manage closely): Board members, key investors, major customers, regulators. Involve early, update frequently. | High Power + Low Interest (keep satisfied): CEO's boss, government officials. Don't surprise them. Brief before major decisions. | Low Power + High Interest (keep informed): affected employees, user groups, press. Regular updates, listen. | Low Power + Low Interest (monitor): general public, industry observers. Minimal effort.", "tags": ["analysis", "org"], "order_index": 1}, {"name": "Stakeholder Salience", "definition": "Mitchell, Agle & Wood: stakeholders get priority based on three attributes \u2014 Power, Legitimacy, and Urgency. Those with all three are 'definitive stakeholders' and demand immediate attention.", "example": "Definitive (all 3): Union threatening strike before product launch. Power (can stop production), Legitimacy (represent workers), Urgency (deadline tomorrow). Act now. | Expectant (2 of 3): Investor with legitimate concern (legitimacy + urgency, but no power to force action). Engage, but don't drop everything. | Latent (1 of 3): Activist with power but no legitimate claim or urgency. Monitor, don't engage yet.", "tags": ["analysis", "org"], "order_index": 2}, {"name": "RACI Mapping", "definition": "For every decision or deliverable, assign: Responsible (does the work), Accountable (approves \u2014 only ONE), Consulted (input before decision), Informed (told after decision). Clarifies who owns what.", "example": "Product launch: R = Product Manager (does work). A = VP Product (one approver). C = Engineering lead, Sales lead, Legal (consulted beforehand). I = CEO, Board, All-hands (informed afterward). | Mistake: having multiple As (two 'approvers' means no one is truly accountable). | Mistake: not Consulting Legal before a regulatory decision. The 'CC' trap \u2014 forward-thinking RACI mapping prevents this.", "tags": ["analysis", "org"], "order_index": 3}, {"name": "Influence Networks", "definition": "Map the informal organization \u2014 who influences whom beyond the org chart. Identify central nodes, bridges, and isolated stakeholders. Engage influencers even if they lack formal power.", "example": "Org chart says VP Engineering decides. But everyone knows the Principal Architect has 'veto by code review.' Map her as a key influencer \u2014 get her buy-in before the VP. | The admin assistant who controls the CEO's calendar has more influence on timing than a VP. Engage them. | ONA (Organizational Network Analysis) tools: survey 'who do you go to for advice/work decisions?' The resulting graph reveals real influence.", "tags": ["analysis", "org"], "order_index": 4}, {"name": "Communication Planning", "definition": "For each stakeholder group, define: what message, through what channel, at what frequency, from whom. The Power/Interest grid determines the communication intensity.", "example": "High power, high interest (Board): weekly written update from CEO, monthly in-person deep dive. | Low power, high interest (affected employees): bi-weekly all-hands, Slack AMA, FAQ document updated weekly. | High power, low interest (regulator): quarterly compliance report, ad-hoc briefing for major changes only. Don't over-communicate and create scrutiny. | Key principle: communicate BEFORE they hear it elsewhere. Surprise is the enemy of stakeholder management.", "tags": ["analysis", "communication"], "order_index": 5, "formula": null}, {"name": "Coalition Building", "definition": "Map stakeholder positions (supporters, neutrals, opponents). Build a winning coalition by: 1) Lock in supporters early 2) Convert neutrals through targeted engagement 3) Neutralize opponents or isolate them.", "example": "Your reorg: CEO supports (locked). CFO neutral. Two VPs oppose. Strategy: 1) Get CFO to champion by showing P&L benefit 2) Address VP concerns one-on-one (fear of losing headcount) 3) If they remain opposed, build enough support that their opposition doesn't block the decision. | Minimum winning coalition: identify the smallest group whose support guarantees success. Don't waste time convincing everyone. | Political capital is finite. Spend it where it changes outcomes, not where you already have support.", "tags": ["analysis", "influence"], "order_index": 6, "formula": null}] },
  { id: "cc000001-0000-4000-8000-000000000004", slug: "cohort-analysis", title: "Cohort Analysis", description: "Group customers by when they joined and track behavior over time — reveals trends hidden in aggregate averages", category: "analysis", difficulty: 2, estimated_time_minutes: 25, key_concepts: ["Cohort Definition (Time vs Behavior)", "Retention Cohorts", "Revenue Cohorts", "Cohort Lifecycle Patterns", "Leading Churn Indicators", "Cohort vs Aggregate Metrics"], use_cases: ["SaaS churn diagnosis", "Marketing campaign ROI", "Product change impact", "Customer lifecycle analysis", "Pricing change effects"], content: "", concepts: [{"name": "Retention Cohorts", "definition": "Track what percentage of each acquisition month is still active after X months. A flat or improving retention curve = healthy. A declining curve = newer customers are worse than older ones.", "example": "January cohort: 100 customers. Month 1 retention = 85%, Month 3 = 72%, Month 6 = 60%. | March cohort: 100 customers. Month 1 retention = 70%, Month 3 = 45%. March customers are 25% worse. Something changed in Q1. Investigate. | Healthy SaaS: each new cohort should retain BETTER than the previous one (product improving over time). If it's getting worse, product quality is declining.", "tags": ["analysis", "saas"], "order_index": 1}, {"name": "Revenue Cohorts", "definition": "Track not just retention, but revenue per retained customer over time. Are you keeping customers but losing revenue? Or growing revenue per retained customer?", "example": "Customers retained: 80%. Revenue retained: 120% (NRR > 100%). Healthy: existing customers are expanding. | Customers retained: 85%. Revenue retained: 60%. Dangerous: you kept the small accounts but lost the big spenders. Aggregate '85% retention' is misleading. | SaaS gold standard: NRR > 120% means existing customers grow 20% annually even before new customers. Cohort analysis reveals if this is true across all cohorts or propped up by one mega-account.", "tags": ["analysis", "saas", "financial"], "order_index": 2}, {"name": "Cohort vs Aggregate Metrics", "definition": "Aggregate '3% monthly churn' can hide: 1% churn in oldest cohorts and 8% in newest. Without cohort breakdown, you'd think everything is fine while the business erodes from the front.", "example": "Total customers growing 5%/month, aggregate churn 3% = net growth 2%. Looks fine. | Cohort breakdown: 2023 cohorts churning at 1% (sticky), 2025 cohorts churning at 8% (new customers are worse quality). Growth is masking a QUALITY problem. When growth slows, churn spike will be catastrophic. | Always ask: 'Is our growth making our unit economics better or just hiding deterioration?' Cohorts answer this.", "tags": ["analysis", "saas"], "order_index": 3}, {"name": "Leading Churn Indicators", "definition": "Don't wait for churn. Identify behavioral patterns that PREDICT churn: declining usage, fewer support tickets (given up), downgrade activity. Act before they leave.", "example": "Cohort A: average 15 logins/week in Month 1. Cohort B: average 8 logins/week in Month 1. Cohort B WILL churn more. Early engagement predicts retention. | Leading indicators: login frequency, feature adoption, support ticket type (is it 'how do I?' or 'I want to cancel?'), NPS drop. | Build a churn prediction model: if a customer has <5 logins in Week 2 and hasn't used a core feature, trigger a CSM intervention. Proactive > reactive.", "tags": ["analysis", "saas", "metrics"], "order_index": 4}, {"name": "Cohort Definition (Time vs Behavior)", "definition": "Time cohorts: group by when they started (acquisition month). Behavior cohorts: group by what they did (first purchased feature X). Use time for retention analysis, behavior for product analysis.", "example": "Time cohort: 'Users who signed up in January 2025.' Track their retention over 12 months. Compare to February 2025 cohort. | Behavior cohort: 'Users whose first purchase was Product X.' Do they retain differently from users who started with Product Y? | Combined: 'January cohort, Product X starters.' Now you know: time effect, product effect, AND interaction. January cohort with Product X has 80% retention \u2014 but February cohort with Product X has 50%. Something changed in February.", "tags": ["analysis", "segmentation"], "order_index": 5, "formula": null}, {"name": "Cohort Lifecycle Patterns", "definition": "Healthy: each new cohort retains better than the previous (product improving). Warning: cohorts show same retention (product stagnant). Danger: newer cohorts retain WORSE (product deteriorating or growth quality declining).", "example": "Quarterly cohorts: Q1 2024 retention at Month 6 = 70%. Q2 = 72%. Q3 = 75%. Product getting better. | Q1 = 70%. Q2 = 68%. Q3 = 65%. Each new cohort is worse. Check: did marketing change targeting? Is sales qualifying differently? What changed in onboarding? | Flat pattern: all cohorts converge to same retention. Product is stable but not improving. Engineering effort going to features, not quality. Shift investment.", "tags": ["analysis", "saas"], "order_index": 6, "formula": null}] },
  { id: "cc000001-0000-4000-8000-000000000005", slug: "monte-carlo-simulation", title: "Monte Carlo Simulation", description: "Run thousands of scenarios with random inputs to get a probability distribution of outcomes — not just one number", category: "analysis", difficulty: 3, estimated_time_minutes: 35, key_concepts: ["Distribution Thinking", "Confidence Intervals (P10/P50/P90)", "Value at Risk (VaR)", "Convergence Testing", "Correlated Assumptions"], use_cases: ["Project timelines", "Revenue forecasting", "Investment valuation", "Risk quantification", "Portfolio optimization", "Supply chain risk"], content: "", concepts: [{"name": "Distribution Thinking", "definition": "Replace every point estimate in your model with a probability distribution (range + likelihood). 'Revenue = $10M' becomes 'Revenue is triangular: min $7M, most likely $10M, max $15M.'", "example": "Project cost estimate: 'It'll cost $5M.' Reality: best case $4M (optimistic), most likely $5.5M, worst case $9M (supplier delay). Monte Carlo with triangular distribution gives realistic range. | Revenue: instead of one number, model it with growth rate as a random variable (historical mean + volatility). | Why: point estimates are always wrong. Distributions are honest about uncertainty. The board respects 'we have 70% confidence it's between X and Y' more than 'it'll be Z.'", "tags": ["analysis", "simulation"], "order_index": 1}, {"name": "Confidence Intervals (P10/P50/P90)", "definition": "Run 10,000 simulations and report: P10 (10% of outcomes are below this \u2014 optimistic but possible), P50 (median \u2014 equally likely above or below), P90 (90% are below \u2014 conservative). The P10-P90 range IS your uncertainty.", "example": "M&A value: P10 = $120M, P50 = $85M, P90 = $40M. The deal has a 10% chance of being worth $120M and a 10% chance of being worth less than $40M. That's a 3:1 range. Is the board comfortable with that risk? | Project completion: P10 = 4 months, P50 = 6 months, P90 = 11 months. Commit to the board for 8 months (between P50 and P75) with contingency for 12. | Buffer sizing: use P90 minus P50 as your recommended contingency budget/time.", "tags": ["analysis", "simulation"], "order_index": 2}, {"name": "Value at Risk (VaR)", "definition": "The maximum loss you'd expect at a given confidence level over a specific time period. VaR(95%) = $10M means 'we're 95% confident we won't lose more than $10M.' The remaining 5% could be worse.", "example": "Portfolio VaR(95%) = $5M. You have a buffer of $8M. You're protected 95% of the time \u2014 the other 5%, you need a plan. | Project budget: deterministic estimate = $10M. Monte Carlo VaR(90%) = $13M. Add $3M contingency. | VaR limitation: it tells you the threshold but NOT how bad it gets beyond. Complement with 'Conditional VaR' (expected loss GIVEN that you exceed VaR). 'When things go wrong, how wrong do they go?'", "tags": ["analysis", "risk"], "order_index": 3}, {"name": "Correlated Assumptions", "definition": "In reality, variables move together: when the economy tanks, both your sales drop AND your cost of capital rises. Model correlations or your simulation will underestimate risk.", "example": "Independent assumption: sales volume varies, price varies, they're unrelated. Reality: in a recession, volume drops AND you have to cut prices. The double-hit is worse than either alone. | Interest rates and cap rates in real estate: when rates rise, cap rates tend to rise too \u2014 double pressure on valuations. Model the correlation (typically 0.6-0.8). | Ignoring correlation gives you a falsely narrow range. The worst case scenarios come from correlated failures, not independent ones.", "tags": ["analysis", "risk", "simulation"], "order_index": 4}, {"name": "Convergence Testing", "definition": "Run enough iterations that the output distribution stabilizes. If adding 1000 more iterations doesn't change P50 by more than 1%, you've converged. Typical: 5,000-10,000 iterations for most business models.", "example": "After 1000 iterations: P50 = $85.3M. After 5000: P50 = $84.9M. After 10000: P50 = $85.0M. Converged. | Under-converged: P50 swings wildly between runs. Run more iterations. | Overkill: 100,000 iterations for a simple 5-variable model. Waste of compute time. 10,000 is almost always sufficient for business decisions.", "tags": ["analysis", "simulation"], "order_index": 5, "formula": null}] },
  { id: "cc000001-0000-4000-8000-000000000006", slug: "value-driver-tree", title: "Value Driver Tree Analysis", description: "Decompose any top-level metric into its mathematical drivers down to operational levers — see what actually moves the needle", category: "analysis", difficulty: 2, estimated_time_minutes: 30, key_concepts: ["Top-Down Decomposition", "Operational Levers", "DuPont-Style Driver Trees", "Cost Driver Trees", "Leading vs Lagging Indicators"], use_cases: ["Performance management", "Strategic planning", "KPI design", "Board reporting", "Organizational alignment"], content: "", concepts: [{"name": "DuPont-Style Driver Trees", "definition": "Start with ROE or ROIC at the top, decompose into margin \u00d7 turnover \u00d7 leverage, and keep decomposing until you reach operational metrics that front-line managers control.", "example": "Enterprise Value \u2192 FCF \u2192 Revenue - Costs - CapEx. Revenue \u2192 Volume \u00d7 Price. Volume \u2192 New customers + repeat customers. New customers \u2192 Marketing leads \u00d7 conversion rate \u00d7 ASP. Each level connects strategy to operations. | Cost \u2192 COGS + OpEx. COGS \u2192 Unit cost \u00d7 volume. Unit cost \u2192 Material cost + labor + overhead. Every node is a lever someone owns. | The tree reveals: to improve ROIC by 2%, you can either raise prices 3%, reduce costs 5%, or increase asset turnover 7%. Which is easiest?", "tags": ["analysis", "financial"], "order_index": 1}, {"name": "Leading vs Lagging Indicators", "definition": "Lagging indicators (revenue, profit) tell you what happened. Leading indicators (pipeline, engagement, quality) predict what WILL happen. A good driver tree connects both.", "example": "Revenue (lagging) \u2190 Bookings \u2190 Pipeline \u2190 Qualified leads \u2190 Marketing spend (leading). If leads drop this month, revenue drops in 3 months. Act now. | Customer satisfaction (leading) \u2192 Retention (lagging). If NPS drops, churn rises in 6 months. Don't wait for churn to spike. | Driver tree tells you which leading indicators to watch. Design your dashboard around the tree: top-line results (lagging) AND the 3-5 drivers that predict them (leading).", "tags": ["analysis", "metrics"], "order_index": 2}, {"name": "Operational Levers", "definition": "Every node in the tree must map to a specific person or team with authority to change it. If a driver can't be assigned to an owner, it's not a lever \u2014 it's an observation.", "example": "Revenue driver: 'Increase average order value.' Who owns this? Marketing (upsells), Product (bundles), Sales (enterprise features). Assign one owner. | Profit driver: 'Reduce customer acquisition cost.' Marketing (channel mix), Sales (efficiency), Product (viral features). Each gets a sub-driver tree. | Only include levers someone can actually pull. 'Macroeconomic conditions' goes in the risk section, not the driver tree. It drives outcomes but you can't control it.", "tags": ["analysis", "operations"], "order_index": 3}, {"name": "KPI Design from Driver Trees", "definition": "Your KPIs should be a direct translation of your driver tree. Each node with an owner becomes a KPI. The tree IS your measurement framework.", "example": "Tree: Revenue \u2192 # Customers \u00d7 ARPU. # Customers \u2192 New + Retained. New \u2192 Leads \u00d7 Win Rate. Each gets a KPI with target and owner. | CEO dashboard: top 5-7 driver tree nodes. Drill down only when a node turns red. | Anti-pattern: random KPIs picked because 'they seem important' without connecting to a driver tree. Why does 'social media followers' matter? Show me the tree path from followers to enterprise value.", "tags": ["analysis", "metrics"], "order_index": 4}, {"name": "Top-Down Decomposition", "definition": "Start with the ultimate metric (enterprise value, ROIC, NPS) at the top. Ask 'what mathematically determines this?' at each level. Break down until you reach operational levers someone controls.", "example": "Enterprise Value = FCF / (WACC - g). FCF = Revenue \u00d7 Margin - CapEx. Revenue = Volume \u00d7 Price. Volume = New customers + Repeat. New customers = Leads \u00d7 Conversion. Leads = Marketing spend / CAC. Every level is a lever with an owner. | Target: increase EV 20%. Top-down: need 5% revenue growth + 2% margin improvement + 1% multiple expansion. Each gets an owner and sub-tree. | Stop decomposing when: the lever can be assigned to a specific person with authority to change it. If you can't assign it, decompose further.", "tags": ["analysis", "metrics"], "order_index": 5, "formula": null}, {"name": "Cost Driver Trees", "definition": "Just as you decompose revenue, decompose costs: Total Cost \u2192 COGS + OpEx + CapEx \u2192 decompose each into unit costs \u00d7 volumes \u2192 decompose unit costs into material, labor, overhead \u2192 map to process owners.", "example": "Total Cost = $50M. COGS (60%) + OpEx (30%) + CapEx (10%). COGS = Unit Cost \u00d7 Units. Unit Cost = Materials ($3/widget) + Labor ($2) + Overhead ($1). Each gets a KPI. | OpEx = Sales + Marketing + R&D + G&A. Sales = Headcount \u00d7 Cost/rep. Cost/rep = Salary + Commission + Travel + Tools. | Tree reveals: biggest cost lever is Materials (30% of total). 5% material cost reduction = $1.5M to bottom line. Focus supplier negotiation there, not on travel budget ($200k).", "tags": ["analysis", "financial"], "order_index": 6, "formula": null}] },
  { id: "cc000001-0000-4000-8000-000000000007", slug: "ab-testing-experiments", title: "A/B Testing & Experiment Design", description: "Run controlled experiments to measure causal impact — prove that your change caused the outcome, not coincidence", category: "analysis", difficulty: 3, estimated_time_minutes: 30, key_concepts: ["Randomized Controlled Trials", "Practical vs Statistical Significance", "Sample Size & Power", "Confidence Intervals in Experiments", "A/A Testing", "The Peeking Problem"], use_cases: ["Product changes", "Marketing campaigns", "Pricing tests", "UI/UX improvements", "Email optimization", "Algorithm changes"], content: "", concepts: [{"name": "Randomized Controlled Trials", "definition": "Randomly split users into control (no change) and treatment (change applied). Randomization ensures the ONLY systematic difference is your change \u2014 so any outcome difference is causal.", "example": "New checkout flow: 50,000 visitors randomly split. Control: old flow, conversion 4.2%. Treatment: new flow, conversion 4.8%. Difference: +0.6 percentage points (14% relative improvement). Randomization means we can attribute this to the new flow. | Without randomization: compare this month (new flow) to last month (old). Confounded by seasonality, other changes, different user mix. | Key: randomization must be at the RIGHT unit. Randomize users, not sessions, if you're testing a user-level change.", "tags": ["analysis", "experimentation"], "order_index": 1}, {"name": "Sample Size & Power", "definition": "Calculate how many users you need BEFORE running the test. Too few = test is underpowered (can't detect real effects). Too many = waste time and users on a decision you already have enough data for.", "example": "Expected lift: 5% relative. Baseline: 10% conversion. Required sample: ~25,000 per variant (for 80% power, p < 0.05). If you only get 2,000 visitors/week, you need 12 weeks. Is that worth it? | Expected lift: 1% relative. Required sample: 500,000. Is this effect worth detecting? Practical significance check. | CEO question: 'How long will this test take?' If answer is '3+ months,' challenge whether the expected impact justifies the cost of waiting.", "tags": ["analysis", "experimentation"], "order_index": 2}, {"name": "The Peeking Problem", "definition": "Don't check results daily and stop when you see significance. This inflates false positive rates 3-5x. Pre-commit to a sample size and wait until it's reached.", "example": "Test planned for 2 weeks. After 3 days: 'p = 0.03, it's working! Ship it!' Wrong. Early fluctuations are normal. The effect may reverse. Wait until the pre-planned endpoint. | Fix: use sequential testing frameworks that adjust significance thresholds for interim looks (e.g., Bayesian approaches, always-valid p-values). | CEO red flag: 'Why are we shipping an A/B test after 3 days?' Demand the pre-registered test plan with sample size, duration, and success criteria.", "tags": ["analysis", "experimentation"], "order_index": 3}, {"name": "Practical vs Statistical Significance", "definition": "A result can be statistically significant (p < 0.05) but practically meaningless (+0.05% revenue). Always ask: 'Is the effect big enough to matter?' before asking 'Is the effect real?'", "example": "Statistically significant: new button color increases CTR by 0.1% (p = 0.001). 10M users \u00d7 0.1% = 10,000 extra clicks. Worth the engineering time? Probably not. | Practically significant: new recommendation algorithm increases AOV by 8% (p = 0.04). $10M revenue impact. Ship it. | Tie every experiment to business impact. 'Increased engagement' means nothing. 'Reduced churn by 0.5% saving $2M/year' means everything.", "tags": ["analysis", "experimentation"], "order_index": 4}, {"name": "A/A Testing", "definition": "Run the SAME version on both groups before your real test. If the A/A test shows a statistically significant difference, your randomization is broken or your metric is noisy. Fix before running real tests.", "example": "A/A test: both groups see identical page. Results: conversion 4.2% vs 4.3%, p = 0.04. But they're identical! This false positive means your sample size or metric has issues. | If A/A tests show false positives > 5% of the time (at p < 0.05 threshold), recalibrate. Your system is generating spurious results. | A/A tests build trust. Before reporting 'new feature increased conversion 15%,' prove your testing infrastructure doesn't find effects where none exist.", "tags": ["analysis", "experimentation"], "order_index": 5, "formula": null}, {"name": "Confidence Intervals in Experiments", "definition": "Report results as 'the effect is +3% with a 95% CI of [1.5%, 4.5%].' A confidence interval tells you both the best estimate AND the precision. Wide CI = small sample, collect more data. Narrow CI = precise estimate.", "example": "Test result: +5% conversion, 95% CI [-1%, +11%]. The effect COULD be negative. Not statistically significant \u2014 CI crosses zero. | Test result: +2% conversion, 95% CI [1.8%, 2.2%]. Statistically significant AND practically meaningful? Only 2% lift \u2014 is it worth the engineering cost? | Overlapping CIs: Treatment A [+2%, +5%], Treatment B [+2.5%, +5.5%]. Overlap means they're not significantly different from each other \u2014 pick either.", "tags": ["analysis", "experimentation"], "order_index": 6, "formula": null}] },
  { id: "cc000001-0000-4000-8000-000000000008", slug: "force-field-analysis", title: "Force Field Analysis", description: "Map the forces driving toward your goal and those holding you back — strengthen drivers or weaken resistors to create change", category: "analysis", difficulty: 1, estimated_time_minutes: 20, key_concepts: ["Driving vs Restraining Forces", "Restraining Forces", "Force Scoring", "Equilibrium Analysis", "Force Reduction Strategy", "Change Management Integration"], use_cases: ["Change management", "Strategy execution debugging", "Team performance issues", "Project stall analysis", "Personal development planning"], content: "", concepts: [{"name": "Driving vs Restraining Forces", "definition": "For any desired change, list forces pushing TOWARD the goal (driving) and forces pushing AGAINST it (restraining). The current state is the equilibrium between them.", "example": "Goal: Remote-to-office return. Driving: collaboration benefits, leadership preference, client requests. Restraining: commute time, flexibility loss, productivity concerns, childcare. | Don't just push harder on drivers (more mandates). Weaken resistors: offer commute subsidies, keep 1 day remote, provide childcare stipend. | Kurt Lewin: 'It's usually easier to reduce restraining forces than to increase driving forces.' Reducing resistors creates less tension and resistance.", "tags": ["analysis", "change"], "order_index": 1}, {"name": "Force Scoring", "definition": "Rate each force 1-5 for strength. Sum the driving forces, sum the restraining forces. If drivers > resistors, change will happen. If not, you need intervention \u2014 strengthen drivers OR weaken resistors.", "example": "Drivers: market urgency (4), CEO mandate (5), customer demand (3) = 12. Restraining: legacy systems (4), fear of change (5), no training (3), budget (2) = 14. Result: 12 < 14. Change won't happen. Target: fund training (reduce 3\u21921), address fear through communication (reduce 5\u21923). New restraining sum = 10. 12 > 10. Change possible. | Visual: draw arrows proportional to scores. The picture makes the balance obvious. | Re-score after interventions to track progress.", "tags": ["analysis", "change"], "order_index": 2}, {"name": "Force Reduction Strategy", "definition": "For each top restraining force, ask: 'How can we reduce this?' Three approaches: 1) Remove the force entirely 2) Reduce its strength 3) Add a counterbalancing new driving force.", "example": "Restraining force: 'Legacy IT system can't support new process.' Remove: migrate to new system (12 months, $5M). Reduce: build API bridge (3 months, $200k). Counterbalance: add driving force 'IT team gets training and career growth from migration project.' | Restraining force: 'Middle managers fear losing authority.' Reduce: give them MORE authority in the new structure (they become process owners, not just supervisors). | Key insight from Lewin: reducing restraining forces creates permanent change. Adding driving forces creates temporary change that snaps back.", "tags": ["analysis", "change"], "order_index": 3}, {"name": "Change Management Integration", "definition": "Force Field Analysis identifies WHAT to change. Pair it with ADKAR or Kotter for HOW to change. FFA = diagnosis, ADKAR = treatment.", "example": "FFA identifies top restraining force: 'middle manager fear of job loss.' ADKAR: Awareness (explain why change is needed), Desire (what's in it for them \u2014 new career paths), Knowledge (training on new role), Ability (support during transition), Reinforcement (celebrate managers who adapt). | Kotter 8-Step: FFA maps to Step 1 (urgency = driving forces), Step 4 (communicate vision = reduce restraining forces through information). | Don't just identify forces \u2014 build a CHANGE PLAN that addresses each one.", "tags": ["analysis", "change"], "order_index": 4, "formula": null}, {"name": "Restraining Forces", "definition": "Everything pushing against your desired change: habits, fears, legacy systems, politics, incentives, resource constraints. Unlike driving forces (push toward), restraining forces maintain the status quo. Weakening them is often easier than strengthening drivers.", "example": "Restraining: 'We've always done it this way' (habit, force 5/5). 'If this fails, I'll lose my job' (fear, force 5/5). 'The legacy system can't support it' (systems, force 4/5). | Strategy: don't argue with habit \u2014 show proof the new way works (pilot program). Don't dismiss fear \u2014 offer job security guarantees during transition. Don't fight the system \u2014 invest in the upgrade. | Lewin's insight: reducing restraining forces creates LESS resistance than adding driving forces. People resist being pushed; they accept obstacles being removed.", "tags": ["analysis", "change"], "order_index": 4, "formula": null}, {"name": "Equilibrium Analysis", "definition": "Identify the current balance of forces. The current situation (equilibrium) persists because driving and restraining forces are roughly equal. To create change, you must disrupt this balance \u2014 strengthen drivers, weaken resistors, or both.", "example": "Current equilibrium: 50% office attendance. Drivers (to increase): leadership mandate (3), collaboration benefits (2), client preference (2) = 7. Restraining: commute time (4), flexibility loss (5), childcare (3) = 12. Resistors dominate \u2014 change won't happen spontaneously. | To reach 80% attendance: need new driving force (commuter subsidy +2, strengthen mandate +1) AND reduce resistors (1 day remote eliminates flexibility loss 5\u21922). New balance: drivers 10, resistors 9. Change possible.", "tags": ["analysis", "change"], "order_index": 5, "formula": null}] },
  { id: "dd000001-0000-4000-8000-000000000001", slug: "cognitive-biases-debiasing", title: "Cognitive Biases & Debiasing", description: "Identify and counteract the 25+ cognitive biases that warp CEO judgment — from anchoring to survivorship bias", category: "decision-making", difficulty: 2, estimated_time_minutes: 45, key_concepts: ["Confirmation Bias", "Anchoring Bias", "Overconfidence Bias", "Availability Bias", "Survivorship Bias", "Sunk Cost Fallacy", "Framing Effect", "Hindsight Bias"], use_cases: ["Hiring decisions", "M&A evaluation", "Strategic bets", "Performance reviews", "Investment decisions", "Crisis response"], content: "", concepts: [{"name": "Confirmation Bias", "definition": "Seeking, interpreting, and remembering information that confirms your existing beliefs while ignoring contradictory evidence. The most pervasive bias in business.", "example": "You believe this candidate is a great hire. You interpret 'aggressive' as 'driven.' A skeptic would see 'abrasive.' Same facts, different interpretation. | M&A: CEO believes target is strategic. Asks team to 'build the case for the acquisition' \u2014 phrasing guarantees confirmation bias. Better: 'Build the case FOR and AGAINST. What's the strongest argument NOT to do this?' | Debiasing: mandate a devil's advocate in every major decision. Require the written case AGAINST before approving.", "tags": ["bias", "decision-making"], "order_index": 1}, {"name": "Anchoring Bias", "definition": "The first number or information you encounter disproportionately influences your judgment. Initial offers, industry benchmarks, and first impressions all anchor you.", "example": "Initial salary offer anchors the entire negotiation. Candidate asks $180k \u2014 employer mentally adjusts from $180k, not from market rate of $145k. | M&A: Target asks 12x EBITDA. Buyer counters at 8x. Settle at 10x. But the 12x anchor made 10x feel like a 'win' \u2014 without it, buyer might have opened at 6x and settled at 8x. | Debiasing: generate your own independent estimate BEFORE hearing the other side's number. Write it down. Compare after.", "tags": ["bias", "negotiation"], "order_index": 2}, {"name": "Overconfidence Bias", "definition": "Systematically overestimating your knowledge, predicting narrower confidence intervals than reality warrants. Your 90% confidence predictions are right only 50-70% of the time.", "example": "CEO: 'I'm 90% confident this product will launch by June.' Actual: launches in October. The '90% confident' range should have captured the true timeline \u2014 it didn't. | Track your predictions. Keep a decision journal. After 100 predictions rated at 90% confidence, ~90 should be correct. Most CEOs: 50-70% correct. That's the overconfidence gap. | Debiasing: take your estimate and DOUBLE the timeline. Then add 20% buffer. That's usually closer to reality.", "tags": ["bias", "decision-making"], "order_index": 3}, {"name": "Availability Bias", "definition": "Judging the likelihood of an event by how easily you can recall examples. Vivid, recent, or emotional events seem more common than they actually are.", "example": "After a plane crash in the news, people fear flying and drive instead. Driving is FAR more dangerous per mile. The crash is vivid and recent; car accidents are routine and forgotten. | After a competitor's failed acquisition makes headlines, your board panics about YOUR deal. Ignore the anecdote \u2014 look at the base rate: 70% of acquisitions in your industry succeed. | Debiasing: always ask 'What's the base rate?' before making probability judgments. Don't let vivid stories override data.", "tags": ["bias", "decision-making"], "order_index": 4}, {"name": "Survivorship Bias", "definition": "Studying successful companies/people/strategies without seeing the failures that didn't survive. The 'graveyard' of failures contains the counterexamples you need.", "example": "Books about 'what made Steve Jobs great' ignore thousands of leaders with similar traits who failed. You're learning from the survivor, not the population. | Study successful startups: all pivoted. Does pivoting cause success? Or do we only hear about the pivots that worked while ignoring the many pivots that killed other companies? | Debiasing: when studying success, ask 'who TRIED this and failed?' Go find the failures. They teach more than the survivors.", "tags": ["bias", "decision-making"], "order_index": 5}, {"name": "Sunk Cost Fallacy", "definition": "Treating money, time, or effort already spent as a reason to continue investing. Rational decision-making ignores sunk costs \u2014 only future costs and benefits matter.", "example": "You've spent $10M on an internal project. It's failing. 'We can't stop now, we've invested too much.' Wrong: those $10M are gone regardless. The question is: will spending $5M MORE generate value? If no, kill it. | Concorde fallacy: British and French governments kept funding the Concorde despite knowing it would never be profitable. 'We've come too far to stop.' | Debiasing: ask 'If I were joining this company TODAY, would I greenlight this project?' Your past investment shouldn't influence your future decision.", "tags": ["bias", "decision-making"], "order_index": 6}, {"name": "Framing Effect", "definition": "How a choice is presented changes what you decide. '80% success rate' feels different from '20% failure rate' \u2014 even though they're identical. Frame the question before deciding.", "example": "Doctor: 'This surgery has a 90% survival rate.' vs 'This surgery has a 10% mortality rate.' Same facts. Patients choose surgery 84% of the time in the first frame, 50% in the second. | Investment: 'This has a 30% chance of losing money' vs '70% chance of making money.' Your risk tolerance shifts with the frame. | Debiasing: ALWAYS reframe the question. 'What if I described this as a loss? As a gain? As a risk? As an opportunity?' See if your decision changes before committing.", "tags": ["bias", "decision-making"], "order_index": 7}, {"name": "Hindsight Bias", "definition": "'I knew it all along' \u2014 after an outcome occurs, you believe you predicted it. Prevents learning because you rewrite history to make yourself look prescient.", "example": "Quarterly results miss by 20%. Everyone says 'I saw this coming.' But did they? Check their pre-quarter predictions \u2014 they projected 10% growth. Hindsight rewrote their memory. | Dot-com crash 2000: after the crash, everyone 'knew' it was a bubble. But before the crash, the same people were investing. | Debiasing: WRITE DOWN your predictions before events unfold. Decision journal. Then compare actual outcomes to what you actually predicted, not what you remember predicting.", "tags": ["bias", "decision-making"], "order_index": 8}] },
  { id: "dd000001-0000-4000-8000-000000000002", slug: "multi-criteria-decision-analysis", title: "Multi-Criteria Decision Analysis (MCDA)", description: "Structured scoring and weighting when you have 5+ options and 10+ criteria — turns \'gut feel\' into auditable, defensible decisions", category: "decision-making", difficulty: 2, estimated_time_minutes: 35, key_concepts: ["Weighted Scoring Matrix", "Analytic Hierarchy Process (AHP)", "Trade-Off Curves", "Criteria Weighting Methods", "Sensitivity at Decision Points", "Non-Compensatory Rules"], use_cases: ["Vendor selection", "Hiring (multiple candidates)", "Site selection", "R&D portfolio prioritization", "Strategic initiative ranking", "CapEx allocation"], content: "", concepts: [{"name": "Weighted Scoring Matrix", "definition": "List criteria, assign weights (must sum to 100%), score each option 1-10 on each criterion, multiply score \u00d7 weight and sum. The option with the highest weighted sum is the analytically 'best' choice.", "example": "Vendor selection: 3 vendors, 5 criteria. Cost (30% weight), Quality (25%), Speed (20%), Reliability (15%), Culture fit (10%). Score each 1-10. Vendor A: $50k (score 8\u00d70.3=2.4) + Quality 6\u00d70.25=1.5 + Speed 9\u00d70.2=1.8 + Reliability 7\u00d70.15=1.05 + Culture 8\u00d70.1=0.8 = Total 7.55. Vendors B=6.2, C=8.1. C wins \u2014 even though A was cheapest. | CEO sanity check: does the winner FEEL right? If not, revisit your weights \u2014 you may have undervalued something you actually care about deeply.", "tags": ["decision-making", "analysis"], "order_index": 1}, {"name": "Analytic Hierarchy Process (AHP)", "definition": "Structured pairwise comparison: instead of guessing weights, compare criteria two at a time. 'Is Cost more important than Quality? How much more? (1-9 scale).' Mathematically derives consistent weights.", "example": "Pairwise: Cost vs Quality: 'Cost is 3x more important than Quality' (score 3/1). Cost vs Speed: 'Cost is 5x more important' (5/1). Quality vs Speed: 'Quality is 2x more important' (2/1). AHP calculates: Cost=65%, Quality=23%, Speed=12%. | Consistency ratio: AHP checks if your comparisons are internally consistent. If Cost>>Quality and Quality>>Speed but Speed=Cost (inconsistent), AHP flags it. | More rigorous than guessing weights but takes longer. Use for high-stakes decisions, not daily ones.", "tags": ["decision-making", "analysis"], "order_index": 2}, {"name": "Trade-Off Curves", "definition": "Plot two criteria against each other for all options. Visualize the frontier \u2014 options that are NOT dominated (no other option beats them on BOTH criteria). Choose from the frontier.", "example": "Cost vs Quality plot: Option A ($50k, quality 6). Option B ($80k, quality 9). Option C ($60k, quality 7). Option D ($55k, quality 5). D is dominated by A (better quality, similar cost). A, B, C are on the frontier \u2014 pick based on your cost/quality preference. | Elegant way to communicate to board: 'Any option below this frontier line is inferior. Here are your three frontier choices \u2014 now let's discuss cost vs quality trade-off.'", "tags": ["decision-making", "analysis"], "order_index": 3}, {"name": "Criteria Weighting Methods", "definition": "Five ways to assign weights: 1) Direct rating (just guess %) 2) Point allocation (spread 100 points) 3) Ranking (then convert to weights) 4) AHP pairwise (most rigorous) 5) Swing weighting (how much would improving from worst-to-best on this criterion matter?).", "example": "Swing weighting: 'Imagine the WORST possible vendor on all criteria. If you could improve just ONE criterion from worst to best, which has most impact?' That criterion gets highest weight. Repeat for remaining criteria. | Ranking to weights: 'Speed > Quality > Cost > Reliability > Culture.' Convert: Speed=5 points, Quality=4, Cost=3, Reliability=2, Culture=1. Normalize: 5/15=33%, 4/15=27%, etc. | Match method to stakes. AHP for $10M+ decisions. Ranking for routine ones.", "tags": ["decision-making", "analysis"], "order_index": 4}, {"name": "Sensitivity at Decision Points", "definition": "Test whether small changes in criteria weights change which option wins. If Winner A beats Winner B by 0.5 points, and changing 'quality' weight from 25% to 26% flips the result to B \u2014 the decision is FRAGILE. Investigate that criterion before committing.", "example": "Sensitivity table: rows = options, columns = criteria weight scenarios (+/- 10%). If the winner changes in any scenario, flag it. | 'The decision is ROBUST: Vendor C wins across all reasonable weight scenarios.' vs 'The decision is SENSITIVE: Vendor A wins if quality > 30%, Vendor B wins otherwise. We need to nail down our quality weighting.' | Board communication: 'This decision is not sensitive to our assumptions \u2014 the winner is the same across a wide range of plausible weights.' Confidence statement.", "tags": ["decision-making", "analysis"], "order_index": 5, "formula": null}, {"name": "Non-Compensatory Rules", "definition": "Some criteria are MUST-HAVES where a bad score eliminates the option regardless of other strengths (non-compensatory). Others are NICE-TO-HAVES where strengths can compensate for weaknesses. Filter out must-have failures first, then score the survivors.", "example": "Must-have: 'Vendor must be SOC2 compliant.' Vendor C scores highest overall but fails SOC2 = eliminated. No amount of other strengths can compensate. | Nice-to-have: 'Vendor's office is within 50 miles.' Vendor B is 60 miles away, but compensates with better pricing and quality. Acceptable trade-off. | Non-compensatory rules prevent the 'best scoring' option from being fundamentally unsuitable. Apply them BEFORE weighted scoring to narrow the field.", "tags": ["decision-making", "analysis"], "order_index": 6, "formula": null}] },
  { id: "dd000001-0000-4000-8000-000000000003", slug: "decision-quality-framework", title: "Decision Quality Framework", description: "Spetzler\'s 6-element framework: frame, alternatives, information, values, reasoning, commitment — ensures every major decision passes a quality audit", category: "decision-making", difficulty: 3, estimated_time_minutes: 35, key_concepts: ["Appropriate Frame", "Creative Alternatives", "Meaningful Information", "Clear Values & Trade-offs", "Sound Reasoning", "Commitment to Action"], use_cases: ["Major strategic decisions", "M&A approval", "Capital allocation", "Product launch go/no-go", "Crisis response strategy", "Board-level decisions"], content: "", concepts: [{"name": "Appropriate Frame", "definition": "The decision frame defines what is IN and what is OUT. A bad frame solves the wrong problem brilliantly. The most common decision error is not bad analysis \u2014 it's answering the wrong question.", "example": "Wrong frame: 'Should we acquire Company X?' Right frame: 'What is the best way to enter the European market?' Acquisition is one OPTION within a broader frame. | Wrong: 'How do we reduce costs 10%?' Right: 'How do we become sustainably profitable?' Cost-cutting is one lever, not the only one. | Framing checklist: 1) What problem are we solving? 2) Who is the decision-maker? 3) What's in scope and out of scope? 4) What's our time horizon? 5) What perspective are we taking? (customer, shareholder, employee?)", "tags": ["decision-making", "analysis"], "order_index": 1}, {"name": "Creative Alternatives", "definition": "Most decisions fail at the alternatives stage \u2014 people pick from 1-2 options when 5+ exist. Great decisions require a CREATIVE set of mutually exclusive, collectively exhaustive alternatives.", "example": "Typical: 'Should we do A or B?' Better: A, B, C (defer 6 months), D (pilot/test first), E (partner instead), F (do nothing \u2014 wait). Most people never consider D, E, F. | Brainstorming rule: generate options BEFORE evaluating them. Evaluation kills creativity. Separate the two phases \u2014 diverge, then converge. | Test: 'If none of these options existed, what would we do?' This question forces you to invent genuinely new alternatives.", "tags": ["decision-making", "creativity"], "order_index": 2}, {"name": "Sound Reasoning", "definition": "Can you explain WHY you chose X over Y in a way that a skeptical third party would find compelling? Sound reasoning connects information to values through logical inference \u2014 no gaps, no leaps, no narrative fallacies.", "example": "Bad reasoning: 'We chose Vendor A because they have a great reputation.' Good: 'Vendor A scored highest on our weighted criteria: cost (30%), quality (30%), reliability (25%), culture fit (15%). Their reference checks scored 9.2/10 vs vendor B's 7.1. Sensitivity analysis shows the decision holds even if we halve the weight on cost.' | Decision tree: map the reasoning visually \u2014 at each chance node, what's the probability? At each decision node, what's the EV? The tree IS the reasoning.", "tags": ["decision-making", "analysis"], "order_index": 3}, {"name": "Commitment to Action", "definition": "A decision without commitment is just a conversation. DQ Element 6: who will do what by when? What resources are allocated? What's the follow-up mechanism? How will we know if the decision was right?", "example": "Decision made: 'We're entering the German market.' No commitment: everyone nods, nobody owns it. With commitment: VP Europe owns Germany launch, $2M budget approved, 3 hires this quarter, Q2 target: 5 pilot customers, monthly review with CEO. | Commitment = named owner + resources + timeline + success metrics + review cadence. | Also: commitment to KILL the decision if conditions change. Pre-define kill criteria. 'We'll exit if we don't have 10 paying customers by Q4.'", "tags": ["decision-making", "execution"], "order_index": 4}, {"name": "Meaningful Information", "definition": "Do you have the RIGHT information at the RIGHT reliability? Not more data \u2014 better data. For each key uncertainty, ask: what do we know? What's our confidence? What would it cost to learn more? Is the decision sensitive to this information?", "example": "DQF audit: 'We have 3 years of customer churn data (high reliability). We have 0 data on competitor response to our pricing change (low reliability, high sensitivity).' Action: commission competitive intelligence before deciding. | Information quality spectrum: Proven facts > Expert judgment > Educated guesses > Wild assumptions. Label each input in your model. | Value of information question: 'If we spent $50k and 2 weeks getting better data on X, would our decision change?' If no, stop researching X.", "tags": ["decision-making", "analysis"], "order_index": 5, "formula": null}, {"name": "Clear Values & Trade-offs", "definition": "What are you optimizing for? Time, money, quality, risk, growth, culture? Explicitly state your trade-off preferences. 'We value time-to-market 2x more than cost savings.' Without this, you can't compare options.", "example": "DQF values statement: 'For this decision, our ranking is: 1) Time-to-market (we have a 6-month window) 2) Quality (but MVP-level acceptable) 3) Cost (we have budget flexibility).' With this clarity, Option A (fast, good-enough, expensive) beats Option B (slow, great, cheap). | Even swaps technique: 'What would we have to change about Option B to make it equal Option A on time-to-market? Is that worth doing?' | Trade-offs made explicit: 'We chose time over quality. Here's why. Here's what we're accepting. Here's the mitigation plan for quality risk.'", "tags": ["decision-making", "analysis"], "order_index": 6, "formula": null}] },
  { id: "dd000001-0000-4000-8000-000000000004", slug: "intuition-vs-analysis", title: "Intuition vs Analysis: When to Trust Your Gut", description: "Know when to rely on instinct (stable domain, deep expertise) vs structured analysis (novel, high stakes, delayed feedback) — and how to combine both", category: "decision-making", difficulty: 2, estimated_time_minutes: 25, key_concepts: ["Klein's Recognition-Primed Decision (RPD)", "The Deliberation-Without-Attention Effect", "When Intuition Works", "When Intuition Fails", "Calibrating Expert Judgment", "Combining Intuition + Analysis"], use_cases: ["Hiring decisions", "Crisis response", "Creative direction", "Market timing", "Product judgment", "People decisions vs capital decisions"], content: "", concepts: [{"name": "Klein's Recognition-Primed Decision (RPD)", "definition": "Gary Klein's research on firefighters, military commanders, and ICU nurses: experts don't compare options \u2014 they recognize patterns and mentally simulate the first viable option. If the simulation works, they act. If not, they adjust.", "example": "Firefighter commander: sees smoke pattern, 'recognizes' it as a basement fire about to flashover. Doesn't compare 5 strategies \u2014 mentally simulates 'ventilate the roof' and orders it. 30 seconds. Correct. | ICU nurse: infant's vital signs 'don't look right.' Can't articulate why. Orders septic workup. Catches early sepsis before lab confirmation. Pattern recognition, not analysis. | RPD works when: 1) Expert has deep domain experience 2) Environment provides valid cues 3) Feedback is rapid enough to build expertise.", "tags": ["decision-making", "intuition"], "order_index": 1}, {"name": "When Intuition Works", "definition": "Intuition is reliable when: 1) The environment is stable (patterns repeat) 2) You have 10,000+ hours of deliberate practice with rapid feedback 3) The problem type is one you've encountered many times before.", "example": "Chess grandmaster: sees a board, instinctively knows best move. 10,000+ hours, immediate feedback (win/lose), stable rules. Intuition = compressed experience. | Sales veteran: 'This deal isn't going to close.' Can't explain why \u2014 but they've seen the pattern of non-committal language 500 times. | Emergency room doctor: triage decisions in seconds. Deep experience with patterns, rapid feedback on outcomes. | Warning: intuition fails when the environment CHANGES. The chess master is lost playing a new variant with different rules.", "tags": ["decision-making", "intuition"], "order_index": 2}, {"name": "When Intuition Fails", "definition": "Intuition is unreliable when: 1) The environment is novel or changing 2) Feedback is delayed or noisy 3) You lack deep domain experience 4) The problem involves probabilities and base rates your brain can't compute intuitively.", "example": "Stock picking: millions do it by 'gut feel.' Decades of data show 90% of active managers underperform the index. Intuition FAILS because feedback is noisy (random chance looks like skill) and the domain is probabilistic. | Startup founder: 'This product will be huge \u2014 I feel it.' First-time founder, novel market, no feedback yet. This 'gut feel' is just hope. Use Lean Startup instead (build, measure, learn). | Hiring interview: 'I knew within 5 minutes they were perfect.' Research: unstructured interviews have near-zero predictive validity. Structured scoring beats gut feel.", "tags": ["decision-making", "intuition"], "order_index": 3}, {"name": "Combining Intuition + Analysis", "definition": "The best decisions use BOTH: 1) Analysis to generate options and eliminate clearly bad ones 2) Intuition to select between the remaining viable options 3) Analysis again to stress-test the intuitive choice.", "example": "Vendor selection: Analysis: score 10 vendors on weighted criteria. Narrow to top 3. Intuition: meet each top vendor's team. Which one 'feels' like a partner? Select. Analysis: run sensitivity analysis. 'If we overweight cost, does the choice change?' If not, confident decision. | Jeff Bezos: 'If you can make the decision with analysis, make it. If you can't, use intuition \u2014 but know that's what you're doing.' The key is AWARENESS of which mode you're in. | When analysis and intuition conflict: DON'T override analysis with gut unless you can articulate WHY the analysis missed something.", "tags": ["decision-making", "intuition"], "order_index": 4}, {"name": "The Deliberation-Without-Attention Effect", "definition": "For complex decisions, your unconscious mind processes information better when you're NOT consciously focusing on it. Take a break, sleep on it, distract yourself \u2014 then decide. Your unconscious does better integration of complex information.", "example": "Dijksterhuis study: participants given complex car-buying information (12 attributes, 4 options). Group A: deliberate 4 minutes, then decide. Group B: solve anagrams (distraction) for 4 minutes, then decide. Group B made significantly better decisions \u2014 their unconscious mind integrated the complexity better than conscious deliberation. | CEO application: get the full briefing Friday afternoon. DON'T decide. Sleep on it. Decide Monday morning. Your unconscious will have processed patterns your conscious mind missed. | Limitation: only works for decisions with sufficient information. If you lack data, unconscious mind has nothing to process.", "tags": ["decision-making", "intuition"], "order_index": 5, "formula": null}, {"name": "Calibrating Expert Judgment", "definition": "Even experts are overconfident. Calibrate by tracking predictions: 'You said there was a 90% chance of X. Did X happen 90% of the time?' Most experts are at 50-70% for their '90% confident' predictions. Use calibration training to improve.", "example": "Superforecasters (Tetlock): the top 2% of forecasters are significantly better than experts with credentials. What do they do? 1) Track predictions and Brier scores 2) Update beliefs incrementally with new evidence 3) Think in probabilities, not certainties. | Calibration exercise: every week, predict 5 outcomes with confidence levels. Track. After 3 months, your '70% confident' predictions should be right ~70% of the time. | CEO dashboard: include a calibration chart showing predicted vs actual for your leadership team's key predictions.", "tags": ["decision-making", "intuition"], "order_index": 6, "formula": null}] },
  { id: "dd000001-0000-4000-8000-000000000005", slug: "decision-speed-velocity", title: "Decision Speed & Velocity", description: "Know when to decide fast (Type 2/reversible) vs slow (Type 1/irreversible) — and build an organization that makes high-velocity decisions", category: "decision-making", difficulty: 2, estimated_time_minutes: 25, key_concepts: ["Type 1 vs Type 2 Decisions (Bezos)", "70% Rule (Bezos)", "Decision Batching & Cadence", "Disagree and Commit", "Decision Fatigue", "Escalation Paths"], use_cases: ["Product roadmap decisions", "Hiring (speed vs thoroughness)", "Crisis response", "Competitive response", "Org design", "Empowering teams"], content: "", concepts: [{"name": "Type 1 vs Type 2 Decisions (Bezos)", "definition": "Type 1: irreversible, one-way doors \u2014 high stakes, hard to undo. Take time, get broad input, analyze deeply. Type 2: reversible, two-way doors \u2014 low stakes, easy to undo. Decide fast, iterate if wrong.", "example": "Type 1: Acquiring a company for $200M (irreversible). Choosing a major technology platform (5-year lock-in). Firing the CEO (career/life impact). | Type 2: Changing the website's pricing page layout (A/B test, revert in 10 min). Trying a new marketing channel (cancel if it doesn't work). Hiring \u2014 you can fire if wrong, it's a 2-way door. | Most decisions are Type 2 but are treated as Type 1. This creates organizational paralysis. Empowering: 'Is this really a Type 1 decision? No? Then decide by Friday.'", "tags": ["decision-making", "speed"], "order_index": 1}, {"name": "70% Rule (Bezos)", "definition": "Decide when you have ~70% of the information you wish you had. The last 30% typically costs more in time and opportunity than it adds in precision. You can course-correct later.", "example": "Price change: you could test for 6 months and have 95% confidence. Or you could test for 2 weeks at 70% confidence and iterate. If the 6-month delay costs $2M in lost revenue while the 2-week test gets you 90% of the accuracy \u2014 speed wins. | Product launch: waiting for 'perfect' costs market share. Ship at 80% readiness, get real customer feedback, iterate. Perfect is the enemy of done. | When NOT to use: irreversible decisions (safety, legal, major financial). 70% rule applies to TYPE 2 decisions only.", "tags": ["decision-making", "speed"], "order_index": 2}, {"name": "Disagree and Commit", "definition": "Amazon leadership principle: you don't have to agree with a decision, but once it's made, you commit to it fully as if it were your own. This unlocks speed \u2014 you can disagree vigorously in the room, then execute without reservation outside it.", "example": "VP Engineering thinks we should build native mobile app. VP Product thinks PWA is better. CEO decides: PWA. VP Engineering: 'I disagree, but I commit.' Now their job is to make PWA succeed, not to prove it was the wrong choice. | Saves months of re-litigation. Without D&C, the PWA decision gets revisited every time there's a bump. 'I told you so' culture kills velocity. | Requires psychological safety: people must feel safe to disagree BEFORE the decision. If they can't disagree, they'll pretend to commit and sabotage later.", "tags": ["decision-making", "culture"], "order_index": 3}, {"name": "Decision Fatigue", "definition": "The quality of your decisions degrades as you make more of them. Judges grant parole 65% of the time in the morning \u2014 near 0% before lunch. After food, resets to 65%. CEOs face this every day.", "example": "Judge study: favorable rulings drop from 65% to near 0% over the course of a morning session. After lunch break, reset to 65%. Decision fatigue is real and measurable. | CEO mitigation: make important decisions in the morning when cognitive resources are fresh. Batch low-stakes decisions (expense approvals, routine sign-offs) into a single 30-minute block. Standardize routine decisions to eliminate them entirely (delegate, policy, automate). | Steve Jobs' uniform was partially a defense against decision fatigue \u2014 one less trivial decision each morning preserves capacity for big ones.", "tags": ["decision-making", "productivity"], "order_index": 4}, {"name": "Decision Batching & Cadence", "definition": "Group similar decisions into regular cadences (weekly, monthly, quarterly) instead of making them ad-hoc. Creates organizational rhythm, reduces context-switching, and makes decision-making a repeatable process.", "example": "Monday 9am: weekly tactical decisions (approvals, resource allocations). Thursday 2pm: weekly strategic review (pipeline, metrics, blockers). Monthly: resource reallocation, hiring priorities. Quarterly: strategy review, OKR setting, kill/accelerate decisions. | Jeff Bezos: no meetings before 10am. Takes his highest-IQ hours for strategic thinking. BATCHES meetings (and decisions they require) in the afternoon. | Decision cadence prevents constant interruptions. When teams know 'we decide pricing on Thursdays,' they prepare and the decision quality improves.", "tags": ["decision-making", "productivity"], "order_index": 5, "formula": null}, {"name": "Escalation Paths", "definition": "Define WHAT decisions get escalated to whom, under WHAT conditions. Without clear escalation paths, everything floats to the CEO. With them, teams decide more and escalate less.", "example": "Decision rights matrix: Team Lead can approve: budget <$10k, hires at their level, product changes with <1 week of eng effort. Director: budget <$100k, VP-level hires, cross-team product changes. VP: budget <$500k, org structure changes. CEO: budget >$500k, M&A, company strategy. | Escalation TRIGGERS (not just thresholds): 'Escalate if: project is >2 weeks behind schedule, customer churn exceeds 5% in a segment, or a competitor launches a directly competing product.' | Anti-pattern: 'Escalate if you're unsure.' This escalates everything. Better: 'Try to decide. If you would decide differently with $1M more budget, escalate.'", "tags": ["decision-making", "org"], "order_index": 6, "formula": null}] },
  { id: "dd000001-0000-4000-8000-000000000006", slug: "red-teaming-wargaming", title: "Red Teaming & Wargaming", description: "Simulate your opponent\'s best counter-move and stress-test your strategy through adversarial roleplay — find the flaws before your competitor does", category: "decision-making", difficulty: 3, estimated_time_minutes: 30, key_concepts: ["Red Team Structure", "Competitor Simulation", "Pre-Mortem vs War Game", "After-Action Review"], use_cases: ["Competitive strategy", "M&A defense", "Product launch", "Pricing strategy", "Crisis planning", "Annual strategy review"], content: "", concepts: [{"name": "Red Team Structure", "definition": "Assign your best people to play the role of your toughest competitor \u2014 not as a critique exercise, but as an adversarial simulation. Their job is to WIN for the competitor, using only the resources and constraints that competitor actually has.", "example": "Red team role: 'You are the VP Strategy at Competitor X. You've just learned that our company is launching Y. You have a $50M budget, 200 engineers, and a board pushing for aggressive growth. What do you do?' | Rules: 1) Red team must stay in character \u2014 use competitor's resources, not yours 2) Red team's 'success' is competitive victory, not politeness 3) Blue team can't dismiss red team's attacks as 'they'd never do that' without evidence. | Rotation: rotate the red team role. Everyone should practice adversarial thinking. It builds strategic muscle.", "tags": ["decision-making", "competitive-strategy"], "order_index": 1}, {"name": "Competitor Simulation", "definition": "Go beyond 'Porter's Five Forces' and actually roleplay your competitor's next move. Given their capabilities, constraints, incentives, and culture \u2014 what's their most dangerous counter-move?", "example": "Your company launches premium SaaS tool at $99/month. Competitor simulation: Competitor X has 50x your revenue, 1000x your user base, and a board that fears disruption. Most dangerous move: they bundle their free product with a 'Pro' tier matching your features at $0 for 12 months. They can afford to lose $50M on this. You can't. How do you respond? | Scenario 2: Competitor does nothing for 6 months, watches your traction, then acquires you. Is that their optimal move? Plan for both responses.", "tags": ["decision-making", "competitive-strategy"], "order_index": 2}, {"name": "Pre-Mortem vs War Game", "definition": "Pre-mortem: 'We failed. Why?' Internal focus on OUR flaws. War game: 'How would a smart, motivated opponent defeat us?' External focus on THEIR moves. Both are essential; they reveal different failure modes.", "example": "Pre-mortem result: our product launch failed because we underestimated integration complexity and overpromised to early customers. | War game result: Competitor XYZ launched a 'matching' feature 2 weeks before our launch, neutralized our differentiation, and our sales team couldn't articulate why we were still better. | Combined insight: fix integration (pre-mortem finding) AND prepare competitive response playbook (war game finding). The pre-mortem makes your product better; the war game makes your strategy resilient.", "tags": ["decision-making", "competitive-strategy"], "order_index": 3}, {"name": "After-Action Review (AAR) for War Games", "definition": "After every war game round, capture: 1) What did the red team exploit? 2) What surprised the blue team? 3) What assumption did blue team hold that red team disproved? 4) What's the action plan for each vulnerability found?", "example": "AAR template: 'Red Team successfully exploited our single-source supplier dependency.' Action: diversify suppliers, build 30-day inventory buffer. | 'Blue Team was surprised that Red Team could rally regulatory opposition.' Action: hire government relations lead, pre-brief regulators on launch. | 'Assumption disproven: we assumed competitor can't match our price point. Red Team showed they can cross-subsidize from their cash-cow product for 18 months.' Action: adjust pricing strategy accordingly.", "tags": ["decision-making", "competitive-strategy"], "order_index": 4}, {"name": "After-Action Review", "definition": "After every war game round, capture: 1) What did the red team exploit? 2) What surprised the blue team? 3) What assumption did blue team hold that red team disproved? 4) What's the action plan for each vulnerability found?", "example": "AAR template: 'Red Team successfully exploited our single-source supplier dependency.' Action: diversify suppliers, build 30-day inventory buffer. | 'Blue Team was surprised that Red Team could rally regulatory opposition in 60 days.' Action: hire government relations lead. | 'Assumption disproven: we assumed competitor can't match our price point. Red Team showed they can cross-subsidize from cash-cow product for 18 months.' Action: adjust pricing strategy to account for competitor response.", "tags": ["decision-making", "competitive-strategy"], "order_index": 5, "formula": null}] },
  { id: "ee000001-0000-4000-8000-000000000001", slug: "systems-architecture-design", title: "Systems Architecture & Design", description: "Evaluate architecture decisions with CEO-grade frameworks: monolith vs microservices, Conway\'s Law, coupling, evolutionary design, and fitness functions", category: "engineering", difficulty: 3, estimated_time_minutes: 45, key_concepts: ["Monolith vs Microservices Decision Framework", "Conway's Law in Practice", "Coupling & Cohesion", "Evolutionary Architecture", "Strangler Fig Pattern"], use_cases: ["Platform modernization", "Make vs buy architecture decisions", "Scaling from monolith to services", "Technical M&A evaluation", "Replatforming decisions"], content: "", concepts: [{"name": "Monolith vs Microservices Decision Framework", "definition": "Not a technical choice \u2014 an organizational scaling decision. Monolith: faster for <20 engineers, simpler ops, harder to scale teams. Microservices: slower initially, complex ops, enables independent team deployment. Choose based on team count, not vanity.", "example": "5 engineers, one product: MONOLITH. Fastest path to value. Modular monolith with clear boundaries. | 50 engineers, 8 teams: evaluate. Are team boundaries clear? If not, fix org first (Conway's Law). Then extract 2-3 services where team autonomy matters most. | 500 engineers, 30+ teams: microservices appropriate \u2014 but only if each team owns a clear business capability. Never microservices for the sake of microservices. | Amazon 2002 mandate: 'All teams expose data and functionality through service interfaces.' Not 'use microservices.' The BEHAVIOR mattered, not the packaging.", "tags": ["engineering", "architecture"], "order_index": 1}, {"name": "Conway's Law in Practice", "definition": "Organizations design systems that mirror their communication structures. If you have 4 teams, you'll build 4 services. If teams can't communicate, their services won't integrate. Fix the org FIRST, then the architecture follows.", "example": "Reverse Conway: design the target architecture, then REORGANIZE teams to match. Want 5 services? Create 5 autonomous teams, each owning one service. | Symptom: 'Our services are tightly coupled and hard to change.' Diagnosis: your teams are tightly coupled and hard to coordinate. The architecture mirrors the org. | Mitigation: define clear API contracts between teams. The API IS the team boundary. If you can't define the API, the teams shouldn't be separate.", "tags": ["engineering", "org"], "order_index": 2}, {"name": "Coupling & Cohesion", "definition": "High cohesion = related things live together (one module = one responsibility). Low coupling = modules don't depend on each other's internals. Good architecture maximizes cohesion and minimizes coupling.", "example": "High cohesion: 'Order management' module handles orders, payments, receipts. Everything about orders in one place. | Low coupling: changing the 'Email' module doesn't require changes to 'Order' module. They communicate through a clean API, not shared database tables. | Red flag: 'Every time we change the pricing engine, the checkout flow breaks.' This is high coupling. Solution: define a clean pricing API with a stable interface \u2014 checkout doesn't need to know HOW pricing works.", "tags": ["engineering", "architecture"], "order_index": 3}, {"name": "Evolutionary Architecture", "definition": "Architecture that supports incremental, guided change over time. Uses fitness functions (automated tests verifying architecture properties) to prevent degradation. The opposite of 'big upfront design' that calcifies.", "example": "Start with a modular monolith. Add fitness functions: 'no circular dependencies between modules' (automated check in CI). 'API response p95 < 200ms.' As the system grows, extract modules into services when fitness functions show a boundary is being violated. | Anti-pattern: 'We'll design the perfect architecture upfront.' Requirements change, technology changes, team composition changes. Architecture must evolve. Build for today's known requirements with tomorrow's flexibility. | Fitness function example: 'No service can directly access another service's database.' Automated test checks this at every PR. Architecture governance without architecture meetings.", "tags": ["engineering", "architecture"], "order_index": 4}, {"name": "Strangler Fig Pattern", "definition": "Migrate from legacy to new system incrementally: 1) Build new alongside old 2) Route traffic gradually (10%, 50%, 100%) 3) Retire old when unused. Named after figs that grow around host trees \u2014 the new system 'strangles' the old.", "example": "Legacy checkout system in Java. New checkout in Go. Strangler: 1) Deploy new checkout alongside old. 2) Route 5% of traffic to new. Monitor errors, latency, revenue. 3) If good, increase to 25%, 50%, 100%. 4) When old receives 0 traffic for 30 days, decommission. | Big bang rewrite: rewrite everything, switch over on launch day. 80% fail. Strangler is safer, faster to value, and reversible. | CEO question: 'How long until the old system is gone?' If answer is 'never,' the strangler hasn't strangled \u2014 it's just added complexity.", "tags": ["engineering", "migration"], "order_index": 5}] },
  { id: "ee000001-0000-4000-8000-000000000002", slug: "site-reliability-engineering", title: "Site Reliability Engineering (SRE) for CEOs", description: "Balance feature velocity vs reliability with data-driven error budgets, SLI/SLO/SLA frameworks, and blameless incident management", category: "engineering", difficulty: 3, estimated_time_minutes: 35, key_concepts: ["SLI, SLO, SLA Hierarchy", "Error Budgets", "Blameless Postmortems", "Chaos Engineering"], use_cases: ["Reliability vs velocity trade-offs", "Setting uptime/availability targets", "Incident management process", "Engineering investment allocation", "Customer SLA negotiation"], content: "", concepts: [{"name": "SLI, SLO, SLA Hierarchy", "definition": "SLI = raw metric (99.95% requests succeed). SLO = internal target (\u226599.9% success rate). SLA = customer-facing promise with penalties (<99.5% = 10% credit). SLO should be tighter than SLA \u2014 a safety buffer.", "example": "Gmail: SLI = request success rate. SLO = 99.9% (internal, drives on-call alerts). SLA = 99.5% (customer-facing, with service credits). SLO is 4x stricter than SLA \u2014 there's a buffer before customers feel pain. | Stripe: SLI = API availability. SLO = 99.95% for payments. SLA = 99.9% to customers. Payment failure is revenue failure. | CEO question: 'What's our buffer between SLO and SLA?' If SLO = SLA, you have no margin. You'll breach SLA whenever you breach SLO. That's dangerous.", "tags": ["engineering", "reliability"], "order_index": 1}, {"name": "Error Budgets", "definition": "Error budget = 1 - SLO. If your SLO is 99.9% uptime, your error budget is 0.1% (43 minutes/month of acceptable downtime). This is NOT a target to hit \u2014 it's a budget to SPEND on innovation and risk.", "example": "Error budget of 0.1% downtime/month. January: no outages, error budget fully available. PM: 'Can we do a risky database migration?' SRE: 'You have 43 minutes of budget. If the migration causes <10 min of issues, yes.' Budget spent = 0 min. | February: a 30-minute outage. Error budget used: 30/43 min. Remaining: 13 min. March: freeze all risky changes \u2014 we're over budget if anything else goes wrong. | Error budgets turn 'reliability vs velocity' from opinion to math. Product can ask for risk; SRE quantifies the cost.", "tags": ["engineering", "reliability"], "order_index": 2}, {"name": "Blameless Postmortems", "definition": "After every incident, write a postmortem: 1) Timeline (what happened, when) 2) Contributing factors (not 'who caused it') 3) Action items (prevent recurrence). No blame, no names \u2014 systems failed, not people.", "example": "Bad postmortem: 'John pushed a bad config and caused outage.' Result: nobody admits mistakes. | Good: 'Timeline: 10:15, config change deployed. 10:16, alerts fired. 10:22, rollback complete. Contributing factors: no automated config validation, manual deployment process, alert-to-response gap of 6 min. Action: add config linting in CI, deploy with canary, reduce alert response time to <2 min.' | John's name never appears. The SYSTEM lacked safeguards. Fix the system, not the person.", "tags": ["engineering", "reliability"], "order_index": 3}, {"name": "Chaos Engineering", "definition": "Deliberately inject failures into production to verify the system handles them gracefully. 'What happens if the payment processor goes down?' Test it \u2014 don't wait for it to happen at 3am.", "example": "Netflix Chaos Monkey: randomly terminates production instances during business hours. Engineers build resilient systems because they KNOW Chaos Monkey is watching. | Game day: simulate a full database outage. Can the team recover within SLO? Runbook works in theory \u2014 does it work when you're panicking at 11pm? | Start small: kill one non-critical service. Observe. Expand to critical paths. Chaos engineering reveals assumptions: 'we thought the failover was automatic \u2014 it required manual DNS change.'", "tags": ["engineering", "reliability"], "order_index": 4}] },
  { id: "ee000001-0000-4000-8000-000000000003", slug: "technical-diligence", title: "Technical Diligence for CEOs", description: "Evaluate any company\'s technology stack, team quality, tech debt, and security posture — the engineering equivalent of financial due diligence", category: "engineering", difficulty: 3, estimated_time_minutes: 30, key_concepts: ["Code & Architecture Quality Assessment", "Engineering Team Assessment", "Tech Debt Audit", "Scalability & Infrastructure Assessment"], use_cases: ["M&A technology evaluation", "Investment due diligence", "Internal tech health check", "Board-level tech briefing", "Crisis diagnosis"], content: "", concepts: [{"name": "Code & Architecture Quality Assessment", "definition": "Quick signals of codebase health: test coverage, static analysis findings, dependency freshness, architecture documentation existence, and deployment frequency. These are leading indicators of future engineering velocity.", "example": "Red flags: test coverage <20% (every change risks breaking things), dependencies >2 years out of date (security + compatibility risk), no architecture diagrams exist (tribal knowledge only), deploy frequency <1/week (slow feedback loops). | Green flags: >60% test coverage on critical paths, automated deploy pipeline, architecture decision records (ADRs) for major choices, static analysis passing in CI. | CEO question: 'If the entire engineering team quit tomorrow, could a new team understand and maintain this system in 3 months?' The answer reveals documentation and architecture quality.", "tags": ["engineering", "diligence"], "order_index": 1}, {"name": "Engineering Team Assessment", "definition": "Bus factor: how many key people could get 'hit by a bus' before the system becomes unmaintainable? 1-2 people = extreme risk. Tenure distribution: if 50%+ of engineers have <1 year tenure, institutional knowledge is fragile.", "example": "Bus factor assessment: 'Who knows the payment system?' Answer: 'Just Alex.' Bus factor = 1. Risk: Alex leaves, payment system has zero experts. Mitigation: pair programming, documentation, rotation. | Tenure: 80% of engineers hired in last 12 months. Red flag: nobody remembers WHY architectural decisions were made. Cargo cult engineering. | Hiring velocity: how long to fill an open role? >3 months = talent bottleneck. High attrition among senior engineers = cultural or technical problems driving them away.", "tags": ["engineering", "people"], "order_index": 2}, {"name": "Tech Debt Audit", "definition": "Quantify tech debt not as 'we have tech debt' (everyone does) but as a PERCENTAGE of engineering capacity consumed by maintenance vs new features. >30% maintenance capacity = tech debt crisis requiring dedicated paydown.", "example": "Survey engineers: 'What % of your time in the last quarter was spent on: bug fixes, refactoring, keeping the lights on vs new features?' Results: 45% maintenance = tech debt consuming almost half your engineering capacity. That's a $450k/quarter tax on a 10-person team. | Tech debt balance sheet: 'To reach 80% feature capacity, we need to invest 3 person-months in test coverage, 2 months in CI/CD, 1 month in monitoring.' Cost: $100k. ROI: 20% more feature output ongoing. | Payback period: $100k investment / $90k/month additional feature capacity = 1.1 month payback. Board-ready math.", "tags": ["engineering", "tech-debt"], "order_index": 3}, {"name": "Scalability & Infrastructure Assessment", "definition": "Can the current infrastructure handle 10x growth without fundamental rearchitecture? What breaks first? What's the cloud bill at 10x current traffic? These are CEO-level questions for any tech company.", "example": "Current: 10,000 requests/min, $5k/month cloud bill. At 100,000 req/min: does the architecture scale linearly or does it need a complete rewrite? If it needs rewrite, that's a hidden future cost. | Database: currently at 50GB, growing 2GB/month. At 10x users, 200GB in 12 months. Does the database handle 500GB without performance degradation? If not, migration cost must be factored into growth planning. | CEO test: ask engineering 'what limits our growth?' If they can't name the FIRST thing that will break, they haven't done a scalability assessment.", "tags": ["engineering", "infrastructure"], "order_index": 4}] },
  { id: "ee000001-0000-4000-8000-000000000004", slug: "data-strategy-analytics", title: "Data Strategy & Analytics Engineering", description: "Turn data into your second most valuable asset: data mesh vs warehouse vs lake, metrics layers, experimentation platforms, GDPR/CCPA governance", category: "engineering", difficulty: 3, estimated_time_minutes: 40, key_concepts: ["Data Warehouse vs Lake vs Mesh", "Metrics Layer & Single Source of Truth", "Data Quality & Observability", "GDPR/CCPA Compliance Engineering"], use_cases: ["Data infrastructure investment", "Compliance readiness", "Analytics team structure", "Data-driven culture building", "Data product development", "M&A integration data strategy"], content: "", concepts: [{"name": "Data Warehouse vs Lake vs Mesh", "definition": "Warehouse (Snowflake, BigQuery): structured SQL, fast queries, BI-friendly. Lake (S3, ADLS): raw files, flexible schemas, cheap storage. Mesh: decentralized ownership \u2014 each domain owns its data and exposes it as a product.", "example": "Startup at 20 people: simple PostgreSQL + Metabase. Don't over-engineer. | Scale-up at 200: central data warehouse (Snowflake) + dbt for transformations. Data team of 3-5 owns the warehouse. | Enterprise at 2000+: data mesh. Marketing team owns marketing data, publishes it as a product. Other teams consume it through APIs. Central platform team provides tooling, not governance. | Common mistake: starting with data mesh before you have the organizational maturity to support decentralized ownership. Start centralized, distribute when teams demand autonomy.", "tags": ["engineering", "data"], "order_index": 1}, {"name": "Metrics Layer & Single Source of Truth", "definition": "A semantic layer between raw data and every dashboard. Define 'Revenue' once as code \u2014 every dashboard, every report, every email pulls the same definition. No more arguing about whose numbers are right.", "example": "Metrics layer (dbt/MetricFlow): define 'monthly_recurring_revenue' once with business logic (exclude trials longer than 14 days, include annual contracts amortized monthly). Sales dashboard, Finance report, and Product analytics all pull the SAME definition. | Before metrics layer: 4 teams, 4 definitions of MRR, 4 different numbers. Weekly 2-hour meetings to reconcile. After: 0 reconciliation meetings. | CEO test: ask 3 different teams for 'monthly active users.' If you get 3 different numbers, you need a metrics layer. Not next quarter \u2014 this quarter.", "tags": ["engineering", "data"], "order_index": 2}, {"name": "Data Quality & Observability", "definition": "Data observability: freshness (is data arriving on time?), completeness (are rows missing?), accuracy (do values make sense?), lineage (where did this data come from?). Without it, decisions are made on bad data.", "example": "Revenue dashboard shows 50% drop on Monday. Is it real (business problem) or a data pipeline issue? Data observability shows: 'daily ETL for transactions table failed \u2014 0 rows loaded since Friday.' Not a business problem, a data problem. Fix the pipeline, not the strategy. | Data freshness SLAs: 'Sales data must be available by 8am daily.' If not, automated alert fires. | Lineage: 'The churn metric in the board deck \u2014 trace it back. It comes from the CRM \u2192 ETL \u2192 dbt model \u2192 Looker dashboard.' If you can't trace the lineage, you can't trust the number.", "tags": ["engineering", "data"], "order_index": 3}, {"name": "GDPR/CCPA Compliance Engineering", "definition": "Data privacy regulations require engineering changes: data inventory (what data do you have?), data subject access requests (give users their data), right to deletion (purge user data everywhere), consent management.", "example": "GDPR DSAR: user emails 'send me all my data.' You have 30 days. Engineering challenge: user data scattered across 12 services, 3 databases, 2 data warehouses. Without a data inventory, this takes weeks. With one, it's automated. | Right to deletion: user says 'delete my data.' You must purge from primary DB, backups, analytics warehouse, and logs. Hard-delete from everywhere. Engineering must support this. | Fine risk: GDPR fines up to 4% of global revenue. For a $50M company, that's $2M. Data compliance engineering costs $200k/year. ROI = 10x risk reduction.", "tags": ["engineering", "compliance"], "order_index": 4}] },
  { id: "ee000001-0000-4000-8000-000000000005", slug: "ai-ml-engineering-mlops", title: "AI/ML Engineering & MLOps", description: "From model lifecycle to LLM deployment: feature stores, training pipelines, monitoring, and AI governance — every CEO\'s #1 technology framework", category: "engineering", difficulty: 4, estimated_time_minutes: 45, key_concepts: ["ML Model Lifecycle", "Feature Stores & Training Pipelines", "LLM / Foundation Model Strategy", "AI Governance & Responsible AI"], use_cases: ["AI strategy development", "Build vs buy ML platform", "LLM integration decisions", "AI team structure", "Regulatory AI compliance", "Make vs buy AI capabilities"], content: "", concepts: [{"name": "ML Model Lifecycle", "definition": "ML is NOT software. Software: write code \u2192 test \u2192 deploy \u2192 done. ML: collect data \u2192 train \u2192 evaluate \u2192 deploy \u2192 MONITOR DRIFT \u2192 retrain \u2192 repeat. 80% of the work is post-deployment (monitoring, retraining, data pipelines). CEOs underestimate this.", "example": "Fraud detection model: trained on 2024 data. In 2025, fraudsters change their patterns (concept drift). Model accuracy drops from 95% to 72%. Nobody notices \u2014 millions in fraud losses. | ML lifecycle investment: training the first model = 20% of cost. Monitoring, retraining pipelines, data quality = 80%. Budget accordingly. | CEO question: 'What happens when the model starts degrading in production?' If the answer is 'we don't know, we haven't monitored it,' you have an ML time bomb.", "tags": ["engineering", "ml"], "order_index": 1}, {"name": "Feature Stores & Training Pipelines", "definition": "Feature store = centralized repository of ML features (user_age_last_30_days, avg_purchase_value). Without it, every ML team builds the same features from scratch. With it, features are shared, consistent, and versioned.", "example": "Without feature store: team A builds 'user_lifetime_value' from raw data. Team B builds 'customer_ltv' from same raw data but different logic. Two identical-sounding features with different values. Models produce different results. Argument ensues. | With feature store: 'user_lifetime_value' defined once. Both teams use the same feature. Models are comparable. | Feature store ROI: 3 data scientists spending 30% of time rebuilding features = $200k/year waste. Feature store costs $100k to implement. Pays back in 6 months.", "tags": ["engineering", "ml"], "order_index": 2}, {"name": "LLM / Foundation Model Strategy", "definition": "Build vs fine-tune vs prompt vs RAG. Build: train from scratch ($10M+, for foundational models only). Fine-tune: adapt existing model ($50k-500k, for domain-specific tasks). Prompt: engineer the input ($0 in model cost, high in prompt engineering). RAG: retrieve + augment + generate ($10k-100k, for knowledge-base tasks).", "example": "Startup: don't build a model from scratch. Use GPT-4/Claude API with prompt engineering for most tasks. Cost: $0-5k/month. Time to market: days. | Enterprise with proprietary data: fine-tune open-source model (Llama 3) on your proprietary support tickets. Better accuracy than generic LLM. Cost: $100k compute + 2 months engineering. | Customer support chatbot: RAG architecture \u2014 retrieve relevant docs from knowledge base, augment the prompt, generate answer. Cheaper and more accurate than fine-tuning for this use case. | CEO rule: start with prompt engineering. Move to RAG when you need factual grounding. Move to fine-tuning when prompt+RAG doesn't reach target accuracy.", "tags": ["engineering", "ai"], "order_index": 3}, {"name": "AI Governance & Responsible AI", "definition": "Framework for ensuring AI is safe, fair, and compliant: bias testing, explainability, human-in-the-loop for high-stakes decisions, model cards for transparency, and alignment with emerging regulations (EU AI Act).", "example": "Bias testing: your hiring model scores male candidates 15% higher on average. Why? Training data reflects historical hiring patterns (biased). Debiasing required before deployment. | Explainability: bank denies loan. Customer asks 'why?' If your model can't explain the decision (it's a black box), you may be violating fair lending laws. Use explainable models or SHAP/LIME for post-hoc explanations. | Human-in-the-loop: AI flags fraudulent transactions. Below $500 = auto-block. Over $500 = human reviews before blocking. Thresholds calibrated to false positive rate. | EU AI Act (2025+): high-risk AI (hiring, credit, healthcare) requires conformity assessment, human oversight, transparency. Budget $200k-500k for compliance.", "tags": ["engineering", "ai", "compliance"], "order_index": 4}] },
  { id: "ee000001-0000-4000-8000-000000000006", slug: "security-compliance-engineering", title: "Security & Compliance Engineering", description: "Shift-left security, zero trust architecture, threat modeling, SOC2/ISO 27001 — evaluate your security posture like a CEO, not a security engineer", category: "engineering", difficulty: 3, estimated_time_minutes: 35, key_concepts: ["Shift-Left Security / DevSecOps", "Zero Trust Architecture", "Threat Modeling (STRIDE)", "SOC2 / ISO 27001 Compliance"], use_cases: ["Security investment decisions", "Compliance certification pursuit", "Vendor security assessment", "Board security briefing", "Security team structuring"], content: "", concepts: [{"name": "Shift-Left Security / DevSecOps", "definition": "Integrate security testing into the development pipeline, not as a separate gate at the end. SAST (static analysis) in IDE, dependency scanning in CI, container scanning before deploy. Catch vulnerabilities when they cost $100 to fix, not $10,000 in production.", "example": "Developer writes code \u2192 SAST scanner checks for SQL injection vulnerabilities in the IDE immediately (cost: $0, 5 min). vs finding SQL injection in penetration testing 6 months later (cost: $5k to fix, potential breach in interim). | CI pipeline automatically scans dependencies for known vulnerabilities (npm audit, OWASP Dependency Check). Fails the build if critical CVEs found. | Container images scanned before deployment. 'This image has a critical vulnerability \u2014 blocking deploy until patched.' No human approval needed \u2014 automated policy.", "tags": ["engineering", "security"], "order_index": 1}, {"name": "Zero Trust Architecture", "definition": "Abandon the 'trusted internal network' model. Every request, whether from the internet or from another internal service, must be authenticated and authorized. Microsegmentation: even if an attacker breaches one service, they can't reach others.", "example": "Traditional: corporate VPN = trusted. Once inside, access everything. Breach: attacker steals VPN credentials \u2192 full network access. | Zero Trust: every service-to-service call requires authentication (mTLS, API tokens). No implicit trust based on network location. Breach: attacker compromises Service A. Service A's credentials only allow access to Service B (not C, D, E). Blast radius limited. | Google BeyondCorp: eliminated corporate VPN entirely. Every access request evaluated based on device, user, and context \u2014 not network location. Employees work from anywhere with the same security posture.", "tags": ["engineering", "security"], "order_index": 2}, {"name": "Threat Modeling (STRIDE)", "definition": "STRIDE: Spoofing (pretending to be someone else), Tampering (modifying data), Repudiation (denying an action), Information Disclosure (leaking data), Denial of Service (overwhelming the system), Elevation of Privilege (gaining unauthorized access). Model threats for each component.", "example": "Payment system threat model: Spoofing (attacker impersonates a merchant to receive payments). Mitigation: API key + IP whitelist + request signing. | Tampering (attacker modifies payment amount mid-transaction). Mitigation: HTTPS, request integrity checks, idempotency keys. | Information Disclosure (attacker reads customer credit card data). Mitigation: tokenization (never store raw card numbers), encryption at rest, access logging. | STRIDE applied to each system component = structured security analysis. Much better than 'is our system secure?' (unanswerable).", "tags": ["engineering", "security"], "order_index": 3}, {"name": "SOC2 / ISO 27001 Compliance", "definition": "SOC2 (US): proves you have controls for security, availability, processing integrity, confidentiality, privacy. ISO 27001 (international): information security management system. Both require 6-12 months of preparation and are audited annually.", "example": "SOC2 Type I: point-in-time assessment. 'As of June 1, were controls in place?' Quicker, cheaper ($30-80k). | SOC2 Type II: assessment over a period (typically 6-12 months). 'Were controls operating effectively from Jan-June?' More rigorous, enterprise customers demand this. ($50-150k). | Timeline: 3 months to design and implement controls \u2192 1 month of evidence collection \u2192 2 months of audit \u2192 report issued at month 6. | CEO decision: pursue SOC2 when enterprise customers >20% of pipeline AND you're losing deals to 'security review' delays. Not before \u2014 premature compliance is expensive overhead.", "tags": ["engineering", "compliance"], "order_index": 4}] },
  { id: "ff000001-0000-4000-8000-000000000001", slug: "capital-allocation", title: "Capital Allocation Framework", description: "The CEO\'s most important recurring decision: reinvest, acquire, return to shareholders, pay down debt, or hold cash — a Munger/Buffett-style framework", category: "financial", difficulty: 3, estimated_time_minutes: 35, key_concepts: ["Capital Allocation Hierarchy", "ROIC vs WACC Test", "Share Buyback Math", "Dividend Policy"], use_cases: ["Annual capital allocation", "Board presentations", "Post-fundraising planning", "M&A vs build decisions", "Activist investor response"], content: "", concepts: [{"name": "Capital Allocation Hierarchy", "definition": "Ranked uses of capital from highest expected return to lowest: 1) Reinvest in existing business (ROIC > WACC) 2) Strategic M&A 3) Share buybacks (if undervalued) 4) Dividends 5) Debt paydown (if leverage > target) 6) Cash reserve (optionality). Start at #1 and work down.", "example": "Apple: $100B cash. #1: reinvest in R&D, retail, supply chain (ROIC > 30%). #2: acquire smaller tech companies ($1-2B each). #3: massive buyback program (felt stock was undervalued). #4: dividend (modest, initiated 2012). Result: extraordinary value creation. | Common mistake: holding cash 'just in case.' Unless you can identify specific optionality worth more than deploying capital, you're destroying value. | Board question: 'Why are we holding $500M in cash?' Answer must be specific: 'For acquisition #X expected to close in Q3.' Not 'for general rainy day.'", "tags": ["financial", "capital-allocation"], "order_index": 1}, {"name": "ROIC vs WACC Test", "definition": "ONLY invest when expected return on invested capital exceeds your weighted average cost of capital. ROIC > WACC = value creation. ROIC < WACC = value destruction \u2014 you'd create more value by returning capital to shareholders.", "example": "Project requires $10M. Expected return: 15% ROIC. Your WACC: 10%. Spread = 5%. Invest \u2014 you're creating $500k/year in value. | Same $10M, expected return: 8%. WACC: 10%. Spread = -2%. DON'T invest \u2014 you're destroying $200k/year. Better to buy back shares or hold cash. | Most public companies have WACC of 8-12%. Most startups have WACC of 15-25% (higher risk). A startup reinvesting at 12% ROIC when WACC is 20% is destroying value \u2014 even if the project is 'profitable.'", "tags": ["financial", "capital-allocation"], "order_index": 2}, {"name": "Share Buyback Math", "definition": "Buy back shares ONLY when stock price < intrinsic value. If the stock is undervalued, a buyback is the highest-return capital allocation. If overvalued, it's value-destroying \u2014 you're overpaying for your own shares.", "example": "Company earns $100M, 100M shares, EPS = $1. Stock at $10 (P/E=10). Intrinsic value: $15. Buyback: spend $100M to retire 10M shares. Now 90M shares, EPS = $1.11 (+11%). Value created. | Stock at $20 (P/E=20, above intrinsic $15). Spend $100M to retire 5M shares. Now 95M shares, EPS = $1.05 (+5%). But you spent $100M to get $75M of intrinsic value. $25M destroyed. | Many companies buy back shares at all-time highs. This is often value-destructive but boosts executive compensation (EPS growth). CEO should resist this.", "tags": ["financial", "capital-allocation"], "order_index": 3}, {"name": "Dividend Policy", "definition": "Dividends signal confidence in stable cash flows. But they're 'sticky' \u2014 cutting a dividend is seen as a crisis signal. Only initiate when cash flows are predictably stable. Growth companies: 0% payout. Mature: 20-50% payout.", "example": "Apple paid no dividend 1995-2012 (growth mode). Initiated $2.65/share in 2012 when cash flows became massive and predictable. Now ~$1B/month in dividends \u2014 sustainable, growing, signals stability. | AT&T cut dividend in 2022 after decades of increases. Stock dropped 30% in a week. The 'sticky' nature of dividends: cutting signals distress even if the business is just restructuring. | Payout ratio = dividends / earnings. Mature company target: 30-50%. Growth company: 0%. Declining company: may pay >100% (unsustainable \u2014 they're liquidating).", "tags": ["financial", "capital-allocation"], "order_index": 4}] },
  { id: "ff000001-0000-4000-8000-000000000002", slug: "working-capital-management", title: "Working Capital Management", description: "Master the cash conversion cycle: optimize DIO, DSO, DPO — free up cash from operations without debt or equity", category: "financial", difficulty: 2, estimated_time_minutes: 25, key_concepts: ["Cash Conversion Cycle (CCC)", "Days Sales Outstanding (DSO)", "Negative Working Capital", "Working Capital Optimization"], use_cases: ["Cash flow improvement", "Funding growth internally", "Turnaround situations", "Seasonal business management", "Supply chain financing"], content: "", concepts: [{"name": "Cash Conversion Cycle (CCC)", "definition": "CCC = DIO + DSO - DPO. The number of days between paying your supplier (cash out) and collecting from your customer (cash in). Every day you can reduce the CCC frees up cash equal to (daily revenue \u00d7 days reduced).", "example": "Current: DIO=45 days, DSO=60 days, DPO=30 days. CCC = 45+60-30 = 75 days. On $10M revenue, that's $2.05M tied up in working capital. | Improve: negotiate supplier terms from 30 to 45 days. DPO now 45. CCC = 45+60-45 = 60 days. 15 days freed = $410k freed cash. | Amazon: CCC is NEGATIVE (-30 days). Customers pay instantly (credit card), Amazon pays suppliers in 60-90 days. Customers finance Amazon's operations. They grow faster with less capital.", "tags": ["financial", "working-capital"], "order_index": 1}, {"name": "Days Sales Outstanding (DSO)", "definition": "DSO = (Accounts Receivable / Revenue) \u00d7 365. The average number of days it takes customers to pay you. Lower = better cash flow. DSO > 45 days for non-enterprise is a red flag \u2014 you're lending money to customers for free.", "example": "Current: AR = $2M, Revenue = $12M. DSO = (2/12)\u00d7365 = 61 days. Customers take 2 months to pay. | Reduce to 30 days: offer 2% discount for payment within 10 days. 30% of customers take it, DSO drops to 45 days. Cash freed: $530k. | Enterprise SaaS: DSO of 45-60 days is normal (large customers have procurement processes). SMB: DSO > 30 days is a problem. | Red flag: DSO increasing quarter over quarter while revenue is flat. Customers are stretching payments \u2014 cash crisis incoming.", "tags": ["financial", "working-capital"], "order_index": 2}, {"name": "Negative Working Capital", "definition": "Receive cash from customers BEFORE you have to pay your suppliers. DSO < DPO + DIO means customers are financing your business. Dell perfected this: build-to-order, customer pays immediately, Dell pays suppliers in 30 days.", "example": "Dell: Customer orders PC online, pays by credit card immediately (DSO=0). Dell builds it in a day (DIO=1). Dell pays component suppliers in 30 days (DPO=30). CCC = 0+1-30 = -29 days. Customer money sitting in Dell's bank account for 29 days before suppliers get paid. | Insurance: premiums paid upfront (DSO negative), claims paid later. Negative working capital = float. | SaaS with annual prepay: customer pays $12k upfront. You recognize $1k/month. The $11k advance is free working capital. Annual contracts are as much a cash flow tool as a retention tool.", "tags": ["financial", "working-capital"], "order_index": 3}, {"name": "Working Capital Optimization", "definition": "For every $1 freed from working capital, you avoid $1 of fundraising dilution. A company with $10M revenue can typically free $1-3M in cash through working capital optimization \u2014 equivalent to a $1-3M funding round at $0 dilution.", "example": "Invoice factoring: sell your AR to a factor at 97 cents on the dollar. Get cash immediately instead of waiting 60 days. Cost: 3% per 60 days = 18% APR. Better: negotiate customer payment terms first. Factoring is expensive \u2014 use as last resort. | Supply chain financing: your suppliers get paid early by a bank, at a rate based on YOUR credit rating (not theirs). You pay the bank at normal DPO. Supplier happy (paid early), you happy (longer DPO). | Dynamic discounting: 'Pay us within 10 days, get 2% off. Pay in 30, full price.' Let suppliers choose. Many will take the discount \u2014 you get cash faster.", "tags": ["financial", "working-capital"], "order_index": 4}] },
  { id: "ff000001-0000-4000-8000-000000000003", slug: "fundraising-capital-structure", title: "Fundraising & Capital Structure", description: "Debt vs equity decisions, term sheet economics, liquidation preferences, dilution waterfalls, and venture debt — raise capital without giving away your company", category: "financial", difficulty: 3, estimated_time_minutes: 40, key_concepts: ["Debt vs Equity Decision", "Liquidation Preferences", "Dilution Waterfall", "Venture Debt"], use_cases: ["Series fundraising", "IPO preparation", "Venture debt evaluation", "Board-level capital structure decisions", "Down-round planning"], content: "", concepts: [{"name": "Debt vs Equity Decision", "definition": "Debt: non-dilutive, tax-deductible interest, requires fixed repayment, increases bankruptcy risk. Equity: dilutive, no repayment required, patient capital, aligns investors with your success. Most startups should raise equity; profitable companies should consider debt.", "example": "Startup at $2M ARR, burning $500k/month. Can't service debt \u2014 debt would kill them. Raise equity. | Profitable SaaS at $10M ARR, 20% EBITDA margin. Could raise $5M debt at 8% interest = $400k/year. No dilution. Debt is better here. | Venture debt: you just raised $10M equity. Borrow $2M at 12% with warrants. Extends runway 4 months without raising more equity. Bridge to profitability or to next funding round. But only available AFTER raising equity.", "tags": ["financial", "fundraising"], "order_index": 1}, {"name": "Liquidation Preferences", "definition": "The order and amount investors get paid in an exit. 1x non-participating (standard, founder-friendly): investor gets their money back OR converts to common at their ownership %. 2x participating (aggressive, investor-friendly): gets 2x money back AND their pro-rata share \u2014 can leave founders with zero.", "example": "Company sells for $30M. VC invested $5M for 20% with 1x non-participating. VC gets MAX($5M, 20%\u00d7$30M=$6M) = $6M. Remaining $24M split among common. Founder with 60% gets $18M. | Same scenario but 2x PARTICIPATING: VC gets 2\u00d7$5M=$10M (preference) PLUS 20%\u00d7($30M-$10M)=$4M. Total = $14M. Remaining $16M to common. Founder gets $12M. | With 2x participating, VC gets $14M on a $30M exit while putting in only $5M. Founders lose millions. TERM SHEET MATH MATTERS.", "tags": ["financial", "fundraising"], "order_index": 2}, {"name": "Dilution Waterfall", "definition": "Model how ownership changes through each funding round + ESOP. Seed \u2192 Series A \u2192 Series B \u2192 exit. Each round dilutes prior shareholders. A founder starting at 80% may end at 15% after Series C + ESOP.", "example": "Seed: Founders 80%, investors 20%. Series A: $10M at $40M pre = 20% new dilution. Post-Series A: Founders 64%, Seed 16%, Series A 20%. ESOP: 10% pool created. If pre-money (dilutes founders only): Founders drop from 64% to 56%. | Series B: $20M at $80M pre = 20% dilution. Post: Founders 45%, Seed 13%, A 16%, ESOP 8%, B 20%. | Exit at $200M: Founders' 45% = $90M. But if there are liquidation preferences and ESOP refreshes, the effective payout could be much less. Model the waterfall, not just cap table percentages.", "tags": ["financial", "fundraising"], "order_index": 3}, {"name": "Venture Debt", "definition": "A loan to extend runway between equity rounds. Typically 10-25% of the last equity round amount, 3-5 year term, 10-15% interest + warrants (0.5-2% of company). Only available AFTER you've raised equity.", "example": "You just raised $10M Series A. Venture debt: borrow $2.5M. Interest-only for 12-18 months, then amortize over 36 months. Warrants: 1% of company. Raises $2.5M at cost of 1% dilution + interest. Much cheaper than raising equity. | Use case: you're at $4M ARR, targeting $6M before Series B. Venture debt extends your runway by 6 months to hit the milestone. Better than raising bridge round at a down-round. | Risk: if you don't raise Series B before you need to repay, you're in trouble. Venture debt should fund GROWTH to the next milestone, not extend a dying company.", "tags": ["financial", "fundraising"], "order_index": 4}] },
  { id: "ff000001-0000-4000-8000-000000000004", slug: "ma-financial-modeling", title: "M&A Financial Modeling", description: "Accretion/dilution analysis, synergy quantification, purchase price allocation, earnout design, and goodwill — the CEO\'s M&A finance toolkit", category: "financial", difficulty: 4, estimated_time_minutes: 40, key_concepts: ["Accretion/Dilution Analysis", "Synergy Quantification", "Goodwill & Intangibles", "Earnout Modeling"], use_cases: ["M&A evaluation", "Board deal approval", "Negotiation strategy", "Integration planning", "Post-acquisition measurement"], content: "", concepts: [{"name": "Accretion/Dilution Analysis", "definition": "Compare pro forma EPS (buyer + target combined) vs standalone buyer EPS. Accretive: combined EPS > standalone EPS (deal 'pays for itself'). Dilutive: combined EPS < standalone (deal reduces earnings). Most deals targeting <24 months to accretion.", "example": "Buyer earns $100M, 50M shares, EPS = $2.00. Target earns $20M, purchase price $200M (10x). Funded with 50% cash ($100M at 6% interest) + 50% stock (5M new shares). Pro forma: earnings $120M - $6M interest = $114M. Shares: 55M. EPS = $2.07. Accretive by $0.07 (3.5%). | If funded all-cash with debt at 6%: EPS = ($120M-$12M)/50M = $2.16. More accretive but more leverage. | Earnout scenario: only pay part of purchase price if targets met. Reduces risk of overpaying for synergies that don't materialize.", "tags": ["financial", "m-a"], "order_index": 1}, {"name": "Synergy Quantification", "definition": "Cost synergies (headcount elimination, vendor consolidation, facility closing): highly reliable, realize 80-100%. Revenue synergies (cross-selling, bundled offerings, market expansion): less reliable, realize 20-50%. Always separate them in your model.", "example": "Cost synergy: combine 2 finance departments, eliminate 5 redundant positions at $150k each = $750k/year. Realization: 90% certain = $675k in model. | Revenue synergy: 'Our sales team will sell their product to our customers.' Estimate: $5M additional revenue. Realization: 40% certain = $2M in model. Be conservative. | Synergy timeline: Year 1: 25% realized. Year 2: 60%. Year 3: 90%. Never assume 100% year 1 \u2014 integration takes time. | Integration costs offset synergies: severance, system migration, rebranding. First year may be NET negative even if synergies exist.", "tags": ["financial", "m-a"], "order_index": 2}, {"name": "Goodwill & Intangibles", "definition": "When you acquire a company for more than its net tangible assets, the excess is allocated to identifiable intangibles (customer relationships, technology, brand) and any remainder goes to Goodwill. Goodwill is tested annually for impairment \u2014 a write-down signals a bad deal.", "example": "Acquire for $50M. Tangible net assets: $10M. Identifiable intangibles: customer relationships ($5M), developed technology ($8M), brand ($2M) = $15M. Goodwill = $50M - $10M - $15M = $25M. | Goodwill sits on balance sheet indefinitely unless impaired. An impairment charge (e.g., 'we wrote down $10M in goodwill') signals the deal was overpriced \u2014 stock typically drops. | Intangible amortization: customer relationships amortized over 5-15 years, technology over 3-7 years. This amortization is a non-cash expense that reduces reported earnings but not cash flow.", "tags": ["financial", "m-a"], "order_index": 3}, {"name": "Earnout Modeling", "definition": "Part of the purchase price is paid only if the acquired company hits specific targets post-close. Ties payment to performance, reduces buyer's risk of overpaying, and incentivizes the seller to ensure smooth integration.", "example": "Purchase price: $50M total. $30M cash at close. $20M earnout: $10M if revenue exceeds $15M in Year 1, $10M if revenue exceeds $20M in Year 2. If Year 1 revenue = $12M, earnout = $0. Founders lose $20M. | Earnout disputes: 'Buyer prevented us from hitting targets by changing strategy.' Provision: 'Buyer shall not unreasonably interfere with earnout milestones.' Litigation risk. | Benefit to buyer: only pay for performance that actually materializes. If the acquired company underperforms, you paid less. Premium only paid if the deal was truly worth it.", "tags": ["financial", "m-a"], "order_index": 4}] },
  { id: "ff000001-0000-4000-8000-000000000005", slug: "investor-relations-earnings", title: "Investor Relations & Earnings Communication", description: "Earnings call mastery, guidance philosophy, shareholder communications, activist defense — how CEOs communicate to the capital markets", category: "financial", difficulty: 3, estimated_time_minutes: 30, key_concepts: ["Earnings Call Strategy", "Guidance Philosophy", "Shareholder Letter Writing", "Activist Investor Defense"], use_cases: ["Quarterly earnings", "IPO roadshow", "Activist response", "Crisis communication to investors", "Annual shareholder meeting"], content: "", concepts: [{"name": "Earnings Call Strategy", "definition": "Prepare for the narrative (what story are you telling this quarter?), the data (every metric must reconcile), and the hard questions (identify top 5 brutal questions and script answers). The prepared remarks frame the narrative; the Q&A proves your command.", "example": "Prepared remarks structure: 1) Financial results (revenue, margin, EPS \u2014 state them clearly, including misses) 2) Business highlights (customer wins, product launches \u2014 evidence of momentum) 3) Challenges (what went wrong, WHY, what you're doing) 4) Outlook (guidance if given, strategic priorities). | Hard Q prep: identify the 5 questions you LEAST want to answer. Script the answer. Practice until it sounds unscripted. | Don't over-prepare the easy questions and wing the hard ones. That's exactly backwards.", "tags": ["financial", "investor-relations"], "order_index": 1}, {"name": "Guidance Philosophy", "definition": "Three approaches: 1) Specific guidance (Q1 revenue $50-52M) \u2014 holds you accountable, builds credibility. 2) Ranges only (15-25% growth) \u2014 flexibility. 3) No guidance (Berkshire) \u2014 forces investors to focus on long-term. Choose based on predictability of your business.", "example": "SaaS with 90% recurring revenue: give specific guidance. Predictability is high, investors expect it. | Biotech startup: no guidance. Binary outcomes (FDA approval or not). Guidance is meaningless and creates false precision. | Companies that give guidance and then revise DOWNWARD 3+ times/year lose all credibility. 'Serial guidance revisers' get a credibility discount (lower P/E multiple). | Costco: gives monthly sales updates (transparency) but no formal EPS guidance. Balance transparency with accountability.", "tags": ["financial", "investor-relations"], "order_index": 2}, {"name": "Shareholder Letter Writing", "definition": "The annual shareholder letter is your direct channel to owners. Buffett writes his himself \u2014 it's the most widely read business document in the world. Write honestly about mistakes, explain the business in plain English, and communicate the long-term vision.", "example": "Amazon 1997 letter: 'It's Day 1.' Simple, bold, set the long-term philosophy. Bezos attached this letter to EVERY subsequent annual report for 20+ years. | Buffett's letters: admit mistakes freely ('I was wrong about X'). Explain insurance float in simple terms. Use humor. Result: trust that survives market cycles. | Bad shareholder letter: jargon-filled, corporate-speak, blames 'macroeconomic headwinds' for everything, never admits mistakes. Zero credibility built.", "tags": ["financial", "investor-relations"], "order_index": 3}, {"name": "Activist Investor Defense", "definition": "Activist investors buy 5-15% of your stock and demand changes (spin-off, buyback, board seat, sale). Defense: 1) Know your vulnerabilities (what would an activist attack?) 2) Have a plan before they arrive 3) Engage, don't fight reflexively 4) Win proxy fight if necessary.", "example": "Activist vulnerability scan: low P/E relative to peers? Cash hoard you're not deploying? Conglomerate discount (sum of parts > market cap)? Underperforming divisions dragging down the core? Fix these BEFORE an activist arrives. | When activist arrives: don't ignore them. Meet, listen, find common ground. Sometimes they're right. Procter & Gamble and Nelson Peltz: fought, then settled, then benefited from his input. | Proxy fight defense: you need 50%+1 of shareholder votes. Know your shareholder base. Index funds (Vanguard, BlackRock) may hold 20%+ \u2014 convince them, win the vote.", "tags": ["financial", "investor-relations"], "order_index": 4}] },
  { id: "a1000001-0000-4000-a000-000000000001", slug: "hiring-talent-acquisition", title: "Hiring & Talent Acquisition", description: "Structured hiring that builds elite teams: scorecards, behavioral interviewing, bar raisers, sourcing pipelines, and measuring quality-of-hire", category: "org", difficulty: 2, estimated_time_minutes: 30, key_concepts: ["Structured Interviewing", "Hiring Scorecards", "Bar Raiser Programs", "Onboarding Acceleration"], use_cases: ["Scaling team 10\u2192100", "Executive hiring", "Fixing broken hiring process", "Diversity hiring", "Reducing regrettable attrition"], content: "", concepts: [{"name": "Structured Interviewing", "definition": "Every candidate for a role gets the same questions, evaluated against the same rubric. Behavioral questions ('Tell me about a time when...') are far more predictive than brainteasers or hypotheticals.", "example": "Unstructured: 'So tell me about yourself.' Halo effect: candidate is charismatic, interviewer rates them highly on everything. Predictive validity: near zero. | Structured: 4 interviewers, each assigned 2 competencies. Behavioral: 'Tell me about a time you resolved a conflict between engineering and product.' Score 1-5 against rubric. Candidates rated on evidence, not impression. | Rubric: 1=No evidence, 3=Meets bar (gave an example with specific actions and outcomes), 5=Clearly exceptional (multiple concrete examples showing pattern). Interviewers must cite evidence for their score.", "tags": ["hiring", "process"], "order_index": 1}, {"name": "Hiring Scorecards", "definition": "Before posting a job, define EXACTLY what success looks like: 1) Mission (what will they achieve in 12 months?) 2) Outcomes (3-5 specific deliverables) 3) Competencies (what skills/behaviors predict success?). Interview against this, not the resume.", "example": "VP Sales scorecard: Mission = grow ARR from $10M to $25M in 24 months. Outcomes: 1) Build 15-person enterprise sales team by Q2 2) Close 10 enterprise logos (>$100k ACV) in Year 1 3) Reduce sales cycle from 90 to 60 days. Competencies: enterprise sales leadership (must have closed $1M+ deals personally), team building (must have grown a team from 3 to 15+), culture fit (must have worked in high-autonomy environments). | Interviewers assign to competencies: VP interviews on leadership, peer on culture fit, direct report on management style.", "tags": ["hiring", "process"], "order_index": 2}, {"name": "Bar Raiser Programs", "definition": "Bar Raisers are specially trained interviewers who are NOT on the hiring team. Their sole objective: ensure every hire raises the average. They have veto power \u2014 even if the hiring manager wants to hire, the Bar Raiser can say no.", "example": "Amazon practice: Bar Raisers are senior employees from different departments who have conducted 100+ interviews and been trained in behavioral assessment. They participate in every interview loop. | Bar Raiser asks: 'Would I admire this person?' 'Will this person raise the average?' 'Could this person teach me something?' | Impact: prevents 'hire fast, regret slow' cycles. Hiring manager is desperate to fill the seat. Bar Raiser has no such pressure. Independent quality gate. | Training: Bar Raisers must demonstrate ability to write evidence-based feedback. 'She is smart' is rejected. 'She redesigned the database schema, reducing query time 80%, with concrete example' is accepted.", "tags": ["hiring", "process"], "order_index": 3}, {"name": "Onboarding Acceleration", "definition": "First 90 days determine a hire's long-term success. Structured onboarding: pre-start prep, first-week setup, 30/60/90-day milestones with clear deliverables, assigned buddy, and executive check-ins at 14, 30, and 90 days.", "example": "Day 1: laptop working, accounts provisioned, documentation access. 'We prepared for your arrival.' | Week 1: meet 15 key people (30-min one-on-ones), understand team org chart, ship a small change to production. Momentum matters. | 30 days: present findings and recommendations to team. 'I've observed. Here's what I think.' | 60 days: lead a significant project or process change. Ownership established. | 90 days: formal review against scorecard. 'Are they on track to achieve their mission?' Corrective feedback or celebrate success.", "tags": ["hiring", "onboarding"], "order_index": 4}] },
  { id: "a1000001-0000-4000-a000-000000000002", slug: "performance-management", title: "Performance Management Systems", description: "Design review processes that actually improve performance: OKR-linked reviews, 360 feedback, calibration, PIPs, and separating performance from potential", category: "org", difficulty: 2, estimated_time_minutes: 30, key_concepts: ["OKR-Linked Performance Reviews", "360-Degree Feedback", "Calibration Sessions", "Performance Improvement Plans (PIPs)"], use_cases: ["Review cycle design", "Promotion decisions", "Underperformance management", "Compensation decisions", "Culture of feedback"], content: "", concepts: [{"name": "OKR-Linked Performance Reviews", "definition": "Performance = outcomes achieved, not hours worked. Link review ratings to OKR completion: 70-80% OKR completion = meets expectations. 90%+ = exceeds. <50% = needs improvement. Eliminates subjectivity.", "example": "Engineer: Q1 OKR \u2014 'Reduce p99 API latency from 800ms to 400ms.' Result: achieved 320ms. Exceeds expectations. | Product Manager: Q1 OKR \u2014 'Launch new onboarding flow, achieve 40% activation rate.' Result: launched, 35% activation. Meets expectations (close to target, learnings documented). | Bad performance review: 'Demonstrates leadership and initiative.' Good: 'Led cross-team project that reduced churn 2% ($200k ARR impact).' Specific, measurable, attributable.", "tags": ["performance", "okr"], "order_index": 1}, {"name": "360-Degree Feedback", "definition": "Collect structured feedback from 5-8 people: manager, 3-4 peers, 2-3 direct reports, 1-2 cross-functional stakeholders. Triangulate patterns. If 6 out of 8 people say you're a poor listener \u2014 you're a poor listener.", "example": "360 process: reviewee selects 6-8 reviewers, manager approves (ensures diversity). Questions: 'What should this person START doing? STOP doing? CONTINUE doing?' | Pattern recognition: 6 reviewers mention 'interrupts in meetings' \u2192 strong signal. 1 reviewer mentions 'was late to a meeting' \u2192 weak signal, probably situational. | CEO receives 360 too. If your direct reports anonymously say you don't listen to dissenting views, that's the most important feedback you'll get all year. Take it seriously.", "tags": ["performance", "feedback"], "order_index": 2}, {"name": "Calibration Sessions", "definition": "Managers meet to calibrate ratings across teams: 'Sarah got Exceeds from me. Here's the evidence.' Other managers challenge: 'That evidence looks like Meets compared to what Maria achieved.' Prevents rating inflation and ensures standards are consistent.", "example": "Without calibration: Manager A rates everyone 'Exceeds' (avoiding hard conversations). Manager B rates honestly. Manager A's team gets bigger bonuses \u2014 unfair. With calibration: ratings are normalized. | Calibration outputs: a 9-box grid of every employee (performance \u00d7 potential). Used for: promotion decisions, succession planning, PIP identification. | CEO red flag: calibration sessions where no one's rating is challenged. That's a rubber stamp, not calibration. The room should have tension.", "tags": ["performance", "calibration"], "order_index": 3}, {"name": "Performance Improvement Plans (PIPs)", "definition": "A written plan for an underperforming employee: specific, measurable goals with a 30-90 day timeline. Weekly check-ins. At the end: meets goals (exits PIP successfully) or doesn't (termination). NOT a 'pre-firing checklist' \u2014 a genuine attempt to improve.", "example": "PIP structure: 1) What's not working (specific examples, dates) 2) What success looks like (measurable goals) 3) Support/resources provided 4) Check-in cadence (weekly) 5) Timeline (60 days) 6) Consequences if goals not met (termination). | Successful PIP: employee meets all goals, exits PIP, thrives. Should be the goal 30-50% of the time. If your PIP success rate is 0%, your PIPs are firing checklists, not improvement tools. | Best practice: the PIP should NOT be a surprise. If the employee is surprised, their manager failed at giving real-time feedback for months.", "tags": ["performance", "management"], "order_index": 4}] },
  { id: "a1000001-0000-4000-a000-000000000003", slug: "compensation-incentive-design", title: "Compensation & Incentive Design", description: "Design comp plans that attract, retain, and motivate: base/bonus/equity mix, sales comp, performance multipliers, and retention incentives", category: "org", difficulty: 3, estimated_time_minutes: 35, key_concepts: ["Total Rewards Philosophy", "Equity Grant Design", "Sales Compensation Models", "Performance-Based Bonus Structures"], use_cases: ["Comp philosophy design", "Annual compensation review", "Sales team restructuring", "Pre-IPO equity planning", "Executive compensation"], content: "", concepts: [{"name": "Total Rewards Philosophy", "definition": "A written document stating: 1) What percentile of the market do we target? 2) What's our mix of base/bonus/equity by level? 3) How often do we refresh equity? 4) What's our philosophy on internal equity vs external market?", "example": "Tech startup: 75th percentile cash + 90th percentile equity (cash poor, equity rich). 'We may not pay the highest salary, but our equity can be life-changing.' | Public tech company: 65th percentile total comp. 60% base, 20% bonus, 20% equity (annual RSU refreshes). | Philosophy guides every offer. Without it: 'What should we pay the new VP Marketing?' becomes a random negotiation based on their previous salary, not your philosophy. | Anti-pattern: paying new hires more than existing employees for the same role. Internal inequity destroys morale. Fix: adjust existing team when market data shifts.", "tags": ["compensation", "strategy"], "order_index": 1}, {"name": "Equity Grant Design", "definition": "Standard terms: 4-year vesting, 1-year cliff (no equity until 12 months). Post-termination exercise window: 90 days (standard, forces exercise or forfeiture) vs 10 years (emerging best practice, kinder to employees). Refresh grants at promotion and periodically.", "example": "New hire grant: 40,000 options over 4 years (1-year cliff). Year 1: 0 shares vest until month 12. Then 10,000 shares vest, 2,083/month thereafter. | 90-day exercise window: employee leaves, has 90 days to exercise vested options. If not exercised, forfeited. Problem: buyer needs cash (strike price + taxes). At a unicorn, could be $500k+. Employee can't afford it, forfeits years of equity. | Extended window (10 years): gives employees time to exercise when the company is liquid. Becoming standard at progressive companies. Costs the company zero, retains employee goodwill.", "tags": ["compensation", "equity"], "order_index": 2}, {"name": "Sales Compensation Models", "definition": "The formula that drives your entire revenue engine. Typical SaaS AE: 50/50 base/variable split. OTE (on-target earnings) = base + commission at 100% quota. Accelerators: earn FASTER above 100% (1.5x-3x multiplier). Clawbacks: if customer churns within 6 months, commission is clawed back.", "example": "AE comp: $100k base + $100k variable = $200k OTE at 100% of $1M quota. Commission rate = 10% of ACV. 0-100% quota: 10% \u00d7 ACV. 100-150%: 15% \u00d7 ACV (accelerator). Above 150%: 20% (double accelerator). | Clawback: 'If customer cancels within 6 months, commission charged back against future commissions.' Aligns AE with customer success, not just closing. | Team vs individual: team quota for collaborative selling (enterprise). Individual quota for transactional (SMB, velocity sales). Wrong incentive model = wrong behavior.", "tags": ["compensation", "sales"], "order_index": 3}, {"name": "Performance-Based Bonus Structures", "definition": "Bonus = target \u00d7 company performance multiplier \u00d7 individual performance multiplier. Company hits 90% of targets \u2192 0.8x multiplier. Individual gets 'exceeds' rating \u2192 1.5x. Bonus = target \u00d7 0.8 \u00d7 1.5 = 1.2x target.", "example": "Target bonus: 15% of base salary ($150k base = $22,500 target). | Company performance: revenue at 105% of plan, EBITDA at 95%. Weighted score: 0.6\u00d71.05 + 0.4\u00d70.95 = 1.01x. | Individual performance: exceeds expectations = 1.3x. | Bonus = $22,500 \u00d7 1.01 \u00d7 1.3 = $29,542.50. | Higher than target (great personal performance made up for slight EBITDA miss). Transparent, formulaic, fair. | Caps: bonus capped at 200% of target. Prevents windfalls from one extraordinary quarter driving outsized bonuses.", "tags": ["compensation", "performance"], "order_index": 4}] },
  { id: "b1000001-0000-4000-b000-000000000001", slug: "business-continuity-planning", title: "Business Continuity & Disaster Recovery", description: "BCP/DR planning: RTO, RPO, failover testing, supplier resilience, pandemic planning — ensure your business survives the unthinkable", category: "risk", difficulty: 3, estimated_time_minutes: 30, key_concepts: ["RTO & RPO (Recovery Objectives)", "Business Impact Analysis (BIA)", "Failover Testing"], use_cases: ["Disaster preparedness", "Regulatory compliance", "Board assurance", "Supply chain risk", "Cyber incident recovery"], content: "", concepts: [{"name": "RTO & RPO (Recovery Objectives)", "definition": "RTO = maximum acceptable downtime before business-threatening damage. RPO = maximum acceptable data loss measured in time. Critical systems: RTO <4 hours, RPO <15 min. Non-critical: RTO <24 hours, RPO <24 hours.", "example": "E-commerce payment system: RTO = 1 hour (every hour down costs $500k in lost revenue). RPO = 0 (zero data loss \u2014 every transaction must be preserved). | Internal wiki: RTO = 24 hours (annoying but not business-threatening). RPO = 24 hours (losing a day of wiki edits is acceptable). | DR cost scales with RTO/RPO stringency. Achieving RTO=1 hour, RPO=0 costs 3-5x more than RTO=24 hours, RPO=24 hours. Align RTO/RPO with business impact, not perfectionism.", "tags": ["risk", "continuity"], "order_index": 1}, {"name": "Business Impact Analysis (BIA)", "definition": "For each business process: 'If this stops working, what's the financial impact after 1 hour, 4 hours, 24 hours, 1 week?' Rank processes by impact. The top-ranked processes get the fastest RTO/RPO.", "example": "BIA matrix: Payment processing: 1 hour = $500k loss, 4 hours = $2M, 24 hours = $12M (max priority). Employee email: 1 hour = minimal, 24 hours = moderate inconvenience (low priority). | BIA determines where to invest DR budget. Don't spend $1M protecting a system whose 24-hour downtime costs $50k. | BIA should include REPUTATIONAL impact, not just financial. 'Customer data is unavailable for 4 hours' costs $0 in direct revenue but millions in trust.", "tags": ["risk", "continuity"], "order_index": 2}, {"name": "Failover Testing", "definition": "Test your disaster recovery quarterly. Tabletop exercise (walk through the runbook): 'The primary data center just burned down. What do you do first?' Technical test: actually switch traffic to DR site and verify everything works.", "example": "Tabletop: CEO walks team through scenario. 'It's 2am. The primary DC is offline. Who gets called? In what order? Who has the decision authority to declare a disaster and initiate failover?' | Technical failover: run this in production quarterly. Switch traffic to DR, verify payments still work, switch back. If you haven't tested failover in 6 months, your DR plan is a fiction. | Netflix does this continuously: Chaos Engineering (randomly kills production instances) ensures DR works. The best DR test is making failure routine.", "tags": ["risk", "continuity"], "order_index": 3}] },
  { id: "b1000001-0000-4000-b000-000000000002", slug: "regulatory-risk-compliance", title: "Regulatory Risk & Compliance", description: "Navigate GDPR, CCPA, EU AI Act, SEC, SOX, and industry regulations — build compliance programs that protect without paralyzing the business", category: "risk", difficulty: 3, estimated_time_minutes: 30, key_concepts: ["Regulatory Landscape Mapping", "Compliance Program Design", "Audit Readiness"], use_cases: ["Pre-IPO compliance", "New market entry", "Regulatory investigation", "AI regulation preparation", "Board compliance oversight"], content: "", concepts: [{"name": "Regulatory Landscape Mapping", "definition": "Create a matrix: rows = regulations (GDPR, CCPA, SOC2, SOX, HIPAA, EU AI Act), columns = applicability (yes/no), risk level (high/med/low), compliance status (compliant/gap/unknown), and remediation cost. Prioritize by risk level.", "example": "SaaS company with EU customers and AI features: GDPR applies (high risk, fine up to 4% global revenue), SOC2 applies (medium risk, customer requirement), EU AI Act applies (medium risk, emerging), SOX applies post-IPO (low risk now, high risk later). | Plan: Q1: close GDPR gaps (data inventory, DSAR process). Q2: SOC2 Type I. Q3: EU AI Act readiness assessment. H2: SOX prep. | Every regulation has a 'trigger event.' GDPR triggers when you have ANY EU customer. SOX triggers at IPO. Don't build compliance for regulations that don't apply yet (waste) \u2014 but know when they WILL apply.", "tags": ["risk", "compliance"], "order_index": 1}, {"name": "Compliance Program Design", "definition": "A compliance program has 6 elements: 1) Written policies 2) Training 3) Monitoring 4) Reporting mechanism 5) Investigation process 6) Enforcement/discipline. DOJ/SEC evaluate these when assessing corporate wrongdoing penalties.", "example": "Anti-bribery policy: written, trained to all employees annually, monitored through expense report audits, reported via anonymous hotline, investigated by legal, enforced with termination for violations. | Without monitoring: policies are aspirational. 'We have a policy against bribery' \u2192 employee bribes anyway \u2192 DOJ finds out \u2192 penalty is higher because you had no monitoring (you should have caught this). | With monitoring + documented investigation: same scenario \u2192 DOJ sees you caught it, investigated, remediated \u2192 penalty reduced significantly (cooperation credit).", "tags": ["risk", "compliance"], "order_index": 2}, {"name": "Audit Readiness", "definition": "Can you produce evidence that your controls exist and work within 48 hours of an auditor's request? Evidence = logs, screenshots, documented approvals, test results, meeting minutes. Build evidence generation INTO your processes, not after the fact.", "example": "Auditor asks: 'Show me that only authorized personnel can deploy to production.' Evidence: access control list showing 8 engineers with deploy permissions, 2-factor auth requirement log, quarterly access review with documented changes. | Bad answer: 'We have a process... let me find the docs... give us a week.' That's not audit-ready. | Best practice: 'compliance as code.' Infrastructure-as-code with audit logs. 'Every deployment was authorized by a PR merge, with reviewer approval, automatically logged to immutable storage.' Evidence is generated automatically.", "tags": ["risk", "compliance"], "order_index": 3}] },
  { id: "c1000001-0000-4000-c000-000000000001", slug: "cross-cultural-negotiation", title: "Cross-Cultural Negotiation & Global Deals", description: "Navigate negotiation styles across cultures: high-context vs low-context, relationship-first vs deal-first, hierarchy vs egalitarian approaches", category: "negotiation", difficulty: 2, estimated_time_minutes: 25, key_concepts: ["High-Context vs Low-Context Communication", "Relationship-First vs Deal-First", "Face-Saving Dynamics"], use_cases: ["International M&A", "Global partnerships", "Cross-border sales", "Multinational team management", "Joint ventures"], content: "", concepts: [{"name": "High-Context vs Low-Context Communication", "definition": "High-context: meaning is embedded in the context \u2014 who is speaking, their relationship to you, what is NOT said. 'We will consider it' often means NO. Low-context: meaning is in the explicit words. 'No' means no. Mismatched styles cause disastrous misunderstandings.", "example": "Japanese counterpart says 'That will be difficult.' Low-context American hears: 'We'll work on it.' High-context reality: 'Absolutely not, but I can't say that directly because it would damage the relationship.' | German counterpart says 'That's unacceptable.' Low-context German means exactly that. High-context listener from another culture hears aggression. Neither is wrong \u2014 different communication norms. | CEO strategy: research the cultural norms of your counterpart BEFORE negotiating. Deploy a cultural bridge (someone with experience in both cultures) on your team.", "tags": ["negotiation", "culture"], "order_index": 1}, {"name": "Relationship-First vs Deal-First", "definition": "Relationship-first cultures (most of Asia, Latin America, Middle East, Africa): you build trust over meals, meetings, and months BEFORE discussing terms. Deal-first (US, Northern Europe): you discuss terms immediately and let trust build through the process.", "example": "China business trip: 3 days of dinners, factory tours, karaoke before any mention of the contract. This IS the negotiation \u2014 you're being evaluated as a partner. Skip the dinners, lose the deal. | US counterpart visiting China: arrives with term sheet, wants to 'get down to business' on day 1. Perceived as rude and transactional. Relationship never forms. Deal dies. | Hybrid approach: respect the relationship-building phase without being inauthentic. Genuine curiosity about their business, their people, their history. The relationship time is NOT wasted \u2014 it's the foundation of a multi-year partnership.", "tags": ["negotiation", "culture"], "order_index": 2}, {"name": "Face-Saving Dynamics", "definition": "In many cultures, 'face' (dignity, respect, social standing) is more important than financial terms. Never publicly contradict a senior counterpart, never force someone to admit they were wrong, and frame concessions as mutual discovery, not capitulation.", "example": "Your proposal is 30% above market. Don't say: 'That's way too high.' Do say: 'We've been researching market rates, and our analysis shows a different range. Could you help us understand your methodology?' They can adjust without 'losing.' | Public negotiation with Chinese government: never criticize their previous policy. Frame your proposal as 'building on the excellent foundation you've established.' | Face-saving language: 'I may have misunderstood' (not 'you didn't explain clearly'). 'Let's explore alternatives' (not 'your proposal is unacceptable'). Small words, massive difference.", "tags": ["negotiation", "culture"], "order_index": 3}] },
  { id: "d1000001-0000-4000-d000-000000000001", slug: "supply-chain-management", title: "Supply Chain Management for CEOs", description: "From supplier diversification to resilience: just-in-time vs just-in-case, make vs buy, supply chain risk assessment, and logistics optimization", category: "operations", difficulty: 3, estimated_time_minutes: 35, key_concepts: ["Supplier Diversification Strategy", "Just-in-Time vs Just-in-Case", "Supply Chain Risk Mapping"], use_cases: ["Supply chain risk mitigation", "Sourcing strategy", "Cost reduction", "Manufacturing footprint decisions", "Post-COVID resilience planning"], content: "", concepts: [{"name": "Supplier Diversification Strategy", "definition": "Never single-source critical components. Minimum: dual-source (primary supplier at 70% volume, secondary at 30%). Better: multi-source across geographies (Taiwan + Vietnam + Mexico). Diversity = resilience.", "example": "Single source risk: Apple relies on TSMC for advanced chips. TSMC is in Taiwan. Geopolitical risk: if China blockades Taiwan, Apple loses its most critical supplier. Apple is actively funding TSMC's Arizona fab. | Dual source: Toyota learned from the 2011 tsunami. Now maintains at least 2 suppliers for every critical part, often in different regions. | Implementation: for each critical component, ask 'Who else could make this within 6 months?' If the answer is 'nobody,' invest in qualifying an alternative supplier now.", "tags": ["operations", "supply-chain"], "order_index": 1}, {"name": "Just-in-Time vs Just-in-Case", "definition": "JIT: inventory arrives exactly when needed (lower cost, fragile). JIC: hold 2-8 weeks of buffer inventory (higher cost, resilient). Post-COVID consensus: JIT for predictable, multi-sourced components. JIC for single-sourced, long-lead-time, or critical components.", "example": "JIT: Toyota in 1990s. Suppliers deliver parts 4 hours before assembly. $0 in inventory carrying cost. But 2011 tsunami disrupted suppliers, production stopped for weeks. | JIC: Apple holds 2-4 weeks of iPhone components. Cost: billions in inventory. Benefit: can survive most supply disruptions without production stoppage. | Hybrid: JIT for commoditized parts from multiple suppliers. JIC for proprietary chips from single supplier. The cost of JIC on 5% of components can eliminate 95% of supply chain risk.", "tags": ["operations", "supply-chain"], "order_index": 2}, {"name": "Supply Chain Risk Mapping", "definition": "Map every supplier (Tier 1), their suppliers (Tier 2), and geographic concentrations. Identify single points of failure: 'Our 3 suppliers of component X all source from the same Tier 2 factory in Thailand.' Diversification is an illusion if Tier 2 is concentrated.", "example": "Tier 1 mapping: you buy from 3 different suppliers. Looks diversified. | Tier 2 mapping: all 3 buy the same raw material from the same mine in Congo. One mine closure \u2192 all 3 suppliers fail simultaneously. Diversification was an illusion. | Geographic concentration: all suppliers are within 50 miles of the same fault line. Earthquake = all three offline. | Mitigation: map to Tier 2-3 for critical components. Diversify by GEOGRAPHY, not just by supplier name. A supplier in Taiwan and a supplier in Korea are diversified. Two suppliers both in Taiwan are not.", "tags": ["operations", "supply-chain"], "order_index": 3}] },
  { id: "e1000001-0000-4000-e000-000000000001", slug: "product-market-fit", title: "Product-Market Fit & Growth Engines", description: "Measure, achieve, and sustain product-market fit: PMF survey, retention benchmarks, growth loops, flywheel design, and cohort-based growth diagnostics", category: "innovation", difficulty: 3, estimated_time_minutes: 30, key_concepts: ["PMF Survey (Sean Ellis Test)", "Growth Loops vs Funnels", "Flywheel Design", "Expansion Revenue Mechanics"], use_cases: ["PMF assessment", "Growth strategy", "Product roadmap", "Investor pitches", "Pivot decisions"], content: "", concepts: [{"name": "PMF Survey (Sean Ellis Test)", "definition": "Survey active users: 'How would you feel if [product] no longer existed?' Options: Very disappointed, Somewhat disappointed, Not disappointed. PMF threshold: >=40% 'very disappointed.' If >=40%, you have PMF. If 25-40%, you're close. If <25%, you don't have PMF.", "example": "Run the survey: email your most active users (used product 3+ times in last 2 weeks). 'We're trying to understand the value of our product. How would you feel if you could no longer use [product]?' | Results: 42% very disappointed = PMF achieved. Now: interview the 'very disappointed' users. 'WHY would you miss it? What job does it do for you?' Their answers are your positioning and messaging. | 18% very disappointed = no PMF. Don't scale growth \u2014 fix the product. Interview the 'somewhat disappointed' \u2014 'what's missing that would make it indispensable?'", "tags": ["innovation", "product"], "order_index": 1}, {"name": "Growth Loops vs Funnels", "definition": "Funnel: acquisition \u2192 activation \u2192 retention \u2192 revenue \u2192 referral (linear, leaks at each stage). Growth Loop: product generates its own growth. Each user who joins creates value that brings more users. Loops compound; funnels decay.", "example": "Pinterest loop: user saves pins \u2192 content indexed by Google \u2192 new user discovers via search \u2192 signs up \u2192 saves pins. The loop is: SAVE \u2192 DISCOVER \u2192 JOIN \u2192 SAVE. Each action fuels the next. | Uber loop: rider requests ride \u2192 driver picks up \u2192 more drivers available \u2192 shorter wait times \u2192 more riders \u2192 more drivers. Two-sided marketplace loop. | Facebook in 2008: user joins \u2192 invites friends \u2192 friends join \u2192 creates content \u2192 user returns. Engagement loop, not a funnel. | CEO question: 'What's our growth loop?' If you can't articulate a loop, you're running a paid acquisition funnel that stops when funding stops.", "tags": ["innovation", "growth"], "order_index": 2}, {"name": "Flywheel Design", "definition": "A self-reinforcing cycle where each step powers the next. Unlike a funnel (where energy leaks at each step), a flywheel accumulates momentum. The CEO's job is to identify and remove friction from the flywheel.", "example": "Amazon flywheel: Lower prices \u2192 More customer visits \u2192 More 3rd-party sellers \u2192 Better selection \u2192 Better customer experience \u2192 More traffic \u2192 Lower cost structure \u2192 Lower prices. | Every action Amazon takes maps to a point on the flywheel. AWS? Reduces cost structure. Prime? Improves customer experience. FBA? Attracts more sellers. | How to find your flywheel: 1) What's the core value you provide? 2) What makes that value increase? 3) What makes customers come back? 4) What makes the business more efficient at scale? Connect these into a causal loop. Every flywheel has friction points \u2014 identify and lubricate them.", "tags": ["innovation", "growth"], "order_index": 3}, {"name": "Expansion Revenue Mechanics", "definition": "NRR > 100% means your existing customer base grows even if you add zero new customers. Expansion revenue comes from: seat expansion (more users), usage expansion (higher tiers), product adoption (additional modules), price increases.", "example": "Year 0: 100 customers, $1M ARR. Year 1: 10 churn (lose $100k), but remaining 90 expand $250k (seat expansion + upgrades). NRR = ($1M - $100k + $250k) / $1M = 115%. | Great NRR: 120%+ (Snowflake, Datadog). Good: 110-120%. Concerning: <100% (you're shrinking even before new customers). | Expansion drivers: add seats, upgrade tiers, cross-sell modules, usage-based pricing (customers naturally expand as they grow). | CEO's expansion strategy: 'How do we make our product MORE valuable to customers over time so they naturally spend MORE?' That's the opposite of churn reduction (defensive). It's growth (offensive).", "tags": ["innovation", "growth"], "order_index": 4}] },
  { id: "a2000001-0000-4000-b000-000000000001", slug: "platform-business-models", title: "Platform Business Models & Network Effects", description: "Build and scale platform businesses: marketplace dynamics, network effects, chicken-and-egg problems, pricing sides, and platform governance", category: "strategy", difficulty: 3, estimated_time_minutes: 35, key_concepts: ["Network Effect Types", "Chicken-and-Egg Problem", "Platform Pricing (Which Side to Charge)"], use_cases: ["Platform launch", "Marketplace design", "Pricing strategy for platforms", "Competitive defense against platforms", "Network effect measurement"], content: "", concepts: [{"name": "Network Effect Types", "definition": "Direct: each new user directly increases value for ALL users (WhatsApp, WeChat). Indirect/Two-Sided: more of Type A attracts more of Type B, and vice versa (Uber, Airbnb). Data: more usage generates more data, which improves the product (Google Search, Netflix recommendations).", "example": "WhatsApp direct: 2B users, each new user makes it MORE useful for existing users (more people to message). | Uber indirect: more riders attract more drivers, more drivers reduce wait times attracting more riders. Self-reinforcing loop. | Google data: every search generates click data \u2192 improves ranking algorithm \u2192 better results \u2192 more users \u2192 more data. 20+ year data moat. | Identify your effect type(s). If you have none, you're not a platform \u2014 you're a pipeline.", "tags": ["strategy", "platform"], "order_index": 1}, {"name": "Chicken-and-Egg Problem", "definition": "Two-sided platforms need BOTH sides to participate, but neither will join without the other. Solutions: 1) Subsidize one side (pay them) 2) Build single-player utility first 3) Use marquee users as anchor tenants 4) Fake it till you make it (seed supply/demand artificially).", "example": "Uber: subsidized riders (cheap rides) with VC money, paid drivers above market rates. Once network reached critical mass (liquidity), reduced subsidies. | Tinder: built single-player utility first (swipe through profiles \u2014 fun even alone). Users stayed and swiped even without matches. Then added matching. | OpenTable: signed marquee restaurants first (anchor tenants). 'We already have French Laundry on the platform' attracted other restaurants and diners. | Airbnb: founders went door-to-door photographing apartments, created fake 'demand' until real demand emerged.", "tags": ["strategy", "platform"], "order_index": 2}, {"name": "Platform Pricing (Which Side to Charge)", "definition": "Two-sided platforms must decide: which side pays, which side gets subsidized? Framework: charge the side that needs the other side more, or the side with lower price sensitivity, or the side with fewer alternatives.", "example": "Credit cards: charge merchants (they need to accept cards to make sales), subsidize cardholders (points, cashback, no annual fee). | LinkedIn: charge recruiters (they need access to candidates), free for job seekers (they need job opportunities \u2014 but recruiters need them more). | Uber: charge riders (they need the ride), pay drivers (they supply the ride). But in new cities, subsidize riders to attract drivers, then flip when network is established. | Rule: the attention side is subsidized; the money side is charged. Attention = users/consumers. Money = advertisers/merchants/recruiters.", "tags": ["strategy", "platform"], "order_index": 3}] },
  { id: "a2000001-0000-4000-b000-000000000002", slug: "disruption-defense", title: "Disruption Response Playbook", description: "When a startup threatens your core business: acquisition vs ignore vs compete vs self-disrupt. Battle-tested playbook from Christensen, Grove, and modern tech strategy", category: "strategy", difficulty: 3, estimated_time_minutes: 30, key_concepts: ["Disruption Detection", "Ignore vs Acquire vs Compete Framework", "Self-Disruption (Separate Unit)"], use_cases: ["Competitive threat response", "Innovation strategy", "Resource allocation", "M&A targeting", "Board strategy discussions"], content: "", concepts: [{"name": "Disruption Detection", "definition": "Early signals you're being disrupted: 1) Startup targeting your LOWEST-MARGIN customers 2) Startup selling to NON-CONSUMERS (people you never served) 3) Your sales team says 'they're not a threat' (they never see it coming) 4) Their product is simpler/cheaper but 'worse' by your metrics.", "example": "Toyota in 1970s: GM sales team said 'those tin cans aren't real cars.' They were selling to non-consumers (people who couldn't afford a Cadillac). 20 years later: Toyota dominates the US market. | Netflix vs Blockbuster: Netflix mailing DVDs was 'worse' than same-day rental at Blockbuster. But it served the 'don't want to leave my house' segment. By the time Blockbuster responded, it was too late. | Detection checklist for board: quarterly review \u2014 'What startups are selling to customers we ignore?'", "tags": ["strategy", "disruption"], "order_index": 1}, {"name": "Ignore vs Acquire vs Compete Framework", "definition": "Ignore: if the disruptor's business model can't scale unit economics beyond the niche. Acquire: if their technology complements yours and cultural integration is possible. Compete: launch your own answer, but ONLY in a separate business unit with different metrics and culture.", "example": "Ignore: Apple ignored cheap Android phones. Why? They sell to different segments (premium vs commodity). Disruption theory says Apple should be dead by now \u2014 but they're not, because the premium segment is durable. | Acquire: Facebook acquired Instagram ($1B) and WhatsApp ($19B). Both were potential disruptors. Both are now core to Meta. | Compete (separately): GM launched Saturn as a separate company to compete with Japanese imports. Different union contract, different factory, different culture. It worked \u2014 until GM integrated Saturn back into the mothership and killed what made it different.", "tags": ["strategy", "disruption"], "order_index": 2}, {"name": "Self-Disruption (Separate Unit)", "definition": "The only proven defense against disruption: launch your own disruptive product in a SEPARATE organization. Different location, different metrics, different compensation, different leadership. Shield it from the core business's margin expectations.", "example": "If you're a premium SaaS company and a free-tier competitor emerges, launch your own free tier \u2014 but as a separate BU with its own P&L, own team, own office. Otherwise, your core business team will sabotage it (cannibalization fear). | Intel's Celeron: launched a cheaper processor to fight AMD. But it was so crippled (intentionally) that it was barely competitive. Self-disruption must be GENUINE, not a crippled version. | Gigafund's thesis: 'If you're Amazon and you see AWS as a side project within the retail P&L, it dies. You must create a COMPLETELY separate entity.'", "tags": ["strategy", "disruption"], "order_index": 3}] },
  { id: "a2000001-0000-4000-b000-000000000003", slug: "blue-ocean-strategy", title: "Blue Ocean Strategy (ERRC Grid)", description: "Create uncontested market space: Eliminate, Reduce, Raise, Create — a systematic framework for making competition irrelevant", category: "strategy", difficulty: 2, estimated_time_minutes: 25, key_concepts: ["ERRC Grid", "Strategy Canvas", "Three Tiers of Non-Customers"], use_cases: ["Product redesign", "New market creation", "Competitive repositioning", "Business model innovation", "Startup strategy"], content: "", concepts: [{"name": "ERRC Grid", "definition": "Eliminate (remove features/costs the industry takes for granted), Reduce (cut well below industry standard on factors customers don't value that much), Raise (dramatically improve what customers do value), Create (offer things the industry never has). Together, these four moves create a new value curve.", "example": "Cirque du Soleil: Eliminated animal acts and star performers (huge cost). Reduced the 'thrill and danger' factor (traditional circus). Raised artistic quality, unique venue, theatrical storyline. Created an entirely new category between circus and theater. Result: premium pricing, massive margins. | Yellow Tail wine: Eliminated wine jargon, aging talk, complexity. Reduced wine variety (2 reds, 2 whites). Raised fun, approachable branding. Created a new market: beer drinkers switching to wine. | Nintendo Wii: Eliminated cutting-edge graphics. Reduced game complexity. Raised movement-based fun. Created casual gaming market (grandparents, kids). Beat Sony and Microsoft without competing on their terms.", "tags": ["strategy", "blue-ocean"], "order_index": 1}, {"name": "Strategy Canvas", "definition": "Plot your offering and your competitors on the SAME set of competitive factors. A Blue Ocean shift happens when your curve is fundamentally DIFFERENT \u2014 not just higher on all factors (which is expensive), but higher on some and lower on others.", "example": "Southwest Airlines canvas vs United: Factors: price, meals, lounges, seat choice, hub connectivity, friendly service, speed, frequent departures. Southwest: raised price (lower price = better), raised friendly service, raised speed, raised frequency. Reduced meals (none), reduced lounges (none), reduced seat choice (open seating), reduced hub connectivity (point-to-point). The curve is DIFFERENT, not just better. | Key insight: you don't have to beat competitors on every factor. You need to beat them on the ones YOUR chosen customers care about. The rest you can eliminate or reduce, saving costs.", "tags": ["strategy", "blue-ocean"], "order_index": 2}, {"name": "Three Tiers of Non-Customers", "definition": "Don't just fight for existing customers. Blue Ocean targets non-customers: Tier 1 (soon-to-be non-customers \u2014 ready to leave), Tier 2 (refusing non-customers \u2014 consciously chose against your industry), Tier 3 (unexplored non-customers \u2014 never considered your industry).", "example": "Tier 1: gym members who are about to cancel. What would make them stay? Peloton targeted them with at-home, on-demand fitness. | Tier 2: people who REFUSE to go to gyms (intimidated, no time, hate the culture). Peloton reached them \u2014 'work out at home, no judgment.' | Tier 3: people who never considered structured fitness at all. Peloton didn't reach them (that needs a different approach). | CEO exercise: map your three tiers of non-customers. What do they have in common that your industry is failing to provide?", "tags": ["strategy", "growth"], "order_index": 3}] },
  { id: "a3000001-0000-4000-b000-000000000001", slug: "capacity-planning-forecasting", title: "Capacity Planning & Forecasting", description: "Match supply to demand: demand forecasting, capacity management, queuing theory, Little\'s Law, and the bullwhip effect — the operations backbone", category: "operations", difficulty: 3, estimated_time_minutes: 30, key_concepts: ["Demand Forecasting Methods", "Little's Law", "The Bullwhip Effect"], use_cases: ["Production planning", "Service operations", "Cloud infrastructure scaling", "Workforce planning", "Supply chain coordination"], content: "", concepts: [{"name": "Little's Law", "definition": "L = \u03bb \u00d7 W. Work-in-Progress (L) = Arrival Rate (\u03bb) \u00d7 Cycle Time (W). To reduce cycle time, you must either reduce WIP or increase throughput. You CAN'T reduce all three simultaneously.", "example": "Call center: 100 calls arrive/hour (\u03bb), average handle time 12 minutes (W = 0.2 hours). Staff needed = \u03bb \u00d7 W = 20 agents online at any time. | Sprint backlog: team has 12 stories in progress (L), average throughput 4 stories/week (\u03bb). Average cycle time = 12/4 = 3 weeks. To reduce to 2 weeks, cut WIP to 8. | CEO takeaway: if you want things to move faster, reduce WIP (fewer projects in flight). Adding more people to the same number of projects INCREASES cycle time (coordination overhead).", "tags": ["operations", "capacity"], "order_index": 1}, {"name": "The Bullwhip Effect", "definition": "Small demand fluctuations at customer level amplify at each upstream stage. Retailer orders 5% more \u2192 wholesaler sees 10% spike \u2192 manufacturer ramps production 20% \u2192 raw material suppliers panic and produce 40% more. Result: massive overproduction, inventory waste, and write-offs.", "example": "P&G discovered the bullwhip effect in Pampers diapers: consumer demand is stable (babies use diapers at a constant rate). But retailer orders fluctuated wildly due to promotions and batch ordering. P&G's production planning overreacted, creating huge inventory costs. | Solution: information sharing \u2014 give upstream partners visibility into ACTUAL consumer demand, not your orders. | Also: stabilize pricing (no volume discounts that encourage batch ordering), smaller/faster replenishment cycles, and collaborative forecasting with suppliers.", "tags": ["operations", "supply-chain"], "order_index": 2}, {"name": "Demand Forecasting Methods", "definition": "Quantitative: time series (moving average, exponential smoothing, ARIMA), causal (regression, leading indicators). Qualitative: expert judgment, Delphi method, market research, sales force composite. Combine both for best results \u2014 quantitative baseline + qualitative adjustments.", "example": "Time series: 'Next month's demand = average of last 3 months \u00d7 seasonal factor.' Simple, reliable for stable products. | Causal: 'Demand for our product = 0.3 \u00d7 GDP growth + 0.5 \u00d7 competitor exits.' Useful when external factors drive demand. | Delphi method: 5 experts independently forecast, then see each other's anonymous forecasts, then revise. Repeats 2-3 rounds. Converges to a better forecast than any individual. | CEO test: ask your ops team 'what's our forecast accuracy for the last 12 months?' If they can't answer, you don't have forecasting \u2014 you have guessing.", "tags": ["operations", "forecasting"], "order_index": 3}] },
  { id: "a3000001-0000-4000-b000-000000000002", slug: "process-mining-optimization", title: "Process Mining & Optimization", description: "Use event log data to discover, analyze, and optimize actual business processes — see what REALLY happens, not what the process doc says", category: "operations", difficulty: 3, estimated_time_minutes: 25, key_concepts: ["Process Discovery from Event Logs", "Conformance Checking", "Bottleneck Identification"], use_cases: ["Operations optimization", "Compliance auditing", "Procure-to-pay analysis", "Order-to-cash optimization", "Customer journey mapping"], content: "", concepts: [{"name": "Process Discovery from Event Logs", "definition": "Every enterprise system generates event logs with timestamps. Process mining reconstructs the actual process: which activities happened, in what order, by whom, and how long each took. This is the REAL process, not the one in the SOP document.", "example": "Procure-to-pay: log shows 10,000 POs with timestamps for creation, approval, receipt, and payment. Mining reveals: average approval time is 4.3 days (not the '48 hours' in the SOP). 15% of POs skip the formal approval step (maverick buying). 3% take >30 days (outliers \u2014 investigate). | The process discovery shows the spaghetti diagram of actual process flow vs the 'happy path' in the SOP. | Tooling: Celonis, UiPath Process Mining, Apromore. Requires: event logs with case ID, activity name, and timestamp.", "tags": ["operations", "process-mining"], "order_index": 1}, {"name": "Conformance Checking", "definition": "Compare the discovered process to your documented SOP. Every deviation is either: 1) A compliance violation (fix it) 2) An undocumented improvement (document it) 3) A work-around for a broken process (fix the process).", "example": "SOP: every purchase order >$5k needs manager approval. Process mining discovers: 8% of POs >$5k have no approval record. Compliance gap \u2014 fix immediately. | SOP: customer refunds require 3-step approval. Mining discovers: top-performing CS reps do refund approvals in 1 step (bypassing the process) and have higher customer satisfaction. This isn't a violation \u2014 it's an improvement. Update the SOP. | 47 variants of 'how to close a deal' \u2014 most are random, 3 are consistently better. Standardize on the top 3, train everyone.", "tags": ["operations", "process-mining"], "order_index": 2}, {"name": "Bottleneck Identification", "definition": "Process mining shows waiting times BETWEEN activities (not activity durations). The bottleneck is usually not the slowest activity \u2014 it's the longest WAIT between activities. Look for cases sitting idle, waiting for a handoff.", "example": "Invoice processing: data entry takes 5 min, approval takes 10 min. But the invoice sits in the approver's queue for 3.2 DAYS (the bottleneck). The approval activity isn't slow \u2014 the queue is. Fix: auto-route to the first available approver, not a specific person. | Order-to-cash: manufacturing takes 2 weeks, shipping takes 3 days. But the order sits in 'credit check' for 5 days. Fix: automate credit check, parallelize with other steps. | Always ask: 'Where does the work WAIT?' That's your bottleneck. Adding capacity to a non-bottleneck just increases WIP and makes things slower.", "tags": ["operations", "process-mining"], "order_index": 3}] },
  { id: "a4000001-0000-4000-b000-000000000001", slug: "intellectual-property-strategy", title: "Intellectual Property Strategy", description: "Patents, trade secrets, trademarks, copyrights — build an IP moat that protects your innovation and creates licensing revenue streams", category: "innovation", difficulty: 3, estimated_time_minutes: 30, key_concepts: ["Patent Portfolio Strategy", "Trade Secret vs Patent Decision", "Freedom to Operate (FTO)"], use_cases: ["R&D protection", "Competitive moat building", "M&A IP diligence", "Open source strategy", "Revenue diversification through licensing"], content: "", concepts: [{"name": "Patent Portfolio Strategy", "definition": "Don't patent just your product \u2014 patent the PROBLEM SPACE. A good portfolio includes: core patents (your product), blocking patents (alternatives competitors might use), and surrounding patents (improvements, applications, methods). Build a fence, not a gate.", "example": "Dyson bagless vacuum: not just one patent \u2014 hundreds covering every aspect of cyclonic separation. Competitors couldn't get around the portfolio without infringing something. | Qualcomm: patents on CDMA technology, but ALSO patents on every feasible alternative. Even if you don't use their tech, you might still need their patents. Licensing revenue > product revenue. | Apple slide-to-unlock patent: they patented the SPECIFIC swipe gesture AND 'unlocking a device by performing a gesture on an image.' Broadest possible claim within the invention.", "tags": ["innovation", "ip"], "order_index": 1}, {"name": "Trade Secret vs Patent Decision", "definition": "Patent if: 1) the invention is easily reverse-engineered (you'll lose the secret anyway) 2) you want licensing revenue 3) the 20-year window is sufficient. Trade secret if: 1) it's difficult to reverse-engineer (manufacturing process, formula) 2) you can keep it secret (limited access) 3) indefinite protection matters more than a 20-year monopoly.", "example": "Patent: pharmaceutical compounds (easy to analyze once on the market). Trade secret: Coca-Cola formula (protected for 130+ years). | Patent: mechanical device (competitor can buy it and take it apart). Trade secret: manufacturing process known only to 3 engineers. | Hybrid: patent the product, keep the manufacturing process as a trade secret. Best of both worlds.", "tags": ["innovation", "ip"], "order_index": 2}, {"name": "Freedom to Operate (FTO)", "definition": "Before you launch a product in a new market, search existing patents to ensure you're not infringing. An FTO opinion from patent counsel says 'we've searched and found no blocking patents.' Without it, you're flying blind into potential lawsuits.", "example": "Startup launches ML product in the US. Large competitor sues for patent infringement. Startup's defense: 'We didn't know about the patent.' Judge: 'That's not a defense. You're liable for 3x damages for willful infringement.' | FTO search costs $10-50k depending on complexity. A patent lawsuit costs $2-5M to defend. FTO is insurance. | Also: FTO is geographic. You may have FTO in the US but not in Europe. Patent rights are territorial. | CEO rule: always get an FTO opinion before entering a new market with a new product. No exceptions.", "tags": ["innovation", "ip"], "order_index": 3}] },
  { id: "a4000001-0000-4000-b000-000000000002", slug: "open-innovation-corporate-venturing", title: "Open Innovation & Corporate Venturing", description: "Go beyond internal R&D: startup partnerships, corporate VC, innovation challenges, technology scouting — build an external innovation pipeline", category: "innovation", difficulty: 3, estimated_time_minutes: 30, key_concepts: ["Open Innovation Models", "Corporate Venture Capital (CVC)", "Innovation Scouting"], use_cases: ["Innovation portfolio expansion", "Digital transformation", "Startup acquisition pipeline", "Technology trend monitoring", "Cultural transformation toward innovation"], content: "", concepts: [{"name": "Open Innovation Models", "definition": "Inbound: bring external ideas IN (customer suggestions, university research, startup partnerships, competitor analysis). Outbound: send your unused IP OUT (license, spin-off, sell). P&G's target: 50% of innovation from external sources. Means: you need half the internal R&D budget.", "example": "P&G Connect + Develop: posted technology needs publicly ('we need a way to put edible images on Pringles'). A bakery in Spain had the solution. P&G licensed it. Product: Pringles Prints. In market in 12 months (vs 3 years internal). | Outbound: if you developed a technology that doesn't fit your strategy, license it rather than shelve it. IBM licenses its massive patent portfolio \u2014 $1B+/year in licensing revenue. | Open Innovation \u2260 no R&D. You still need internal R&D to ABSORB external innovation (absorptive capacity).", "tags": ["innovation", "open-innovation"], "order_index": 1}, {"name": "Corporate Venture Capital (CVC)", "definition": "Your company invests directly in external startups. Strategic objectives (not just financial): 1) Window on technology 2) Option to acquire 3) Ecosystem development 4) Financial return (least important). Research shows CVCs with primarily financial objectives underperform; strategic CVCs outperform.", "example": "Google Ventures (GV): invested in Uber ($258M), Nest (acquired for $3.2B), and hundreds of others. Strategic window on emerging tech + financial returns. | Intel Capital: invested billions in semiconductor startups. Strategic: ensure ecosystem grows around Intel's platform. Financial: $2B+ in returns. | Best practice: CVC team must be separate from corporate strategy team (speed matters \u2014 startups can't wait 6 months for your corporate approval). But must have a CONNECTION to business units so partnerships actually happen.", "tags": ["innovation", "cvc"], "order_index": 2}, {"name": "Innovation Scouting", "definition": "Station scouts in tech hubs to find startups BEFORE they're on your M&A team's radar. Scouts attend demo days, hackathons, meetups. They build relationships with founders 12-24 months before any deal.", "example": "BMW Startup Garage: scouts in Silicon Valley, Tel Aviv, Shanghai, Munich. Found early-stage lidar startup, partnered on proof of concept, eventually acquired. BMW had the relationship for 18 months before the acquisition \u2014 much better diligence than a cold deal. | Scout profile: technical enough to evaluate the technology, business-savvy enough to assess the business model, and independent enough to say 'this isn't ready for us.' | Scout's mandate: 'Find us the 5 most interesting startups in [domain] this quarter.' Not 'find us acquisition targets.' Broader search, better results.", "tags": ["innovation", "scouting"], "order_index": 3}] },
  { id: "a5000001-0000-4000-b000-000000000001", slug: "multi-party-coalition-negotiation", title: "Multi-Party Negotiation & Coalition Building", description: "Negotiate with 5+ parties, build winning coalitions, manage alliances, and navigate complex stakeholder dynamics", category: "negotiation", difficulty: 3, estimated_time_minutes: 30, key_concepts: ["Coalition Formation Strategy", "Minimum Winning Coalition", "Multi-Party Agenda Setting"], use_cases: ["Board negotiations", "Multi-vendor deals", "Cross-department resource allocation", "International partnerships", "Regulatory settlement negotiations"], content: "", concepts: [{"name": "Coalition Formation Strategy", "definition": "Map all parties on ISSUES (what they want) and LEVERAGE (what they can do about it). Form a coalition of parties whose interests are compatible. Start with the easiest supporter and build outward \u2014 momentum attracts fence-sitters.", "example": "Board negotiation: 5 directors. You need 3 votes. Two are allies (always support you), two are skeptics, one is neutral. Strategy: present to allies first (lock them in). Then present to neutral with their feedback incorporated. Now you have 3 votes \u2014 decision made. Skeptics informed, not consulted. | Union negotiation: 3 unions, each with different priorities. Union A cares about wages, B about benefits, C about job security. Package a deal that gives each their top priority. Don't try to satisfy all 3 on all issues.", "tags": ["negotiation", "multi-party"], "order_index": 1}, {"name": "Minimum Winning Coalition", "definition": "Don't try to satisfy everyone. Identify the MINIMUM number of parties needed to reach agreement, build a coalition with them, and get the deal done. Adding more parties beyond the minimum introduces more demands without adding value.", "example": "Corporate restructuring: 5 creditor groups. Bankruptcy law requires 2/3 of each class to approve. Class A = 8 banks (need 6). Approach the 3 largest first (they hold 60% of the debt). Get their consent. Then the remaining banks fall in line. Don't negotiate with all 8 simultaneously. | UN Security Council: 5 permanent members with veto power. You need at least 9 of 15 votes AND no veto. Strategy: secure all 5 permanent members first (eliminate veto risk), then lobby the 10 rotating members for the remaining 4 votes. Minimum winning coalition = 9 members including all 5 permanents.", "tags": ["negotiation", "multi-party"], "order_index": 2}, {"name": "Multi-Party Agenda Setting", "definition": "Control the sequence of negotiations: who gets approached first, which issues get discussed when, and what's the deadline. Early wins create momentum; early concessions create expectations of weakness. Frame the issue in a way that favors your coalition.", "example": "International climate negotiations: host country controls the agenda. They set the topic order (emissions first, finance second), decide who speaks when, and draft the initial text. Whoever writes the first draft controls 80% of the final outcome. | Corporate M&A with multiple bidders: you're the seller. Set the process \u2014 sealed bids by Friday, best-and-final offers only, no 'topping' after winner selected. Control the rules, control the outcome. | Internal: mediating between Sales and Engineering on resource allocation. Set the agenda: 'Let's first agree on WHAT we're trying to achieve, then discuss HOW.' The shared goal framing reduces positional negotiation.", "tags": ["negotiation", "multi-party"], "order_index": 3}] },
  { id: "b2000001-0000-4000-b000-000000000001", slug: "quantitative-risk-assessment", title: "Quantitative Risk Assessment (QRA)", description: "Monte Carlo for risk, VaR/CVaR, probability distributions, risk matrices, and expected loss modeling — quantify risk, don\'t just list it", category: "risk", difficulty: 3, estimated_time_minutes: 35, key_concepts: ["Risk Matrix (Likelihood \u00d7 Impact)", "Value at Risk (VaR) & CVaR", "Risk Appetite Statements"], use_cases: ["Enterprise risk quantification", "Capital reserve sizing", "Insurance coverage decisions", "Board risk reporting", "Investment risk analysis"], content: "", concepts: [{"name": "Risk Matrix (Likelihood \u00d7 Impact)", "definition": "Plot every risk on a 5\u00d75 grid: Likelihood (Almost Certain to Rare) \u00d7 Impact (Insignificant to Catastrophic). The top-right quadrant (high likelihood, high impact) gets immediate attention. Simple, visual, but beware: different risks with the same 'score' can have very different distributions.", "example": "Quadrant I (High/High): ransomware attack, supply chain collapse. Mitigate with insurance, redundancy. | Quadrant II (Low/High): earthquake destroys HQ. Low probability, catastrophic impact. Transfer through insurance. | Quadrant III (High/Low): minor IT incidents. Accept or mitigate with process improvements. | Quadrant IV (Low/Low): paper clip shortage. Accept and move on. | Limitation: a '3\u00d73=9' risk and a '9\u00d71=9' risk look identical in a matrix but are fundamentally different (one is moderate on both, one is catastrophic but rare). Complement matrices with quantitative analysis.", "tags": ["risk", "assessment"], "order_index": 1}, {"name": "Value at Risk (VaR) & CVaR", "definition": "VaR(95%) = $10M means 'in 95% of scenarios, we lose \u2264$10M.' CVaR answers: 'in the 5% of scenarios where we DO exceed $10M, what's our average loss?' CVaR is usually 20-50% higher than VaR. Always report both.", "example": "Portfolio: VaR(95%) = $5M. Board thinks: '$5M worst case, manageable.' But CVaR(95%) = $12M. 'When things go bad, they go REALLY bad.' This changes the insurance decision. | Project: 3 months (best), 6 months (expected), 9 months (VaR 95%), 14 months (CVaR 95%). The CVaR tail is the 'oh no' scenario \u2014 plan contingencies for this, not the expected case. | Regulatory: Basel III requires banks to calculate both VaR (for market risk capital) and stressed VaR. Corporations should adopt the same discipline.", "tags": ["risk", "quantitative"], "order_index": 2}, {"name": "Risk Appetite Statements", "definition": "A board-approved document declaring: 1) How much risk the company is willing to take 2) In what areas 3) Measured how 4) With what limits. Not 'we're risk-aware' \u2014 specific thresholds that trigger action.", "example": "Risk appetite: 'We accept up to $2M in uncovered operational risk per year. We will not accept any single risk that could reduce liquidity below $10M. We accept cybersecurity risk up to the point of a data breach affecting more than 50,000 customers.' | Risk tolerance (narrower): 'For customer data breach risk, we tolerate a maximum 10% annual probability of an event exceeding $1M.' | Every material risk should have an appetite statement. Without one, the organization doesn't know when to escalate, and risk management is reactive.", "tags": ["risk", "governance"], "order_index": 3}] },
  { id: "b2000001-0000-4000-b000-000000000002", slug: "insurance-risk-transfer", title: "Insurance & Risk Transfer", description: "Captive insurance, self-insurance, parametric policies, reinsurance, and hedging — transfer risk systematically, not just buy insurance", category: "risk", difficulty: 3, estimated_time_minutes: 30, key_concepts: ["Risk Transfer Spectrum", "Captive Insurance", "Parametric Insurance"], use_cases: ["Insurance program design", "Captive feasibility", "Self-insurance decisions", "M&A risk allocation", "Supply chain risk transfer"], content: "", concepts: [{"name": "Risk Transfer Spectrum", "definition": "Not all risks need insurance. Decision framework: 1) Can we RETAIN this risk? (low severity, predictable) 2) Can we MITIGATE it? (reduce probability or impact) 3) Can we CONTRACTUALLY transfer it? (indemnification from partners) 4) Should we INSURE it? (catastrophic, unpredictable) 5) Should we HEDGE it? (financial market risks).", "example": "Risk: office laptop theft. Frequency: 5/year. Severity: $2k each. Total: $10k/year. Retain \u2014 self-insure. Premium would be $15k (insurer adds admin + profit). | Risk: class action lawsuit. Severity: $50M+. Insure (D&O/E&O). Can't retain this. | Risk: FX exposure on \u20ac5M revenue. Hedge with forward contracts. Cheaper and more direct than insurance. | Risk: supplier failure. Contractual transfer: require supplier to carry business interruption insurance naming you as beneficiary. Don't insure their failure yourself.", "tags": ["risk", "insurance"], "order_index": 1}, {"name": "Captive Insurance", "definition": "A wholly-owned insurance subsidiary that insures the parent company. Advantages: 1) Keep underwriting profits (don't pay them to a commercial insurer) 2) Cover risks the market won't touch 3) Tax benefits (premiums paid to captive are tax-deductible, captive's reserves grow tax-advantaged). Typically makes sense at $1M+ in annual premiums.", "example": "Fortune 500 captives: 90% of Fortune 500 have captive insurers. Shell, BP, and others use captives to cover environmental liability, political risk, and supply chain risks that commercial markets either won't cover or charge extreme premiums for. | Mid-market captive: company paying $800k/year in premiums. Form a captive in Vermont or Bermuda. Captive issues policies, parent pays premiums to captive. Captive invests reserves. Underwriting profits stay in the group. | Feasibility test: premiums > $1M, predictable loss history, management bandwidth to run the captive. If premiums < $500k, the administrative overhead exceeds the benefit.", "tags": ["risk", "insurance"], "order_index": 2}, {"name": "Parametric Insurance", "definition": "Pays out automatically when a predefined trigger is met \u2014 no loss assessment, no claims adjuster, no dispute. Example: 'If hurricane wind speed exceeds 120mph at our location, pay $5M within 48 hours.' Faster and more certain than traditional indemnity insurance.", "example": "Caribbean hotel: traditional hurricane insurance takes 6-18 months to settle (assessing damage, negotiating). Parametric: buys policy that pays $2M if sustained wind speed exceeds 100mph at the hotel. Hurricane hits at 115mph \u2192 $2M wired within 48 hours. | Agriculture: farmer buys policy that pays if rainfall drops below 10 inches during growing season (measured at nearby weather station). No need to prove crop damage. | Limitation: basis risk \u2014 the trigger may not perfectly match your actual loss. Wind speed at the weather station \u2260 wind speed at YOUR property. Acceptable imperfection for fast payout.", "tags": ["risk", "insurance"], "order_index": 3}] },
  { id: "b2000001-0000-4000-b000-000000000003", slug: "cyber-risk-framework", title: "Cyber Risk Management Framework", description: "NIST CSF, breach quantification, ransomware readiness, third-party risk — a CEO-level cyber risk program for the boardroom", category: "risk", difficulty: 3, estimated_time_minutes: 35, key_concepts: ["NIST Cybersecurity Framework", "FAIR Model (Breach Quantification)", "Ransomware Readiness"], use_cases: ["Cyber program design", "Board cyber reporting", "Breach preparedness", "Regulatory compliance", "M&A cyber diligence", "CISO reporting structure"], content: "", concepts: [{"name": "NIST Cybersecurity Framework", "definition": "Five functions: IDENTIFY (asset management, risk assessment, governance), PROTECT (access control, training, data security), DETECT (anomalies, continuous monitoring), RESPOND (response planning, communications, analysis), RECOVER (recovery planning, improvements, communications).", "example": "NIST CSF maturity model: Tier 1 (Partial) \u2014 ad-hoc, reactive. Tier 2 (Risk-Informed) \u2014 management approved, not organization-wide. Tier 3 (Repeatable) \u2014 formal policy, regularly updated. Tier 4 (Adaptive) \u2014 continuous improvement, lessons learned from incidents, external threat intelligence integration. | Board reporting: 'We're at NIST Tier 2, targeting Tier 3 within 12 months.' Clear, benchmarked, credible. | Adoption: US federal agencies are mandated to use NIST CSF. Private sector adoption is increasing as boards expect structured cyber governance.", "tags": ["risk", "cyber"], "order_index": 1}, {"name": "FAIR Model (Breach Quantification)", "definition": "Factor Analysis of Information Risk: the standard for quantifying cyber risk in dollars. Loss Event Frequency \u00d7 Loss Magnitude = Annualized Loss Expectancy (ALE). Turns 'our cyber risk is high' into 'our cyber risk is $3.2M/year expected loss.'", "example": "Scenario: ransomware attack on customer database. Loss Event Frequency: 0.15 (15% chance/year). Loss Magnitude: P10=$1M, P50=$4M, P90=$12M. ALE = 0.15 \u00d7 $4M = $600k/year. | Cost of mitigation: $200k/year for improved backup + $100k for training = $300k/year. ROI = ($600k - $300k)/$300k = 100%. Clear investment case. | Board question: 'Should we pay for cyber insurance?' Run FAIR analysis with and without insurance. Show the risk reduction for $150k premium. FAIR makes cyber risk a business conversation, not a technical one.", "tags": ["risk", "cyber"], "order_index": 2}, {"name": "Ransomware Readiness", "definition": "The single most likely cyber event for most companies. Readiness: 1) Immutable backups (3-2-1 rule) 2) Offline backup that ransomware can't reach 3) Pre-negotiated incident response firm on retainer 4) Ransom payment decision framework (board-approved policy BEFORE you're hit) 5) Tabletop exercise quarterly.", "example": "3-2-1 backup: 3 copies of critical data, 2 different media types (disk + tape), 1 copy offsite (air-gapped, not reachable from the network). Ransomware can't encrypt tapes on a shelf. | Ransom payment policy: 'We will not pay ransoms' \u2014 sounds principled, but what if the alternative is 4 weeks of downtime at $2M/week? Pre-decide with board. | Incident response retainer: firms like CrowdStrike, Mandiant, or Unit 42 on annual retainer ($50-100k/year). They respond within hours, negotiate with attackers if needed, handle forensics. You don't want to be googling 'ransomware response firm' during an incident.", "tags": ["risk", "cyber"], "order_index": 3}] },
  { id: "b2000001-0000-4000-b000-000000000004", slug: "geopolitical-risk-analysis", title: "Geopolitical Risk Analysis", description: "Assess country risk, sanctions exposure, supply chain geography, political instability — protect your business from the world\'s volatility", category: "risk", difficulty: 3, estimated_time_minutes: 30, key_concepts: ["Country Risk Assessment", "Sanctions & Export Controls", "Supply Chain Geopolitical Mapping"], use_cases: ["International expansion", "Supply chain diversification", "Sanctions compliance", "Investment decisions", "Crisis preparedness"], content: "", concepts: [{"name": "Country Risk Assessment", "definition": "Evaluate every country in your footprint on: Political (regime stability, corruption, rule of law), Economic (currency volatility, inflation, debt levels), Social (labor unrest, demographic trends), Technology (infrastructure, IP protection), Environmental (climate vulnerability), Legal (regulatory predictability, contract enforcement).", "example": "Vietnam expansion: political stability (good), economic growth (strong, 6-8% GDP), IP protection (moderate \u2014 improving but weaker than US/EU), infrastructure (ports good, inland logistics challenging). Overall: invest, but with local partner for regulatory navigation. | Russia post-2022: political risk (extreme \u2014 sanctions, unpredictability), economic (volatile), legal (no effective contract enforcement with Western companies). Assessment: exit or dramatically reduce exposure. | Use external ratings (World Bank Governance Indicators, Transparency International CPI, S&P Country Risk) as baselines, then add company-specific factors.", "tags": ["risk", "geopolitical"], "order_index": 1}, {"name": "Sanctions & Export Controls", "definition": "US sanctions (OFAC), EU sanctions, UN sanctions \u2014 different lists, different rules. Know which apply to you based on: 1) Your jurisdiction 2) Your customers' locations 3) Your products (dual-use technology needs export license). Violating sanctions is criminal, not civil. Penalties can include prison for executives.", "example": "OFAC SDN list: you cannot transact with Specially Designated Nationals. This includes entities owned 50%+ by an SDN (even if the entity itself isn't on the list). | Export controls: selling encryption software to certain countries requires BIS license. Your SaaS product may be 'exported' when a user in a sanctioned country downloads it. Geolocation blocking is not optional \u2014 it's mandatory. | M&A red flag: acquired a company with customers in Iran (sanctions violation). You inherit the liability. Always include sanctions screening in M&A diligence.", "tags": ["risk", "geopolitical"], "order_index": 2}, {"name": "Supply Chain Geopolitical Mapping", "definition": "Map every Tier 1-2 supplier by country and sub-region. Identify geographic concentration: 'We have 3 suppliers \u2014 all in Taiwan.' Overlay with geopolitical risk: China-Taiwan tensions, South China Sea shipping lanes, semiconductor foundry concentration.", "example": "Semiconductor supply chain mapping: design (US, UK, Israel), fabrication (Taiwan 63%, South Korea 18%, China 6%), packaging (Taiwan, China, Malaysia). Any disruption in the Taiwan Strait \u2192 63% of advanced chip production stops. Mitigate: TSMC building fabs in Arizona, Japan, and Germany (diversification). | Apparel supply chain: Vietnam 40%, Bangladesh 30%, China 30%. Map exposed to climate (Bangladesh floods), labor (Vietnam minimum wage increases), logistics (Suez Canal for EU shipments from Asia). | Strategy: no single country >30% of supply for critical components.", "tags": ["risk", "geopolitical"], "order_index": 3}] },
  { id: "b2000001-0000-4000-b000-000000000005", slug: "financial-risk-management", title: "Financial Risk Management (Treasury)", description: "FX hedging, interest rate exposure, commodity price risk, counterparty credit risk — the CFO\'s toolkit, overseen by the CEO", category: "risk", difficulty: 3, estimated_time_minutes: 30, key_concepts: ["FX Hedging Strategies", "Counterparty Credit Risk", "Treasury Policy Design"], use_cases: ["FX exposure management", "Debt structure decisions", "Bank relationship management", "Cash management across currencies", "Board treasury reporting"], content: "", concepts: [{"name": "FX Hedging Strategies", "definition": "Natural hedge: match revenues and costs in the same currency (pay European employees in euros, not dollars). Forward contracts: lock in today's rate for future currency needs. Options: pay a premium for the right (not obligation) to exchange at a specific rate. Layered hedging: hedge 50-70% of expected exposure, leave rest to benefit from favorable moves.", "example": "US company with \u20ac10M annual revenue. If EUR/USD drops from 1.10 to 0.95, revenue drops from $11M to $9.5M. Forward hedge: lock in 1.10 for \u20ac8M (80% of exposure). Rate drops to 0.95: \u20ac8M converts at $8.8M (protected), remaining \u20ac2M at $1.9M. Total: $10.7M. Protected $1.2M of potential loss. | Natural hedge: open European office, pay European employees in euros. Revenue and costs are now matched in EUR \u2014 no conversion needed. Cheapest hedge. | Board reporting: 'We've hedged 70% of our 12-month FX exposure. The unhedged 30% could swing earnings \u00b1$500k.' Transparency.", "tags": ["risk", "financial"], "order_index": 1}, {"name": "Counterparty Credit Risk", "definition": "When you deposit money in a bank or enter a derivative contract, you're exposed to that counterparty's creditworthiness. If they fail, you lose your deposit or your hedge. Manage by diversifying counterparties, monitoring their credit ratings, and using collateral agreements (CSA for derivatives).", "example": "SVB collapse 2023: thousands of startups had 100% of their cash at Silicon Valley Bank. When it failed, they couldn't make payroll. Lesson: diversify. | Diversification rule: no single bank should hold >25% of total cash. At least one bank should be systemically important (too-big-to-fail). | Derivatives: when you hedge FX with a forward contract, the bank's obligation to pay you is only as good as that bank. Use multiple banks for large hedges. | Credit Support Annex (CSA): the derivative counterparty posts collateral if their credit rating drops. Protects you.", "tags": ["risk", "financial"], "order_index": 2}, {"name": "Treasury Policy Design", "definition": "A board-approved document governing: 1) Which financial risks is the company willing/not willing to take? 2) How are those risks measured? 3) What hedging limits and instruments are permitted? 4) Who has authority to execute hedges? 5) How is compliance monitored? Prevents rogue trading and ensures alignment with risk appetite.", "example": "Treasury policy statement: 'The company will hedge 50-80% of forecasted FX exposure for the next 12 months using only plain vanilla forward contracts and purchased options. No speculative positions. No structured products. No leverage. All hedges pre-approved by CFO.' | Rogue trader prevention: Barings Bank was destroyed by a single trader (Nick Leeson) taking unauthorized derivatives positions. Policy + segregation of duties (trader \u2260 settlement) + monitoring prevents this. | Quarterly board report: treasury compliance with policy, outstanding hedges, value-at-risk of unhedged positions, counterparty exposure by bank.", "tags": ["risk", "financial"], "order_index": 3}] },
]

